window.FLASHCARDS = [{"id": "单1", "ch": "导论", "type": "单选", "page": "P4", "q": "马克思主义产生于19世纪40年代", "qh": "马克思主义产生于<span class=\"rd\">【19世纪40年代】</span><span class=\"pg\">P4</span>", "a": "马克思主义产生于19世纪40年代，创始人是马克思和恩格斯。马克思主义的产生具有深刻的社会根源、阶级基础和思想渊源。"}, {"id": "单2", "ch": "导论", "type": "单选", "page": "P5", "q": "直接理论来源与自然科学前提", "qh": "<span class=\"rd\">【德国古典哲学、英国古典政治经济学（代表人物：斯密、李嘉图）、英法空想社会主义】</span>为马克思主义的创立提供了直接的理论来源。19世纪的三大科学发现，即<span class=\"rd\">【细胞学说、能量守恒与转化定律、生物进</span><span class=\"rd\">化论】</span>为马克思主义的产生提供了自然科学前提<span class=\"pg\">P5</span>", "a": "德国古典哲学、英国古典政治经济学、英法空想社会主义为马克思主义的创立提供了直接的理论来源；19世纪的三大科学发现，即细胞学说、能量守恒与转化定律、生物进化论，为马克思主义的产生提供了自然科学前提。（英国古典政治经济学代表人物：斯密、李嘉图）"}, {"id": "单3", "ch": "导论", "type": "单选", "page": "P7", "q": "世界上第一个无产阶级政党的党纲", "qh": "世界上第一个无产阶级政党(共产主义者同盟)的党纲——<span class=\"rd\">【《共产党宣言》】</span><span class=\"pg\">P7</span>", "a": "马克思、恩格斯接受国际性工人组织\"正义者同盟\"的邀请，将其改组为\"共产主义者同盟\"，并为其起草了世界上第一个无产阶级政党的党纲——《共产党宣言》。1848年2月《共产党宣言》发表，标志着马克思主义的公开问世。"}, {"id": "单4", "ch": "导论", "type": "单选", "page": "P9", "q": "列宁\"一国或数国首先胜利\"论断", "qh": "列宁深刻分析了19世纪末20世纪初世界历史条件的变化，认为<span class=\"rd\">【资本主义经济政治发展的不平衡已成</span><span class=\"rd\">为资本主义发展的绝对规律】</span>，提出了社会主义革命可能在一国或数国首先发生并取得胜利的论断。<span class=\"pg\">P9</span>", "a": "列宁深刻分析了19世纪末20世纪初世界历史条件的变化，认为资本主义发达国家已经发展到帝国主义阶段，经济政治发展的不平衡已成为资本主义发展的绝对规律；由此提出了社会主义革命可能在一国或数国首先发生并取得胜利的论断。"}, {"id": "单5", "ch": "导论", "type": "单选", "page": "P13-16", "q": "马克思主义的基本特征", "qh": "马克思主义的基本特征：包括<span class=\"rd\">【科学性、人民性、实践性、发展性】</span>，用一句话概括为<span class=\"rd\">【科学性与革命</span><span class=\"rd\">性的统一】</span><span class=\"pg\">P13-16</span>(1)<span class=\"rd\">【人民性】</span>是马克思主义的本质属性。人民至上是马克思主义的政治立场(2)<span class=\"rd\">【实践观点】</span>是马克思主义首要的和基本的观点(3)马克思主义具有<span class=\"rd\">【与时俱进】</span>的理论品质", "a": "马克思主义具有鲜明的科学性、人民性、实践性、发展性。（1）人民性是马克思主义的本质属性，人民至上是马克思主义的政治立场；（2）实践观点是马克思主义首要的和基本的观点；（3）马克思主义是不断发展的开放的学说，具有与时俱进的理论品质；（4）概括为科学性与革命性的统一——马克思主义\"把严格的和高度的科学性同革命性结合起来\"。"}, {"id": "单6", "ch": "导论", "type": "单选", "page": "P16-20", "q": "马克思主义的当代价值", "qh": "马克思主义的当代价值：<span class=\"rd\">【观察当代世界变化的认识工具；指引当代中国发展的行动指南；引领人类社</span><span class=\"rd\">会进步的科学真理】</span><span class=\"pg\">P16-20</span>", "a": "马克思主义的当代价值体现在三个方面：（一）观察当代世界变化的认识工具；（二）指引当代中国发展的行动指南；（三）引领人类社会进步的科学真理。"}, {"id": "简1", "ch": "导论", "type": "简答", "page": "P2", "q": "什么是马克思主义？", "qh": "什么是马克思主义？<span class=\"pg\">P2</span>", "a": "马克思主义是由马克思、恩格斯创立并为后继者所不断发展的科学理论体系，是关于自然、社会和人类思维发展一般规律的学说，是关于社会主义必然代替资本主义、最终实现共产主义的学说，是关于无产阶级解放、全人类解放和每个人自由而全面发展的学说，是无产阶级政党和社会主义国家的指导思想，是指引人民创造美好生活的行动指南。马克思主义哲学、马克思主义政治经济学和科学社会主义是其三个基本组成部分。", "o": "马克思主义是<span class=\"rd\">由马克思、恩格斯创立</span>并为后继者所不断发展的科学理论体系，是关于自然、社会和人类思维发展一般规律的学说，是关于社会主义必然代替资本主义、最终实现共产主义的学说，是关于无产阶级解放、全人类解放和每个人自由而全面发展的学说，是无产阶级政党和社会主义国家的指导思想，是指引人民创造美好生活的行动指南"}, {"id": "单7", "ch": "第一章 世界的物质性及发展规律", "type": "单选", "page": "P26", "q": "世界观", "qh": "人对世界有一个总体的看法和把握，这就是人的<span class=\"rd\">【世界观】</span>问题<span class=\"pg\">P26</span>", "a": "人生活在世界上，需要对世界有一个总体的看法和把握，这就是人的世界观问题。哲学是系统化、理论化的世界观。"}, {"id": "单8", "ch": "第一章 世界的物质性及发展规律", "type": "单选", "page": "P26-27", "q": "哲学基本问题", "qh": "<span class=\"rd\">【存在和思维的关系问题又称为物质和意识的关系问题】</span>构成了全部哲学的基本问题。哲学基本问题主要包括两方面内容：<span class=\"pg\">P26-27</span>(1)<span class=\"rd\">【存在和思维、物质和意识谁为本原的问题，即何者为第一性的问题】</span>；对这一问题的不同回答形成了<span class=\"rd\">【唯物主义和唯心主义】</span>(2)<span class=\"rd\">【存在和思维、物质和意识是否具有同一性的问题】</span>，即思维能否正确地反映存在、人能否认识或彻底认识世界的问题；对这一问题的不同回答产生了<span class=\"rd\">【可知论和不可知论】</span>", "a": "存在和思维的关系问题又称为物质和意识的关系问题，构成了全部哲学的基本问题。包括两方面：一是存在和思维、物质和意识谁为本原即何者为第一性的问题，形成唯物主义和唯心主义；二是二者是否具有同一性的问题，产生可知论和不可知论。"}, {"id": "单9", "ch": "第一章 世界的物质性及发展规律", "type": "单选", "page": "P29", "q": "物质的唯一特性", "qh": "马克思主义的物质观认为<span class=\"rd\">【客观实在性】</span>是物质的唯一特性<span class=\"pg\">P29</span>", "a": "马克思主义的物质观认为，客观实在性是物质的唯一特性，这既肯定了哲学物质范畴同自然科学物质结构理论的联系，又把它们区别开来。"}, {"id": "单10", "ch": "第一章 世界的物质性及发展规律", "type": "单选", "page": "P30", "q": "物质的根本属性是运动", "qh": "物质的根本属性是<span class=\"rd\">【运动】</span>。<span class=\"rd\">【运动】</span>是标志一切事物和现象的变化及其过程的哲学范畴<span class=\"pg\">P30</span>", "a": "物质的根本属性是运动。运动是标志一切事物和现象的变化及其过程的哲学范畴。物质和运动不可分割，运动是物质的运动，物质是运动着的物质。"}, {"id": "单11", "ch": "第一章 世界的物质性及发展规律", "type": "单选", "page": "P30", "q": "相对静止的两种状态", "qh": "相对静止具体包括两种状态：<span class=\"rd\">【空间的相对位置暂时不变和事物的根本性质暂时不变】</span><span class=\"pg\">P30</span>", "a": "相对静止是物质运动在一定条件下的稳定状态，具体包括两种状态：空间的相对位置暂时不变和事物的根本性质暂时不变。"}, {"id": "单12", "ch": "第一章 世界的物质性及发展规律", "type": "单选", "page": "P31", "q": "绝对运动与相对静止", "qh": "无条件的<span class=\"rd\">【绝对运动】</span>和有条件的<span class=\"rd\">【相对静止】</span>构成了对立统一的关系<span class=\"pg\">P31</span>", "a": "无条件的绝对运动和有条件的相对静止构成了对立统一的关系。运动和静止相互依赖、相互渗透、相互包含，\"动中有静、静中有动\"。"}, {"id": "单13", "ch": "第一章 世界的物质性及发展规律", "type": "单选", "page": "P31", "q": "时间和空间", "qh": "<span class=\"rd\">【时间和空间】</span>是运动着的物质的基本存在形式<span class=\"pg\">P31</span>(1)时间指物质运动的持续性、顺序性，特点是<span class=\"rd\">【一维性(时间一去不复返)】</span>(2)空间指物质运动的广延性、伸张性，特点是<span class=\"rd\">【三维性(长、宽、高)】</span>", "a": "时间和空间是运动着的物质的基本存在形式。时间指物质运动的持续性、顺序性，特点是一维性（一去不复返）；空间指物质运动的广延性、伸张性，特点是三维性（长、宽、高）。"}, {"id": "单14", "ch": "第一章 世界的物质性及发展规律", "type": "单选", "page": "P31", "q": "物质世界的二重化", "qh": "物质世界的二重化：<span class=\"rd\">【从自然界中分化出人类社会，从客观世界中分化出主观世界】</span><span class=\"pg\">P31</span>", "a": "人类的出现特别是人类改造世界的实践活动，使世界发生了二重分化，即从自然界中分化出人类社会，从客观世界中分化出主观世界。"}, {"id": "单15", "ch": "第一章 世界的物质性及发展规律", "type": "单选", "page": "P39-40", "q": "世界的物质统一性原理", "qh": "世界的物质统一性原理<span class=\"pg\">P39-40</span>(1)马克思主义认为，世界的统一性在于它的物质性，世界统一于物质：<span class=\"rd\">【自然界是物质的；人类社会本质</span><span class=\"rd\">上是生产实践基础上形成的物质体系；人的意识统一于物质】</span>(2)现实意义：世界的物质统一性原理是辩证唯物主义最基本、最核心的观点，是马克思主义的基石。有助于树立唯物主义科学世界观，为进一步确立正确的人生观和价值观奠定坚实的基础。有助于确立正确的思想路线和思想方法，在认识世界和改造世界中，遵循一切从实际出发、实事求是的原则。一切从实际出发是在坚持和发展中国特色社会主义伟大实践中想问题、办事情的根本立足点", "a": "\"世界的真正的统一性在于它的物质性\"——自然界是物质的，人类社会本质上是生产实践基础上形成的物质体系，人的意识统一于物质。世界的物质统一性原理是辩证唯物主义最基本、最核心的观点，是马克思主义的基石；有助于树立唯物主义科学世界观，有助于确立正确的思想路线和思想方法，遵循一切从实际出发、实事求是的原则。"}, {"id": "单16", "ch": "第一章 世界的物质性及发展规律", "type": "单选", "page": "P41-43", "q": "联系和发展的观点；发展的实质", "qh": "<span class=\"rd\">【联系和发展的观点】</span>是唯物辩证法的总观点、总特征。发展的实质是<span class=\"rd\">【新事物的产生和旧事物的灭</span><span class=\"rd\">亡】</span><span class=\"pg\">P41-43</span>", "a": "联系和发展的观点是唯物辩证法的总观点、总特征。物质世界的发展特别是人类社会的发展，其实质是新事物的产生和旧事物的灭亡；新事物是指合乎历史前进方向、具有远大前途的东西。"}, {"id": "单17", "ch": "第一章 世界的物质性及发展规律", "type": "单选", "page": "P44", "q": "唯物辩证法的三大规律", "qh": "唯物辩证法揭示了事物变化发展的一般规律，即<span class=\"rd\">【对立统一规律(是根本规律)、量变质变规律和否定</span><span class=\"rd\">之否定规律】</span><span class=\"pg\">P44</span>", "a": "对立统一规律、量变质变规律、否定之否定规律是事物变化发展的一般规律，其中对立统一规律是根本规律（唯物辩证法的实质和核心）。"}, {"id": "单18", "ch": "第一章 世界的物质性及发展规律", "type": "单选", "page": "P44-45", "q": "矛盾的两种基本属性", "qh": "矛盾的两种基本属性：<span class=\"rd\">【对立(即斗争性)；统一(即同一性)】</span><span class=\"pg\">P44-45</span>(1)矛盾的同一性指矛盾着的对立面相互依存、相互贯通的性质和趋势(2)矛盾的斗争性是矛盾着的对立面相互排斥、相互分离的性质和趋势。斗争性在事物发展中的作用：<span class=\"rd\">【促</span><span class=\"rd\">进矛盾双方力量的变化，造成双方力量发展的不平衡，为对立面的转化、事物的质变创造条件；是一种矛</span><span class=\"rd\">盾统一体向另一种矛盾统一体过渡的决定性力量】</span>(3)矛盾的同一性和斗争性<span class=\"rd\">【相互联结、相辅相成】</span>。没有斗争性就没有同一性，没有同一性也没有斗争性；斗争性寓于同一性之中，同一性通过斗争性来体现。矛盾的同一性是<span class=\"rd\">【有条件的、相对的】</span>，矛盾的斗争性是<span class=\"rd\">【无条件的、绝对的】</span>。矛盾的同一性和斗争性相结合，构成了事物的矛盾运动，推动着事物的变化发展。二者的辩证关系原理要求我们在观察和处理问题时，必须善于把二者结合起来，在斗争性中把握同一性，在同一性中把握斗争性", "a": "对立（斗争性）和统一（同一性）分别体现了矛盾的两种基本属性。同一性是矛盾着的对立面相互依存、相互贯通的性质和趋势；斗争性是相互排斥、相互分离的性质和趋势，其作用在于促进矛盾双方力量变化、为质变创造条件，是一种矛盾统一体向另一种矛盾统一体过渡的决定性力量。二者相互联结、相辅相成，斗争性寓于同一性之中；同一性是有条件的、相对的，斗争性是无条件的、绝对的。"}, {"id": "单19", "ch": "第一章 世界的物质性及发展规律", "type": "单选", "page": "P50", "q": "否定之否定规律的基本内容", "qh": "否定之否定规律的基本内容：事物的辩证否定不是一次完成的，而是经历<span class=\"rd\">【事物自我发展的两次否定，</span><span class=\"rd\">三个阶段，即“肯定—否定—否定之否定”】</span>的有规律的过程。事物的发展呈现出周期性，不同周期的交替使事物的发展呈现出波浪式前进或螺旋式上升的总趋势<span class=\"pg\">P50</span>", "a": "事物的辩证否定经历事物自我发展的两次否定、三个阶段，即\"肯定—否定—否定之否定\"。事物的发展呈现出周期性，不同周期的交替使事物的发展呈现出波浪式前进或螺旋式上升的总趋势。"}, {"id": "单20", "ch": "第一章 世界的物质性及发展规律", "type": "单选", "page": "P50", "q": "前进性与曲折性的统一", "qh": "否定之否定规律揭示了事物发展的<span class=\"rd\">【前进性与曲折性】</span>的统一：<span class=\"pg\">P50</span>(1)原理：前进性体现在每一次否定都是质变，都把事物推进到新阶段；每一个周期都是开放的，前一个周期的终点是下一个周期的起点，不存在不被否定的终点。曲折性体现在回复性上，其中有暂时的停顿甚至倒退。这表明，<span class=\"rd\">【事物的发展不是直线式前进，而是螺旋式上升的】</span>(2)意义：要深刻认识人类社会历史发展是前进性与曲折性的辩证统一，既要坚信社会历史是不断发展的进程，任何时候都不能失去开拓前进的信心和勇气，又要高度重视和认真对待前进中的曲折，在应对挑战和解决矛盾中推动社会发展", "a": "否定之否定规律揭示了事物发展的前进性与曲折性的统一。前进性体现在每一次否定都是质变，都把事物推进到新阶段；曲折性体现在回复性上，其中有暂时的停顿甚至倒退。这表明事物的发展不是直线式前进，而是螺旋式上升的。"}, {"id": "单21", "ch": "第一章 世界的物质性及发展规律", "type": "单选", "page": "P51-53", "q": "联系和发展的基本环节（四对范畴）", "qh": "<span class=\"rd\">【内容与形式】</span>是从构成要素和表现方式上反映事物的一对范畴。<span class=\"rd\">【本质与现象】</span>是揭示事物内在联系和外在表现的一对范畴。<span class=\"rd\">【原因与结果】</span>是揭示事物引起和被引起关系的一对范畴。<span class=\"rd\">【必然与偶然】</span>是揭示事物产生、发展和衰亡过程中的不同趋势的一对范畴<span class=\"pg\">P51-53</span>", "a": "内容与形式是从构成要素和表现方式上反映事物的一对范畴；本质与现象是揭示事物内在联系和外在表现的一对范畴；原因与结果是揭示事物引起和被引起关系的一对范畴；必然与偶然是揭示事物产生、发展和衰亡过程中不同趋势的一对范畴。"}, {"id": "单22", "ch": "第一章 世界的物质性及发展规律", "type": "单选", "page": "P55", "q": "唯物辩证法本质上是批判的和革命的", "qh": "唯物辩证法本质上是<span class=\"rd\">【批判的和革命的】</span><span class=\"pg\">P55</span>", "a": "马克思指出\"辩证法不崇拜任何东西，按其本质来说，它是批判的和革命的\"。马克思、恩格斯对资本主义的批判及革命性结论，体现了唯物辩证法的批判性和革命性。"}, {"id": "单23", "ch": "第一章 世界的物质性及发展规律", "type": "单选", "page": "P58", "q": "矛盾分析方法居于核心地位", "qh": "<span class=\"rd\">【矛盾分析方法】</span>在唯物辩证法的方法论体系中居于核心地位，是认识事物的根本方法<span class=\"pg\">P58</span>", "a": "矛盾分析方法是对立统一规律在方法论上的体现，在唯物辩证法的方法论体系中居于核心地位，是我们认识事物的根本方法；其核心要求是善于分析矛盾的特殊性，做到具体问题具体分析。"}, {"id": "单24", "ch": "第一章 世界的物质性及发展规律", "type": "单选", "page": "P59", "q": "坚持问题导向", "qh": "<span class=\"rd\">【坚持问题导向】</span>是马克思主义永葆生机活力的奥秘所在<span class=\"pg\">P59</span>", "a": "问题是时代的声音，是矛盾的集中体现。坚持问题导向是马克思主义永葆生机活力的奥秘所在。"}, {"id": "简2", "ch": "第一章 世界的物质性及发展规律", "type": "简答", "page": "P28-29", "q": "马克思主义（列宁）的物质范畴及其理论意义", "qh": "马克思主义(列宁)的物质范畴及其理论意义<span class=\"pg\">P28-29</span>", "a": "物质是标志客观实在的哲学范畴，这种客观实在是人通过感觉感知的，它不依赖于我们的感觉而存在，为我们的感觉所复写、摄影、反映。意义：第一，坚持了唯物主义一元论，同唯心主义一元论和二元论划清界限；第二，坚持了能动的反映论和可知论，批判了不可知论；第三，体现了唯物论和辩证法的统一，克服了形而上学唯物主义的缺陷；第四，体现了唯物主义自然观与历史观的统一，为彻底的唯物主义奠定理论基础。", "o": "(1)马克思主义的“物质”范畴是对世界上客观存在的各种事物共同本质的概括。列宁对物质概念作了规定：<span class=\"rd\">物质是标志客观实在的哲学范畴</span>，这种客观实在是人通过感觉感知的，它不依赖于我们的感觉而存在，为我们的感觉所复写、摄影、反映。这表明，<span class=\"rd\">物质是不依赖于人类的意识而存在，并能为人类的意识</span><span class=\"rd\">所反映的客观实在</span>。这种客观实在性，是从自然存在和社会存在中抽象出的共同特性\n(2)意义：坚持了唯物主义一元论，<span class=\"rd\">同唯心主义一元论和二元论划清了界限</span>；坚持了能动的反映论和可知论，<span class=\"rd\">批判了不可知论</span>；体现了唯物论和辩证法的统一，<span class=\"rd\">克服了形而上学唯物主义的缺陷</span>；体现了唯物主义自然观与历史观的统一，<span class=\"rd\">为彻底的唯物主义奠定了理论基础</span>"}, {"id": "简3", "ch": "第一章 世界的物质性及发展规律", "type": "简答", "page": "P33-34", "q": "物质与意识的辩证统一关系", "qh": "物质与意识的辩证统一关系<span class=\"pg\">P33-34</span>", "a": "（1）物质决定意识：从起源看，意识是自然界长期发展的产物，也是社会历史发展的产物；从本质看，意识是人脑的机能和属性，是客观世界的主观映象，是客观内容和主观形式的统一。（2）意识对物质具有反作用，即意识的能动作用：具有目的性和计划性、创造性、指导实践改造客观世界的作用、调控人的行为和生理活动的作用。", "o": "(1)<span class=\"rd\">物质决定意识</span>。决定作用表现在：①从意识的起源看，<span class=\"rd\">意识是自然界长期发展的产物；也是社会历</span><span class=\"rd\">史发展的产物</span>。②从意识的本质看，<span class=\"rd\">意识是人脑的机能和属性，是客观世界的主观映象</span>。意识是客观内容和主观形式的统一。意识是物质的产物，但又不是物质本身\n(2)<span class=\"rd\">意识对物质具有反作用</span>。这种反作用就是意识的能动作用，表现在：<span class=\"rd\">意识具有目的性和计划性、意识具</span><span class=\"rd\">有创造性、意识具有指导实践改造客观世界的作用、意识具有调控人的行为和生理活动的作用</span>"}, {"id": "简4", "ch": "第一章 世界的物质性及发展规律", "type": "简答", "page": "P35-36", "q": "主观能动性和客观规律性的关系", "qh": "主观能动性和客观规律性的关系<span class=\"pg\">P35-36</span>", "a": "（1）尊重客观规律是正确发挥主观能动性的前提；（2）只有充分发挥主观能动性，才能正确认识和利用客观规律。正确发挥主观能动性的前提和条件：从实际出发是前提；实践是根本途径；还要依赖一定的物质条件和物质手段。", "o": "正确认识和把握物质与意识的辩证关系，还需要处理好主观能动性和客观规律性的(辩证统一)关系：\n(1)<span class=\"rd\">尊重客观规律是正确发挥主观能动性的前提</span>\n(2)<span class=\"rd\">只有充分发挥主观能动性，才能正确认识和利用客观规律</span>。正确发挥人的主观能动性，有三方面前提和条件：①从实际出发是正确发挥人的主观能动性的前提。②实践是正确发挥人的主观能动性的根本途径。③正确发挥人的主观能动性，还要依赖于一定的物质条件和物质手段"}, {"id": "简5", "ch": "第一章 世界的物质性及发展规律", "type": "简答", "page": "P41-42", "q": "联系的含义及特点", "qh": "联系的含义及特点<span class=\"pg\">P41-42</span>", "a": "联系是指事物内部各要素之间和事物之间相互影响、相互制约、相互作用的关系。特点：客观性（事物本身所固有、不以人的意志为转移）、普遍性、多样性、条件性。", "o": "(1)联系指事物内部各要素之间和<span class=\"rd\">事物之间相互</span>影响、相互制约、相互作用<span class=\"rd\">的关系</span>\n(2)特点：<span class=\"rd\">客观性</span>(指事物的联系是事物本身所固有的、不以人的意志为转移的)、<span class=\"rd\">普遍性</span>、<span class=\"rd\">多样性</span>、<span class=\"rd\">条件性</span>"}, {"id": "简6", "ch": "第一章 世界的物质性及发展规律", "type": "简答", "page": "P44", "q": "对立统一规律是唯物辩证法的实质和核心", "qh": "简述对立统一规律是唯物辩证法的实质和核心<span class=\"pg\">P44</span>", "a": "（1）揭示了事物普遍联系的根本内容和变化发展的内在动力，从根本上回答了事物为什么会发展的问题；（2）是贯穿量变质变规律、否定之否定规律以及唯物辩证法基本范畴的中心线索，是理解这些规律的\"钥匙\"；（3）提供了人们认识世界和改造世界的根本方法——矛盾分析方法。", "o": "(1)对立统一规律揭示了事物普遍联系的根本内容和变化发展的内在动力，从根本上回答了事物为什么会发展的问题\n(2)是贯穿量变质变规律、否定之否定规律以及唯物辩证法基本范畴的中心线索，也是理解这些规律的“钥匙”\n(3)提供了人们认识世界和改造世界的根本方法——矛盾分析方法"}, {"id": "简7", "ch": "第一章 世界的物质性及发展规律", "type": "简答", "page": "P45", "q": "矛盾的同一性在事物发展中的作用", "qh": "矛盾的同一性在事物发展中的作用<span class=\"pg\">P45</span>", "a": "（1）同一性是事物存在和发展的前提；（2）同一性使矛盾双方相互吸取有利于自身的因素，在相互作用中各自得到发展；（3）同一性规定着事物转化的可能和发展的趋势。", "o": "(1)同一性是事物存在和发展的前提\n(2)同一性使矛盾双方相互吸取有利于自身的因素，在相互作用中各自得到发展\n(3)同一性规定着事物转化的可能和发展的趋势"}, {"id": "简8", "ch": "第一章 世界的物质性及发展规律", "type": "简答", "page": "P47", "q": "矛盾的普遍性与特殊性辩证关系及现实意义", "qh": "矛盾的普遍性与特殊性辩证关系的原理及其现实意义<span class=\"pg\">P47</span>", "a": "矛盾的普遍性即共性（无条件的、绝对的），特殊性即个性（有条件的、相对的）；任何现实存在的事物的矛盾都是共性和个性的有机统一，共性寓于个性之中。这一原理是马克思主义基本原理同各国实际相结合的哲学基础；中国共产党坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，推进马克思主义中国化时代化。", "o": "(1)二者是辩证统一关系。<span class=\"rd\">矛盾的普遍性即矛盾的共性，矛盾的特殊性即矛盾的个性</span>。矛盾的共性是无条件的、绝对的，矛盾的个性是有条件的、相对的。<span class=\"rd\">任何现实存在的事物的矛盾都是共性和个性的有机统</span><span class=\"rd\">一</span>，共性寓于个性之中，没有离开个性的共性，也没有离开共性的个性。矛盾的共性和个性相统一的关系，既是客观事物固有的辩证法，也是科学的认识方法\n(2)二者的辩证关系原理<span class=\"rd\">是马克思主义基本原理同各国实际相结合的哲学基础</span>。中国共产党坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，不断推进马克思主义中国化时代化，取得一系列重大理论成果，指引中国革命、建设、改革取得伟大胜利，同时又用中国经验和理论创新丰富发展了马克思主义"}, {"id": "简9", "ch": "第一章 世界的物质性及发展规律", "type": "简答", "page": "P48-49", "q": "量变和质变的辩证关系及方法论意义", "qh": "量变和质变的辩证关系原理及其方法论意义<span class=\"pg\">P48-49</span>", "a": "第一，量变是质变的必要准备；第二，质变是量变的必然结果，并为新的量变开辟道路；第三，量变和质变相互渗透（总的量变过程中有阶段性和局部性的部分质变，质变过程中有旧质在量上的收缩和新质在量上的扩张）。意义：量变阶段要踏踏实实做好日常工作、为重大改变作准备；质变来临时要果断抓住机遇，促成质变。", "o": "(1)辩证关系：①<span class=\"rd\">量变是质变的必要准备</span>。②<span class=\"rd\">质变是量变的必然结果</span>，并为新的量变开辟道路。③<span class=\"rd\">量变</span><span class=\"rd\">和质变是相互渗透的</span>。在总的量变过程中有阶段性和局部性的部分质变；在质变过程中也有旧质在量上的收缩和新质在量上的扩张\n(2)意义：当事物的发展<span class=\"rd\">处在量变阶段时，要踏踏实实做好日常工作</span>，为未来重大改变作准备；<span class=\"rd\">当质变来临</span><span class=\"rd\">的时候</span>，<span class=\"rd\">要果断</span>地、不失时机地<span class=\"rd\">抓住机遇</span>，促成质变，使工作迈上新台阶"}, {"id": "简10", "ch": "第一章 世界的物质性及发展规律", "type": "简答", "page": "P49-50", "q": "唯物辩证法的否定观及其指导意义", "qh": "唯物辩证法的否定观的内容及其指导意义<span class=\"pg\">P49-50</span>", "a": "（1）否定是事物的自我否定、自我发展，是事物内部矛盾运动的结果；（2）否定是事物发展的环节，是旧事物向新事物的转变，是从旧质到新质的飞跃；（3）否定是新旧事物联系的环节；（4）辩证否定的实质是\"扬弃\"，即既批判又继承，既克服消极因素又保留积极因素。意义：要求对一切事物采取科学分析的态度，反对简单地肯定一切或否定一切。", "o": "(1)内容：①<span class=\"rd\">否定是事物的自我否定、自我发展，是事物内部矛盾运动的结果</span>\n②<span class=\"rd\">否定是事物发展的环节</span>，是旧事物向新事物的转变，是从旧质到新质的飞跃\n③<span class=\"rd\">否定是新旧事物联系的环节</span>，新事物孕育产生于旧事物，新旧事物是通过否定环节联系起来的\n④<span class=\"rd\">辩证否定的实质是扬弃</span>，即新事物对旧事物既批判又继承，既克服其消极因素又保留其积极因素\n(2)意义：要求对待一切事物都要<span class=\"rd\">采取科学分析的态度，既要把握住现存状态又要把握住发展趋向，反对简</span><span class=\"rd\">单地肯定一切或否定一切</span>。例如，对于中华优秀传统文化，既要注重传承又要根据时代要求实现创造性转化和创新性发展。对于其他民族的文化成果，既不照搬也不一概排斥，而要批判地吸收其合理的因素，为我所用"}, {"id": "简11", "ch": "第一章 世界的物质性及发展规律", "type": "简答", "page": "P51-52", "q": "内容与形式", "qh": "内容与形式的含义、关系原理及其意义<span class=\"pg\">P51-52</span>", "a": "内容指构成事物的一切要素的总和，形式指把诸要素统一起来的结构或表现内容的方式。内容是事物存在的基础，对形式具有决定作用；形式对内容具有反作用，并具有相对独立性，同一内容可以通过多种形式来体现。意义：注重内容、反对形式主义，又要积极利用合适的形式促进内容发展。", "o": "(1)内容指构成事物的一切要素的总和，形式指把诸要素统一起来的结构或表现内容的方式\n(2)任何事物都是内容与形式的统一。<span class=\"rd\">内容是事物存在的基础，对形式具有决定作用；形式对内容具有反作</span><span class=\"rd\">用</span>。形式具有相对独立性，这种相对独立性使得在内容与形式的关系中，同一内容可以通过多种形式来体现\n(3)意义：在我们的认识和实践中，要根据内容决定形式的原理，<span class=\"rd\">注重事物的内容，反对忽视内容、夸大形</span><span class=\"rd\">式</span>作用的形式主义；<span class=\"rd\">又要</span>积极<span class=\"rd\">利用</span>合适的<span class=\"rd\">形式</span>去<span class=\"rd\">促进内容</span>的发展，<span class=\"rd\">不能忽视形式对内容的</span>能动促进<span class=\"rd\">作用</span>"}, {"id": "简12", "ch": "第一章 世界的物质性及发展规律", "type": "简答", "page": "P52", "q": "本质和现象", "qh": "本质和现象的含义、辩证关系及其意义<span class=\"pg\">P52</span>", "a": "本质是事物的根本性质，是构成事物的诸要素之间的内在联系；现象是事物的外部联系和表面特征，是事物本质的外在表现。二者相互区别（本质是一般的、稳定的，需理性思维把握；现象是个别的、多变易逝的，可直接感知），又相互依存（本质决定现象，现象表现本质）。意义：科学的任务在于辨别真象和假象，透过现象把握本质，去粗取精、去伪存真、由此及彼、由表及里。", "o": "(1)本质是事物的根本性质，是构成事物的诸要素之间的内在联系。现象是事物的外部联系和表面特征，是事物本质的外在表现\n(2)关系：①<span class=\"rd\">二者相互区别</span>。本质是一般的、普遍的，现象是个别的、具体的；本质是相对稳定的，现象是多变易逝的；本质深藏于事物的内部，只有通过理性思维才能把握，现象是表面、外显的，可以直接为人的感官所感知。②<span class=\"rd\">二者相互依存</span>。本质决定现象；现象表现本质。不表现为现象的本质和不表现本质的现象都是不存在的\n(3)正确把握二者的关系对于我们的认识活动和科学研究具有重要作用。科学的任务就在于准确辨别真象和假象，<span class=\"rd\">透过现象把握本质</span>，为此需要掌握大量的现象，<span class=\"rd\">进而通过技术手段和理论分析去粗取精、去伪存真</span>，由此及彼、由表及里，不断深化对事物的认识"}, {"id": "简13", "ch": "第一章 世界的物质性及发展规律", "type": "简答", "page": "P53", "q": "原因和结果", "qh": "原因和结果的辩证关系及其意义<span class=\"pg\">P53</span>", "a": "在具体的因果联系中，原因就是原因，结果就是结果，原因在前、结果在后，二者不能混淆和颠倒（倒因为果或倒果为因会歪曲事实）。二者又相互依存和相互转化：没有无果之因，也没有无因之果；一种现象在一种联系中是原因，在另一种联系中则可能是结果。意义：正确把握因果关系，才能消除不利原因，使因果关系运动朝着有利于人的方向发展。", "o": "(1)原因与结果是<span class=\"rd\">相互区别</span>的。在具体的因果联系中，原因就是原因，结果就是结果，<span class=\"rd\">原因在前，结果</span><span class=\"rd\">在后</span>，二者不能混淆和颠倒。如果倒因为果或者倒果为因，就会歪曲事实，得出荒谬的结论。原因与结果是<span class=\"rd\">相互依存和相互转化</span>的。任何原因都必然引起一定的结果，<span class=\"rd\">没有无果之因</span>；任何结果都是由一定的原因引起的，<span class=\"rd\">没有无因之果</span>。<span class=\"rd\">一种现象在一种联系中是原因，在另一种联系中则可能是结果，反之亦然</span>\n(2)原因与结果的辩证关系能够指导我们的认识和实践活动。只有<span class=\"rd\">正确把握事物的因果关系</span>，才能通过自觉的努力，消除不利的原因，<span class=\"rd\">使因果关系运动朝着有利于人的发展的方向运行</span>，从而达到我们所需要的结果"}, {"id": "简14", "ch": "第一章 世界的物质性及发展规律", "type": "简答", "page": "P53-54", "q": "必然性和偶然性", "qh": "必然性和偶然性关系的原理及其意义<span class=\"pg\">P53-54</span>", "a": "二者相互依存——没有脱离偶然的必然（必然通过偶然表现并为自己开辟道路），也没有脱离必然的偶然（在偶然起支配作用的地方，实际是必然起决定作用）；二者相互转化。意义：既要重视必然规律和发展趋势并据此制定目标计划，又要充分估计偶然因素的作用，善于识别和把握机遇。", "o": "(1)关系：①<span class=\"rd\">二者相互依存</span>。没有脱离偶然的必然。没有脱离必然的偶然。②<span class=\"rd\">二者相互转化</span>。相对于某一过程来说是必然的东西，对另一过程就可能成为偶然的东西，反之亦然\n(2)在我们的认识和实践中，必须<span class=\"rd\">重视事物发展的必然规律和发展趋势</span>，并<span class=\"rd\">以此为依据制定我们的目标和计</span><span class=\"rd\">划</span>，也要充分估计到各种偶然因素的作用，善于敏锐地<span class=\"rd\">识别和把握机遇</span>，在实践中达到预期的目标"}, {"id": "简15", "ch": "第一章 世界的物质性及发展规律", "type": "简答", "page": "P54", "q": "现实和可能", "qh": "现实和可能的辩证关系及其意义<span class=\"pg\">P54</span>", "a": "现实是当下的客观存在，标志着事物的当前状况；可能是事物潜在的趋势，标志着事物的发展方向。二者相互转化：现实蕴藏着未来的发展方向，会不断产生新的可能；可能包含着发展成为现实的因素和根据，条件成熟即转化为现实。意义：立足现实、全面分析和预判可能性；着眼长远，防止坏的可能变为现实，创造条件促使好的可能实现。", "o": "(1)关系：①<span class=\"rd\">二者相互区别</span>。现实是当下的客观存在，标志着事物的当前状况；可能是事物潜在的趋势，标志着事物的发展方向。②<span class=\"rd\">二者相互转化</span>。现实蕴藏着未来的发展方向，会不断产生新的可能；可能包含着发展成为现实的因素和根据，一旦主客观条件成熟，可能就会转化为现实\n(2)意义：在实践中正确把握现实与可能的辩证关系，既涉及对现实的评价也涉及对未来的认识。要<span class=\"rd\">立足现</span><span class=\"rd\">实</span>，对可能性作出全面的分析和预判；要<span class=\"rd\">着眼长远</span>，防止坏的可能变为现实，<span class=\"rd\">善于创造条件，促使好的可</span><span class=\"rd\">能获得实现</span>"}, {"id": "单25", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P70", "q": "实践性是根本特征", "qh": "<span class=\"rd\">【实践性】</span>是马克思主义理论区别于其他理论的根本特征。<span class=\"rd\">【实践的观点】</span>是马克思主义的基本观点<span class=\"pg\">P70</span>", "a": "实践性是马克思主义理论区别于其他理论的根本特征。实践的观点是马克思主义的基本观点。"}, {"id": "单26", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P71", "q": "全部社会生活在本质上是实践的", "qh": "马克思强调全部社会生活在本质上是<span class=\"rd\">【实践的】</span><span class=\"pg\">P71</span>", "a": "他（马克思）强调全部社会生活在本质上是实践的，凡是把理论引向神秘主义的神秘东西，都能在人的实践中以及对这个实践的理解中得到合理的解决。"}, {"id": "单27", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P73", "q": "实践观点是认识论首要的和基本的观点", "qh": "<span class=\"rd\">【实践观点】</span>是辩证唯物主义认识论首要的和基本的观点<span class=\"pg\">P73</span>", "a": "马克思坚持实践观点和辩证观点，深刻揭示了实践观点是辩证唯物主义认识论首要的和基本的观点。"}, {"id": "单28", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P73-74", "q": "科学实践观及其意义", "qh": "科学实践观揭示了实践的本质，指明实践是<span class=\"rd\">【人类能动地改造世界的社会性的物质活动】</span>。科学实践观的意义：<span class=\"rd\">【克服了旧唯物主义的根本缺陷，为辩证唯物主义的创立奠定了科学的理论基础；揭示了实践</span><span class=\"rd\">对认识的决定作用，为能动的、革命的反映论的创立奠定了科学的理论基础；在人类思想史上第一次揭示</span><span class=\"rd\">了社会生活的实践本质，为唯物史观的创立奠定了科学的理论基础；为人们能动地认识世界和改造世界提</span><span class=\"rd\">供了基本的思想方法和工作方法】</span><span class=\"pg\">P73-74</span>", "a": "实践是人类能动地改造世界的社会性的物质活动。科学实践观的意义：第一，克服了旧唯物主义的根本缺陷，为辩证唯物主义的创立奠定科学理论基础；第二，揭示了实践对认识的决定作用，为能动的、革命的反映论的创立奠定科学理论基础；第三，在人类思想史上第一次揭示了社会生活的实践本质，为唯物史观的创立奠定科学理论基础；第四，为人们能动地认识世界和改造世界提供了基本的思想方法和工作方法。"}, {"id": "单29", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P75-78", "q": "实践的特征、基本结构、形式", "qh": "实践<span class=\"pg\">P75-78</span>(1)特征：<span class=\"rd\">【客观实在性、自觉能动性、社会历史性】</span>(2)基本结构(基本要素)：①<span class=\"rd\">【实践主体】</span>，指具有一定的主体能力、从事现实社会实践活动的人，有个体主体、群体主体和人类主体三种基本形态；②<span class=\"rd\">【实践客体】</span>，指实践活动所指向的对象；③<span class=\"rd\">【实践中介】</span>，指各种形式的工具、手段以及运用、操作这些工具、手段的程序和方法(3)形式：<span class=\"rd\">【物质生产实践(是人类最基本的实践活动)、社会政治实践、科学文化实践】</span>", "a": "（1）特征：客观实在性、自觉能动性、社会历史性。（2）基本结构：实践主体（具有一定的主体能力、从事现实社会实践活动的人，有个体主体、群体主体、人类主体三种形态）、实践客体（实践活动所指向的对象）、实践中介（各种形式的工具、手段以及运用操作这些工具的程序和方法）。（3）形式：物质生产实践（人类最基本的实践活动）、社会政治实践、科学文化实践。"}, {"id": "单30", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P76-77", "q": "主体和客体相互作用的关系", "qh": "实践的主体和客体相互作用的关系，包括<span class=\"rd\">【实践关系(最根本的关系)、认识关系和价值关系】</span><span class=\"pg\">P76-77</span>", "a": "实践的主体和客体相互作用的关系，包括实践关系、认识关系和价值关系，其中实践关系是最根本的关系。"}, {"id": "单31", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P81", "q": "认识的本质", "qh": "认识的本质是<span class=\"rd\">【主体在实践基础上对客体的能动反映】</span>，这是辩证唯物主义认识论对认识本质的科学回答<span class=\"pg\">P81</span>", "a": "认识的本质是主体在实践基础上对客体的能动反映，这是辩证唯物主义认识论对认识本质的科学回答。"}, {"id": "单32", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P82", "q": "两种唯心主义认识论", "qh": "<span class=\"rd\">【主观唯心主义】</span>认为人的认识是主观自生的，是生而知之的。<span class=\"rd\">【客观唯心主义】</span>认为人的认识是上帝的启示或某种客观精神的产物<span class=\"pg\">P82</span>", "a": "主观唯心主义认为人的认识是主观自生的，是生而知之的；客观唯心主义认为人的认识是上帝的启示或某种客观精神的产物。"}, {"id": "单33", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P83", "q": "辩证唯物主义认识论与唯心、旧唯物认识论的根本区别", "qh": "辩证唯物主义认识论<span class=\"rd\">【坚持以科学的社会实践为特征的实践观】</span>，即实践是人类能动地改造世界的社会性的物质活动。这是马克思主义认识论即辩证唯物主义认识论与唯心主义认识论、旧唯物主义认识论的根本区别<span class=\"pg\">P83</span>", "a": "坚持以科学的社会实践为特征的实践观，即实践是人类能动地改造世界的社会性的物质活动。这是马克思主义认识论即辩证唯物主义认识论与唯心主义认识论、旧唯物主义认识论的根本区别。"}, {"id": "单34", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P83", "q": "辩证唯物主义认识论的两个突出特点", "qh": "辩证唯物主义认识论两个突出特点：<span class=\"rd\">【把实践的观点引入认识论；把辩证法应用于反映论考察认识的</span><span class=\"rd\">发展过程】</span><span class=\"pg\">P83</span>", "a": "一是把实践的观点引入认识论（以实践的观点作为整个认识论的基础）；二是把辩证法应用于反映论考察认识的发展过程。"}, {"id": "单35", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P84", "q": "认识的两次飞跃", "qh": "人们认识一定事物的过程，是一个<span class=\"rd\">【从实践到认识(是第一次飞跃，表现为从感性认识到理性认识)，</span><span class=\"rd\">再从认识到实践(第二次飞跃)】</span>的过程<span class=\"pg\">P84</span>", "a": "人们认识一定事物的过程，是一个从实践到认识（第一次飞跃，表现为在实践基础上由感性认识能动地飞跃到理性认识），再从认识到实践（第二次飞跃）的过程。"}, {"id": "单36", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P85", "q": "感性认识", "qh": "感性认识：<span class=\"pg\">P85</span>(1)是人们在实践基础上，由感觉器官直接感受到的关于事物的现象、事物的外部联系、事物的各个方面的认识(2)形式：<span class=\"rd\">【感觉、知觉和表象】</span>(3)是认识的初级阶段(4)特点：<span class=\"rd\">【直接性、具体性】</span>", "a": "感性认识是人们在实践基础上，由感觉器官直接感受到的关于事物的现象、事物的外部联系、事物的各个方面的认识，包括感觉、知觉和表象三种形式，是认识的初级阶段，突出特点是直接性、具体性。"}, {"id": "单37", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P85-86", "q": "理性认识", "qh": "理性认识：<span class=\"pg\">P85-86</span>(1)指人们借助抽象思维，在概括整理大量感性材料的基础上，达到关于事物的本质、全体、内部联系和事物自身规律性的认识(2)形式：<span class=\"rd\">【概念(最基本的思维形式)、判断、推理】</span>(3)是认识的高级阶段(4)特点：<span class=\"rd\">【抽象性和间接性】</span>", "a": "理性认识是人们借助抽象思维，在概括整理大量感性材料的基础上，达到关于事物的本质、全体、内部联系和事物自身规律性的认识，包括概念（最基本的思维形式）、判断、推理三种形式，是认识的高级阶段，特点是抽象性和间接性。"}, {"id": "单38", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P88-89", "q": "第二次飞跃的必要性和重要性", "qh": "从认识到实践的飞跃是更为重要的飞跃，其必要性和重要性：<span class=\"rd\">【①认识世界的目的是改造世界。②认识的</span><span class=\"rd\">真理性只有在实践中才能得到检验和发展】</span><span class=\"pg\">P88-89</span>", "a": "第一，认识世界的目的是改造世界；第二，认识的真理性只有在实践中才能得到检验和发展。"}, {"id": "单39", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P93-94", "q": "真理的客观性", "qh": "真理的<span class=\"rd\">【客观性】</span>指真理的内容是对客观事物及其规律的正确反映。客观性是真理的本质属性。<span class=\"pg\">P93-94</span>", "a": "真理的客观内容就是客观事物的实际状况。真理的客观性决定了真理的一元性——在同一条件下对于特定的认识客体的真理性认识只有一个。客观性是真理的本质属性。"}, {"id": "单40", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P101", "q": "实践是检验真理的唯一标准", "qh": "实践之所以能够作为检验真理的唯一标准，是由真理的本性和实践的特点决定的<span class=\"pg\">P101</span>(1)真理是人们对客观事物及其发展规律的正确反映，它的本性在于<span class=\"rd\">【主观和客观相符合】</span>。检验真理就是检验人的主观认识同客观实际是否相符合以及符合的程度(2)实践具有<span class=\"rd\">【直接现实性】</span>，这是它的客观实在性的具体表现", "a": "第一，从真理的本性看，真理是人们对客观事物及其发展规律的正确反映，它的本性在于主观和客观相符合，检验真理就是检验主观认识同客观实际是否相符合；第二，从实践的特点看，实践具有直接现实性，这是它的客观实在性的具体表现。实践，只有实践，才是检验真理的唯一标准。"}, {"id": "单41", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P102", "q": "实践标准的确定性与不确定性", "qh": "实践作为检验真理的标准，<span class=\"rd\">【既有确定性(绝对性)，又有不确定性(相对性)】</span><span class=\"pg\">P102</span>", "a": "实践作为检验真理的标准，既有确定性（绝对性），又有不确定性（相对性）。确定性即唯一性、归根到底性、最终性；不确定性即条件性——任何实践都受主客观条件制约，实践是社会的、历史的实践，对真理的检验具有相对性、有限性。实践检验真理是一个永无止境的发展过程。"}, {"id": "单42", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P104", "q": "价值的基本特性", "qh": "价值的基本特性：<span class=\"rd\">【主体性、客观性、多维性、社会历史性】</span><span class=\"pg\">P104</span>", "a": "价值具有主体性、客观性、多维性和社会历史性四个基本特性。"}, {"id": "单43", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P108", "q": "人民群众是推动社会历史进步的根本动力", "qh": "<span class=\"rd\">【人民群众】</span>是推动社会历史进步的根本动力<span class=\"pg\">P108</span>", "a": "价值评价要以最广大人民的需要和利益为根本，人民群众始终是推动社会历史进步的根本动力，人民群众的需要和利益是与历史发展的基本要求或趋势相一致的。"}, {"id": "单44", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P109", "q": "社会主义核心价值观", "qh": "我国社会主义核心价值观的基本内容<span class=\"pg\">P109</span>(1)国家层面：<span class=\"rd\">【富强、民主、文明、和谐】</span>(2)社会层面：<span class=\"rd\">【自由、平等、公正、法治】</span>(3)公民层面：<span class=\"rd\">【爱国、敬业、诚信、友善】</span>", "a": "我国社会主义核心价值观的基本内容包括：富强、民主、文明、和谐（国家层面），自由、平等、公正、法治（社会层面），爱国、敬业、诚信、友善（公民层面）。它回答了建设什么样的国家、建设什么样的社会、培育什么样的公民的重大问题。"}, {"id": "单45", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P109-110", "q": "真理尺度与价值尺度", "qh": "<span class=\"rd\">【实践的真理尺度】</span>指在实践中人们必须遵循正确反映客观事物本质和规律的真理；<span class=\"rd\">【实践的价值尺</span><span class=\"rd\">度】</span>指在实践中人们都是按照自己的尺度和需要去认识世界和改造世界。真理与价值(真理尺度与价值尺度)的辩证统一关系：<span class=\"rd\">【①价值尺度必须以真理为前提。②人类自身需要的内在尺度，推动着人们不断发现新</span><span class=\"rd\">的真理】</span><span class=\"pg\">P109-110</span>", "a": "实践的真理尺度是指在实践中人们必须遵循正确反映客观事物本质和规律的真理；实践的价值尺度是指在实践中人们都是按照自己的尺度和需要去认识世界和改造世界。二者辩证统一：一方面，价值尺度必须以真理为前提；另一方面，人类自身需要的内在尺度，推动着人们不断发现新的真理。"}, {"id": "单46", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P111-112", "q": "认识世界的根本目的在于改造世界", "qh": "认识世界的根本目的在于<span class=\"rd\">【改造世界】</span>。<span class=\"rd\">【主观和客观的矛盾】</span>是人类认识世界和改造世界的根本动力<span class=\"pg\">P111-112</span>", "a": "一、认识世界的根本目的在于改造世界。认识世界和改造世界统一的基础是实践；主观和客观的矛盾是人类认识世界和改造世界的根本动力。"}, {"id": "单47", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P112-113", "q": "改造客观世界与主观世界的意义", "qh": "马克思主义关于改造客观世界与主观世界的观点的意义：<span class=\"rd\">【有助于提高认识世界的能力，努力做到主</span><span class=\"rd\">观符合客观，更好地处理主观世界与客观世界的关系；有助于提高自身的思想修养和精神境界；有助于在</span><span class=\"rd\">改造外部世界的同时，把目光转向自身，高度重视并努力实现人自身的改造】</span><span class=\"pg\">P112-113</span>", "a": "首先，有助于提高认识世界的能力，努力做到主观符合客观，更好地处理主观世界与客观世界的关系；其次，有助于提高自身的思想修养和精神境界；最后，有助于在改造外部世界的同时，把目光转向自身，高度重视并努力实现人自身的改造。"}, {"id": "单48", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P114-115", "q": "认识必然和争取自由", "qh": "<span class=\"rd\">【认识必然和争取自由】</span>是人类认识世界和改造世界的根本目标。<span class=\"rd\">【必然与自由的关系】</span>成为人类存在和发展的永恒矛盾，是人类存在和发展的永恒动力<span class=\"pg\">P114-115</span>", "a": "必然与自由的关系贯穿于人类存在和发展的始终，并成为人类存在和发展的永恒矛盾，因此也是人类存在和发展的永恒动力。自由是对必然的认识和对客观世界的改造。"}, {"id": "单49", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P116", "q": "一切从实际出发", "qh": "<span class=\"rd\">【一切从实际出发】</span>就是要把客观存在的事物作为观察和处理问题的根本出发点，这是马克思主义认识论的根本要求。从实际出发，关键是要注重事实，从事实出发<span class=\"pg\">P116</span>", "a": "一切从实际出发，就是要把客观存在的事物作为观察和处理问题的根本出发点，这是马克思主义认识论的根本要求和具体体现。从实际出发，关键是要注重事实，从事实出发。"}, {"id": "单50", "ch": "第二章 实践与认识及其发展规律", "type": "单选", "page": "P118-119", "q": "坚持实事求是", "qh": "坚持实事求是：最基础的工作在于<span class=\"rd\">【搞清楚“实事”】</span>，这是进行一切科学决策所必需的也是唯一可靠的前提和基础；关键在于“求是”，就是探求和掌握事物发展的规律；要坚持一切从实际出发，坚持解放思想<span class=\"pg\">P118-119</span>", "a": "坚持实事求是，最基础的工作在于搞清楚\"实事\"，也就是了解实际、掌握实情，这是进行一切科学决策所必需的也是唯一可靠的前提和基础；关键在于\"求是\"，即探求和掌握事物发展的规律；还要坚持一切从实际出发、坚持解放思想。"}, {"id": "简16", "ch": "第二章 实践与认识及其发展规律", "type": "简答", "page": "P80-81", "q": "实践对认识的决定作用", "qh": "实践对认识的决定作用<span class=\"pg\">P80-81</span>", "a": "（1）实践是认识的来源；（2）实践是认识发展的动力——实践的需要推动认识的产生和发展，实践为认识发展提供手段和条件，实践改造了人的主观世界、锻炼和提高了人的认识能力；（3）实践是认识的目的；（4）实践是检验认识真理性的唯一标准。", "o": "(1)实践<span class=\"rd\">是认识的来源</span>\n(2)实践<span class=\"rd\">是认识发展的动力</span>。①实践的需要推动认识的产生和发展，推动人类的科学发现和技术发明，推动人类的思想进步和理论创新。②实践为认识的发展提供了手段和条件。③实践改造了人的主观世界，锻炼和提高了人的认识能力\n(3)实践<span class=\"rd\">是认识的目的</span>\n(4)实践<span class=\"rd\">是检验认识真理性的唯一标准</span>"}, {"id": "简17", "ch": "第二章 实践与认识及其发展规律", "type": "简答", "page": "P86-87", "q": "感性认识与理性认识的辩证关系；反对经验主义和教条主义", "qh": "感性认识和理性认识的辩证关系以及反对经验主义和教条主义的原因(实践意义)<span class=\"pg\">P86-87</span>", "a": "（1）理性认识依赖于感性认识；（2）感性认识有待于发展和深化为理性认识；（3）二者相互渗透、相互包含，感性中有理性，理性中有感性。割裂二者的辩证统一，要么走向唯理论（轻视感性认识、夸大理性认识，犯教条主义错误），要么走向经验论（轻视理性认识、夸大感性认识，导致经验主义）。", "o": "(1)二者是辩证统一的。①<span class=\"rd\">理性认识依赖于感性认识</span>。②<span class=\"rd\">感性认识有待于发展和深化为理性认识</span>。③<span class=\"rd\">感</span><span class=\"rd\">性认识和理性认识相互渗透、相互包含</span>。感性中有理性，理性中有感性\n(2)二者的辩证统一关系是在实践的基础上形成的，也需要在实践中发展。如果<span class=\"rd\">割裂二者的辩证统一关系</span>，<span class=\"rd\">要么走向唯理论</span>，即轻视感性认识而片面夸大理性认识的作用，在实际工作中<span class=\"rd\">犯教条主义</span>的错误；<span class=\"rd\">要么走</span><span class=\"rd\">向经验论</span>，即轻视理性认识而片面夸大感性认识的作用，<span class=\"rd\">导致</span>实践中的<span class=\"rd\">经验主义</span>"}, {"id": "简18", "ch": "第二章 实践与认识及其发展规律", "type": "简答", "page": "P87", "q": "从感性认识上升到理性认识的条件", "qh": "从感性认识上升到理性认识的条件<span class=\"pg\">P87</span>", "a": "第一，投身实践，深入调查，获取十分丰富和合乎实际的感性材料（这是基础）；第二，经过思考的作用，运用理论思维和科学抽象，将丰富的感性材料加以去粗取精、去伪存真、由此及彼、由表及里的处理加工，形成概念和理论的系统。", "o": "(1)基础：<span class=\"rd\">投身实践，深入调查，获取十分丰富和合乎实际的感性材料</span>\n(2)经过思考的作用，<span class=\"rd\">运用理论思维和科学抽象</span>，<span class=\"rd\">将</span>丰富的<span class=\"rd\">感性材料</span>加以去粗取精、去伪存真、由此及彼、由表及里的<span class=\"rd\">处理加工，形成概念和理论的系统</span>"}, {"id": "简19", "ch": "第二章 实践与认识及其发展规律", "type": "简答", "page": "P95-97", "q": "真理的绝对性和相对性", "qh": "真理的绝对性和相对性的含义、关系及其意义<span class=\"pg\">P95-97</span>", "a": "（1）绝对性：任何真理都标志着主观与客观相符合，都包含着不依赖于人和人的意识的客观内容，都同谬误有原则界限；人类认识能够正确认识无限发展着的物质世界，每前进一步都是对无限发展着的物质世界的接近。（2）相对性：任何真理都只是对客观世界某一阶段、某一部分的正确认识，认识有待扩展；也只是对客观对象一定方面、一定层次、一定程度的正确认识，认识有待深化。（3）二者相互依存、相互包含，真理的发展是由相对性走向绝对性的过程；割裂二者会走向绝对主义和相对主义。意义：马克思主义作为客观真理是绝对性和相对性的统一，既要坚持以马克思主义为指导，又要在实践中丰富和发展马克思主义。", "o": "(1)绝对性：指真理主客观统一的确定性和发展的无限性。包含的含义：①<span class=\"rd\">任何真理都标志着主观与客</span><span class=\"rd\">观相符合</span>，都包含着不依赖于人和人的意识的客观内容，都同谬误有原则的界限，这是绝对的、无条件的。②<span class=\"rd\">人类认识能够正确认识无限发展着的物质世界</span>，认识每前进一步，都是对无限发展着的物质世界的接近，这是绝对的、无条件的\n(2)相对性：指人们对客观事物及其本质和发展规律的正确认识总是有限度的、不完善的。包含的含义：①<span class=\"rd\">任何真理都只是对客观世界的某一阶段、某一部分的正确认识</span>，认识有待扩展。②<span class=\"rd\">任何真理都只是对客观</span><span class=\"rd\">对象一定方面、一定层次、一定程度的正确认识</span>，认识有待深化\n(3)辩证统一关系：①真理的两重性角度：绝对性与相对性<span class=\"rd\">相互依存</span>，任何真理都既是绝对的又是相对的。绝对性与相对性<span class=\"rd\">相互包含</span>。绝对之中有相对，相对之中有绝对，真理的绝对性通过真理的相对性表现出来，任何真理的相对性之中都包含着真理绝对性的颗粒。②真理的发展角度：<span class=\"rd\">人类的认识永远处在由真理的相</span><span class=\"rd\">对性走向绝对性、接近绝对性的转化和发展过程中</span>。③<span class=\"rd\">割裂</span>真理的<span class=\"rd\">绝对性与相对性的辩证关系</span>就<span class=\"rd\">会走向形</span><span class=\"rd\">而上学</span>的真理观，即绝对主义和相对主义\n(4)意义：①<span class=\"rd\">马克思主义作为客观真理</span>，是绝对性和相对性的统一，马克思主义正确反映人类社会的发展规律，<span class=\"rd\">具有绝对性</span>；马克思主义并没有穷尽对一切事物及其规律的认识，仍需要随着社会实践的发展而发展，<span class=\"rd\">具有相对性</span>。②马克思主义真理的<span class=\"rd\">绝对性要求我们必须坚持以马克思主义为指导思想</span>；<span class=\"rd\">相对性要求我们必</span><span class=\"rd\">须在实践中丰富和发展马克思主义</span>"}, {"id": "简20", "ch": "第二章 实践与认识及其发展规律", "type": "简答", "page": "P106-107", "q": "价值评价的特点", "qh": "价值评价的特点<span class=\"pg\">P106-107</span>", "a": "（1）评价以主客体之间的价值关系为认识对象；（2）评价结果与评价主体直接相关；（3）评价结果的正确与否依赖于对客体状况和主体需要的认识；（4）价值评价有科学与非科学之别。", "o": "(1)评价以主客体之间的价值关系为认识对象\n(2)评价结果与评价主体直接相关\n(3)评价结果的正确与否依赖于对客体状况和主体需要的认识\n(4)价值评价有科学与非科学之别"}, {"id": "简21", "ch": "第二章 实践与认识及其发展规律", "type": "简答", "page": "P117", "q": "党的思想路线的基本内涵和核心", "qh": "党思想路线的基本内涵和核心<span class=\"pg\">P117</span>", "a": "思想路线是化为指导思想用以支配行动的认识路线。中国共产党思想路线的基本内涵是：一切从实际出发，理论联系实际，实事求是，在实践中检验和发展真理，其核心是实事求是。", "o": "思想路线就是人们在实践活动中用以指导行动的基本原则和方法，是化为指导思想用以支配行动的认识路线。中国共产党思想路线的基本内涵：<span class=\"rd\">一切从实际出发，理论联系实际，实事求是，在实践中检验和</span><span class=\"rd\">发展真理</span>，其核心是<span class=\"rd\">实事求是</span>"}, {"id": "单51", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P126", "q": "社会历史观的基本问题", "qh": "<span class=\"rd\">【社会存在与社会意识的关系问题】</span>是社会历史观的基本问题<span class=\"pg\">P126</span>", "a": "社会存在与社会意识的关系问题，是社会历史观的基本问题。正确认识社会存在与社会意识的关系，是科学把握人类社会发展规律的基础和前提。"}, {"id": "单52", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P126", "q": "两种根本对立的历史观", "qh": "两种根本对立的历史观<span class=\"pg\">P126</span>(1)<span class=\"rd\">【唯心史观】</span>。从社会意识决定社会存在的前提出发，把社会历史看成精神发展史(2)<span class=\"rd\">【唯物史观】</span>。认为是人们的社会存在决定人们的意识", "a": "唯心史观从社会意识决定社会存在的前提出发，把社会历史看成精神发展史；唯物史观认为不是人们的意识决定人们的存在，而是人们的社会存在决定人们的意识。"}, {"id": "单53", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P127-129", "q": "社会存在", "qh": "<span class=\"rd\">【社会存在】</span>指社会物质生活条件，是社会生活的物质方面，包括<span class=\"pg\">P127-129</span>(1)自然地理环境：其优劣对<span class=\"rd\">【劳动生产率的提高产生积极或消极的影响，并对社会发展起促进或延缓的作</span><span class=\"rd\">用】</span>(2)人口因素：人口的数量、质量和结构等因素<span class=\"rd\">【对生产发展和社会进步起加速或延缓的作用】</span>。适度的人口对社会发展起加速作用，过密或过疏的人口则对社会发展起延缓作用(3)物质生产方式：指人们为获取物质生活资料而进行的生产活动的方式，是<span class=\"rd\">【生产力和生产关系】</span>的统一体", "a": "社会存在是指社会物质生活条件，是社会生活的物质方面，主要包括自然地理环境、人口因素和物质生产方式。（1）自然地理环境是人们生活和生产的自然基础，其优劣对劳动生产率的提高产生积极或消极影响，对社会发展起促进或延缓的作用；（2）人口因素对社会发展起加速或延缓的作用，适度人口起加速作用，过密或过疏则起延缓作用；（3）物质生产方式是人们为获取物质生活资料而进行的生产活动的方式，是生产力和生产关系的统一体。"}, {"id": "单54", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P129-130", "q": "社会意识的构成", "qh": "社会意识<span class=\"pg\">P129-130</span>(1)根据不同的主体，分为：个体意识、群体意识(2)根据不同的层次，分为：①社会心理：表现为人们的感知、情绪、情感、心态、习俗，以感性认识为主②社会意识形式：以理性认识为主，分为<span class=\"rd\">【意识形态(如政治法律思想、道德、艺术、宗教、哲学)、非意</span><span class=\"rd\">识形态(如自然科学、语言学、形式逻辑)】</span>", "a": "根据不同的主体，社会意识可分为个体意识和群体意识；根据不同的层次，可分为社会心理（表现为人们的感知、情绪、情感、心态、习俗，以感性认识为主）和社会意识形式（以理性认识为主，分为意识形态如政治法律思想、道德、艺术、宗教、哲学，以及非意识形态如自然科学、语言学、形式逻辑）。"}, {"id": "单55", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P130", "q": "政治法律思想的地位", "qh": "<span class=\"rd\">【政治法律思想】</span>是最直接、最集中地反映经济基础的意识形态，在意识形态中居于核心地位<span class=\"pg\">P130</span>", "a": "政治法律思想是最直接、最集中地反映经济基础的意识形态，在意识形态中居于核心地位，发挥主导作用。"}, {"id": "单56", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P132-133", "q": "社会意识相对独立性的表现", "qh": "社会意识相对独立性的表现：<span class=\"rd\">【社会意识与社会存在发展具有不完全同步性和不平衡性；社会意识内</span><span class=\"rd\">部各种形式之间存在相互影响且各自具有历史继承性；社会意识对社会存在具有能动的反作用】</span><span class=\"pg\">P132-133</span>", "a": "一是社会意识与社会存在发展具有不完全同步性和不平衡性；二是社会意识内部各种形式之间存在相互影响且各自具有历史继承性；三是社会意识对社会存在具有能动的反作用（这是相对独立性的突出表现）。"}, {"id": "单57", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P133", "q": "唯物史观与唯心史观的根本分野", "qh": "<span class=\"rd\">【主张社会存在决定社会意识，还是社会意识决定社会存在】</span>是唯物史观与唯心史观的根本分野<span class=\"pg\">P133</span>", "a": "主张社会存在决定社会意识，还是主张社会意识决定社会存在，是唯物史观与唯心史观的根本分野。唯物史观在人类思想史上第一次正确回答了社会历史观的基本问题，宣告了唯心史观的彻底破产。"}, {"id": "单58", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P134", "q": "社会基本矛盾和基本规律", "qh": "<span class=\"rd\">【生产力与生产关系、经济基础与上层建筑之间的矛盾】</span>是人类社会基本矛盾。<span class=\"rd\">【生产力与生产关系</span><span class=\"rd\">矛盾运动的规律、经济基础与上层建筑矛盾运动的规律】</span>是人类社会发展的基本规律<span class=\"pg\">P134</span>", "a": "生产力与生产关系、经济基础与上层建筑之间的矛盾，是人类社会基本矛盾；生产力与生产关系矛盾运动的规律、经济基础与上层建筑矛盾运动的规律，是人类社会发展的基本规律。"}, {"id": "单59", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P134-135", "q": "生产力", "qh": "生产力<span class=\"pg\">P134-135</span>(1)是人类在生产实践中形成的改造和影响自然以使其适合社会需要的物质力量，是人类社会生活和全部历史的物质基础(2)具有<span class=\"rd\">【客观现实性和社会历史性】</span>(3)基本要素：<span class=\"rd\">【劳动资料、劳动对象、劳动者】</span>。<span class=\"rd\">【生产工具】</span>是区分社会经济时代的客观依据", "a": "生产力是人类在生产实践中形成的改造和影响自然以使其适合社会需要的物质力量，是人类社会生活和全部历史的物质基础，具有客观现实性和社会历史性。基本要素包括劳动资料、劳动对象和劳动者；其中生产工具是区分社会经济时代的客观依据。"}, {"id": "单60", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P136", "q": "科学技术是第一生产力", "qh": "<span class=\"rd\">【科学技术】</span>是先进生产力的集中体现和主要标志，是第一生产力<span class=\"pg\">P136</span>", "a": "科学技术是先进生产力的集中体现和主要标志，是第一生产力。"}, {"id": "单61", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P136", "q": "生产关系", "qh": "生产关系是人们在物质生产过程中形成的不以人的意志为转移的<span class=\"rd\">【经济关系】</span>，是社会关系中最基本的关系，包括<span class=\"rd\">【生产资料所有制关系、生产中人与人的关系和产品分配关系】</span>。<span class=\"rd\">【生产资料所有制关系】</span>是人们进行物质资料生产的前提，生产、分配、交换和消费关系在很大程度上是由这一前提决定的，所以是最基本的、具有决定意义的方面，它是区分不同生产方式、判定社会经济结构性质的客观依据<span class=\"pg\">P136</span>", "a": "生产关系是人们在物质生产过程中形成的不以人的意志为转移的经济关系，是社会关系中最基本的关系，包括生产资料所有制关系、生产中人与人的关系和产品分配关系。生产资料所有制关系是最基本的、具有决定意义的方面，是区分不同生产方式、判定社会经济结构性质的客观依据。"}, {"id": "单62", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P139", "q": "社会主义的根本任务", "qh": "生产力是推动社会进步的最活跃、最革命的要素，社会主义的根本任务是<span class=\"rd\">【解放和发展社会生产力】</span><span class=\"pg\">P139</span>", "a": "生产力是推动社会进步的最活跃、最革命的要素，社会主义的根本任务是解放和发展社会生产力。"}, {"id": "单63", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P140", "q": "国家政权是政治上层建筑的核心", "qh": "<span class=\"rd\">【国家政权】</span>是政治上层建筑的核心<span class=\"pg\">P140</span>", "a": "在整个上层建筑中，政治上层建筑居于主导地位，国家政权是政治上层建筑的核心。"}, {"id": "单64", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P140", "q": "上层建筑的构成", "qh": "上层建筑由<span class=\"rd\">【意识形态(观念上层建筑)以及政治法律制度及设施和政治组织(政治上层建筑)】</span>两部分构成<span class=\"pg\">P140</span>", "a": "上层建筑是建立在一定经济基础之上的意识形态以及与之相适应的制度、组织和设施。意识形态又称观念上层建筑（政治法律思想、道德、艺术、宗教、哲学等）；政治法律制度及设施和政治组织又称政治上层建筑。"}, {"id": "单65", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P141", "q": "社会主义民主的本质和核心", "qh": "社会主义民主的本质和核心是<span class=\"rd\">【人民当家作主】</span><span class=\"pg\">P141</span>", "a": "社会主义民主的本质和核心是人民当家作主，人民民主是社会主义的生命，是对资产阶级民主的辩证否定，是民主发展的历史性飞跃。"}, {"id": "单66", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P142-143", "q": "经济基础与上层建筑的辩证统一", "qh": "经济基础与上层建筑是辩证统一的：<span class=\"pg\">P142-143</span>(1)<span class=\"rd\">【经济基础决定上层建筑，上层建筑反作用于经济基础】</span>(2)经济基础与上层建筑的相互作用构成二者的矛盾运动(3)经济基础和上层建筑的内在联系构成了<span class=\"rd\">【上层建筑一定要适合经济基础状况的规律】</span>", "a": "（1）经济基础决定上层建筑，上层建筑反作用于经济基础；（2）二者的相互作用构成矛盾运动；（3）经济基础和上层建筑的内在联系构成了上层建筑一定要适合经济基础状况的规律。"}, {"id": "单67", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P143", "q": "生产关系的实质", "qh": "生产关系的实质是<span class=\"rd\">【人们的物质利益关系】</span><span class=\"pg\">P143</span>", "a": "生产关系的实质是人们的物质利益关系。在社会主义条件下，上层建筑对经济基础的保护从根本上说就是为了保障最广大人民群众的物质利益。"}, {"id": "单68", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P144-145", "q": "交往对社会生活的影响", "qh": "交往对社会生活的影响：<span class=\"rd\">【促进生产力的发展；促进社会关系的进步；促进文化的发展与传播；促进</span><span class=\"rd\">人的全面发展】</span><span class=\"pg\">P144-145</span>", "a": "第一，促进生产力的发展；第二，促进社会关系的进步；第三，促进文化的发展与传播；第四，促进人的全面发展。"}, {"id": "单69", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P145-146", "q": "世界历史的形成和发展", "qh": "<span class=\"rd\">【生产方式的发展变革】</span>是世界历史形成和发展的基础。<span class=\"rd\">【普遍交往】</span>是世界历史的基本特征<span class=\"pg\">P145-146</span>", "a": "生产方式的发展变革是世界历史形成和发展的基础；普遍交往是世界历史的基本特征。"}, {"id": "单70", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P147", "q": "社会进步的表现", "qh": "社会进步表现在：<span class=\"rd\">【社会形态从低级到高级的发展；同一社会形态内部的发展】</span><span class=\"pg\">P147</span>", "a": "社会进步主要表现在两个方面：一是社会形态从低级到高级的发展；二是同一社会形态内部的发展。社会进步不是直线上升的，而是曲折发展的。"}, {"id": "单71", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P148", "q": "人的自由而全面的发展", "qh": "只有在<span class=\"rd\">【共产主义社会】</span>，人才能真正得到自由而全面的发展<span class=\"pg\">P148</span>", "a": "在以私有制为基础的社会，人的自由和发展问题不可能得到彻底的解决；只有在共产主义社会，人才能真正得到自由而全面的发展。"}, {"id": "单72", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P149", "q": "社会形态的内涵", "qh": "社会形态是关于社会运动的具体形式、发展阶段和不同质态的范畴，是同生产力发展一定阶段相适应的经济基础与上层建筑的统一体，包括<span class=\"rd\">【经济形态(是基础)、政治形态、意识形态】</span><span class=\"pg\">P149</span>", "a": "社会形态是关于社会运动的具体形式、发展阶段和不同质态的范畴，是同生产力发展一定阶段相适应的经济基础与上层建筑的统一体，包括社会的经济形态（是基础）、政治形态和意识形态。"}, {"id": "单73", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P150", "q": "社会形态更替的必然性", "qh": "<span class=\"rd\">【生产力与生产关系矛盾运动的规律性】</span>从根本上规定了社会形态更替的必然性<span class=\"pg\">P150</span>", "a": "社会形态更替归根结底是社会基本矛盾运动的结果，其中生产力的发展具有最终的决定意义。生产力与生产关系矛盾运动的规律性，从根本上规定了社会形态更替的必然性。"}, {"id": "单74", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P155-156", "q": "两对社会基本矛盾的关系", "qh": "两对社会基本矛盾之间的关系：<span class=\"rd\">【生产力和生产关系的矛盾是更为基本的矛盾，它决定经济基础和上</span><span class=\"rd\">层建筑的矛盾的产生和发展；经济基础和上层建筑的矛盾也会影响和制约生产力和生产关系的矛盾，生产</span><span class=\"rd\">力和生产关系矛盾的最终解决有赖于经济基础和上层建筑矛盾的解决】</span><span class=\"pg\">P155-156</span>", "a": "生产力和生产关系的矛盾是更为基本的矛盾，它决定经济基础和上层建筑的矛盾的产生和发展；经济基础和上层建筑的矛盾也会影响和制约生产力和生产关系的矛盾，生产力和生产关系矛盾的最终解决有赖于经济基础和上层建筑矛盾的解决。"}, {"id": "单75", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P157-159", "q": "社会主要矛盾的转化原理", "qh": "社会主要矛盾的转化原理<span class=\"pg\">P157-159</span>(1)转化原理：社会主要矛盾不是一成不变的，在一定条件下会朝着两个方面转化：<span class=\"rd\">【一是社会主要矛盾双</span><span class=\"rd\">方的内容发生一定变化；二是矛盾地位发生变化，原来的主要矛盾转化为从属地位的矛盾，而原来的某个</span><span class=\"rd\">非主要矛盾则上升为占支配地位的主要矛盾】</span>。由于社会主要矛盾发生变化，它所影响的社会发展过程也发生变化，主要表现为社会发展过程中出现新的阶段性特点(2)其实践意义：当正确把握社会主要矛盾时，社会主义建设事业会朝着正确方向发展。我国社会主要矛盾已经转化为<span class=\"rd\">【人民日益增长的美好生活需要和不平衡不充分的发展】</span>之间的矛盾。抓住这一主要矛盾，就找到正确理解和把握新时代的钥匙。我们要紧紧扭住这一主要矛盾不放，不断推进我国经济社会发展", "a": "社会主要矛盾不是一成不变的，在一定条件下会朝着两个方面转化：一是社会主要矛盾双方的内容发生一定变化；二是矛盾地位发生变化，原来的主要矛盾转化为从属地位的矛盾，而原来的某个非主要矛盾则上升为主要矛盾。我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾，抓住这一主要矛盾就找到了正确理解和把握新时代的钥匙。"}, {"id": "单76", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P159-160", "q": "阶级斗争是阶级社会发展的直接动力", "qh": "<span class=\"rd\">【阶级斗争】</span>是阶级社会发展的直接动力。阶级是一个<span class=\"rd\">【经济范畴、历史范畴】</span>。阶级斗争根源于阶级之间<span class=\"rd\">【物质利益的根本对立】</span><span class=\"pg\">P159-160</span>", "a": "阶级是一个经济范畴，也是一个历史范畴。阶级斗争是阶级利益根本冲突的对抗阶级之间的对立和斗争，根源于阶级之间物质利益的根本对立，根源于社会经济关系的冲突。一切阶级斗争归根结底都是围绕经济利益这个轴心展开的。"}, {"id": "单77", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P162", "q": "革命的实质和根本原因", "qh": "革命是阶级斗争的最高形式，其实质是<span class=\"rd\">【革命阶级推翻反动阶级的统治，用新的社会制度代替旧的社</span><span class=\"rd\">会制度】</span>。<span class=\"rd\">【生产力的发展和旧的生产关系、经济基础的发展和旧的上层建筑之间出现矛盾冲突】</span>，是革命爆发的根本原因<span class=\"pg\">P162</span>", "a": "革命或狭义的社会革命，是阶级斗争的最高形式，其实质是革命阶级推翻反动阶级的统治，用新的社会制度代替旧的社会制度，国家政权从反动阶级手里转移到革命阶级手里是实现社会形态变革的首要的、基本的标志。革命爆发的根本原因在于生产力的发展和旧的生产关系、经济基础的发展和旧的上层建筑之间出现矛盾冲突。"}, {"id": "单78", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P165-167", "q": "科学技术在社会发展中的作用", "qh": "科学技术在社会发展中的作用：科技革命是推动经济和社会发展的强大杠杆。<span class=\"rd\">【①对生产方式产生了深</span><span class=\"rd\">刻影响。改变了社会生产力的构成要素；改变了人们的劳动形式；改变了社会经济结构；②对生活方式产生了</span><span class=\"rd\">巨大影响；③促进了思维方式的变革】</span><span class=\"pg\">P165-167</span>", "a": "科技革命是推动经济和社会发展的强大杠杆。第一，对生产方式产生了深刻影响：改变了社会生产力的构成要素，改变了人们的劳动形式，改变了社会经济结构；第二，对生活方式产生了巨大影响；第三，促进了思维方式的变革。"}, {"id": "单79", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P169-170", "q": "文化在社会发展中的作用", "qh": "文化在社会发展中的作用<span class=\"pg\">P169-170</span>(1)文化是推动社会发展的重要力量(2)文化对社会发展的影响：<span class=\"rd\">【为社会发展提供思想指引；为社会发展提供精神动力；为社会发展提供凝聚</span><span class=\"rd\">力量】</span>", "a": "文化是推动社会发展的重要力量。文化对社会发展的影响表现为：为社会发展提供思想指引；为社会发展提供精神动力；为社会发展提供凝聚力量。"}, {"id": "单80", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P171-172", "q": "两种历史观在历史创造者问题上的对立", "qh": "两种历史观在历史创造者问题上的对立：唯物史观与唯心史观的对立，在历史创造者问题上表现为群众史观与英雄史观的对立。英雄史观从社会意识决定社会存在的基本前提出发，<span class=\"rd\">【否认物质资料的生产方</span><span class=\"rd\">式是社会发展的决定力量，抹杀人民群众的历史作用，宣扬少数英雄人物创造历史】</span>。群众史观<span class=\"rd\">【认为历</span><span class=\"rd\">史的创造者不是个别英雄，而是人民群众】</span><span class=\"pg\">P171-172</span>", "a": "唯物史观与唯心史观的对立，在历史创造者问题上表现为群众史观与英雄史观的对立。英雄史观从社会意识决定社会存在的基本前提出发，否认物质资料的生产方式是社会发展的决定力量，抹杀人民群众的历史作用，宣扬少数英雄人物创造历史；群众史观认为历史的创造者不是个别英雄，而是人民群众。"}, {"id": "单81", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P172-174", "q": "唯物史观考察历史创造者的方法论原则", "qh": "唯物史观在考察历史创造者问题上坚持的方法论原则：<span class=\"rd\">【唯物史观立足于现实的人及其本质来把握历</span><span class=\"rd\">史的创造者；立足于整体的社会历史过程来探究谁是历史的创造者；从社会历史发展的必然性入手来考察</span><span class=\"rd\">和说明谁是历史的创造者；从人与历史关系的不同层次上考察谁是历史的创造者】</span><span class=\"pg\">P172-174</span>", "a": "第一，立足于现实的人及其本质来把握历史的创造者；第二，立足于整体的社会历史过程来探究谁是历史的创造者；第三，从社会历史发展的必然性入手来考察和说明谁是历史的创造者；第四，从人与历史关系的不同层次上考察谁是历史的创造者。"}, {"id": "单82", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P173", "q": "人的本质", "qh": "马克思指出人的本质在其现实性上是<span class=\"rd\">【一切社会关系的总和】</span>。人的本质属性是<span class=\"rd\">【社会属性】</span><span class=\"pg\">P173</span>", "a": "马克思指出，\"人的本质不是单个人所固有的抽象物，在其现实性上，它是一切社会关系的总和\"。这就告诉我们，人的本质属性是社会属性，而不是自然属性；人的本质属性表现在各种社会关系中；人的本质是变化发展的。"}, {"id": "单83", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P177", "q": "群众观点与群众路线", "qh": "马克思主义(党/无产阶级政党)群众观点的主要内容：<span class=\"rd\">【坚信人民群众自己解放自己的观点，全心全意</span><span class=\"rd\">为人民服务的观点，一切向人民群众负责的观点，虚心向人民群众学习的观点】</span>。群众路线是群众观点的具体应用，即<span class=\"rd\">【一切为了群众，一切依靠群众，从群众中来，到群众中去】</span><span class=\"pg\">P177</span>", "a": "马克思主义群众观点的主要内容包括：坚信人民群众自己解放自己的观点，全心全意为人民服务的观点，一切向人民群众负责的观点，虚心向人民群众学习的观点。群众路线是群众观点的具体应用，即一切为了群众，一切依靠群众，从群众中来，到群众中去。"}, {"id": "单84", "ch": "第三章 人类社会及其发展规律", "type": "单选", "page": "P179", "q": "评价历史人物的方法", "qh": "评价历史人物时应该<span class=\"rd\">【坚持历史分析方法和阶级分析方法】</span><span class=\"pg\">P179</span>", "a": "评价历史人物应坚持历史分析方法和阶级分析方法。不能用今天的时代条件、发展水平、认识水平去衡量和要求前人，不能苛求前人干出只有后人才能干出的业绩来。"}, {"id": "简22", "ch": "第三章 人类社会及其发展规律", "type": "简答", "page": "P129", "q": "物质生产方式是社会存在和发展的基础及决定力量", "qh": "为什么说物质生产方式是社会存在和发展的基础及决定力量(生产方式在社会发展中的作用)<span class=\"pg\">P129</span>", "a": "（1）它是人类社会赖以存在和发展的基础，是人类其他一切活动的首要前提；（2）它决定社会的结构、性质和面貌，制约着人们的经济生活、政治生活和精神生活等全部社会生活；（3）它的变化发展决定整个社会历史的变化发展，决定社会形态从低级向高级的更替和发展。", "o": "生产方式是社会历史发展的决定力量\n(1)它是人类社会赖以存在和发展的基础，是人类其他一切活动的首要前提\n(2)它决定社会的结构、性质和面貌，制约着人们的经济生活、政治生活和精神生活等全部社会生活\n(3)它的变化发展决定整个社会历史的变化发展，决定社会形态从低级向高级的更替和发展"}, {"id": "简23", "ch": "第三章 人类社会及其发展规律", "type": "简答", "page": "P137-139", "q": "生产力与生产关系的关系及其矛盾运动规律的意义", "qh": "生产力与生产关系的关系及其矛盾运动规律的意义<span class=\"pg\">P137-139</span>", "a": "①生产力决定生产关系：生产力状况决定生产关系的性质，生产力的发展决定生产关系的改变；②生产关系对生产力具有能动的反作用：适合时起推动作用，不适合时起阻碍作用。意义：第一次科学地确立了生产力发展是\"社会进步的最高标准\"，把生产力与生产关系矛盾运动的规律作为判断时代变革的客观依据；是马克思主义政党制定路线、方针和政策的重要依据。", "o": "(1)关系：①<span class=\"rd\">生产力决定生产关系</span>。生产力是居支配地位、起决定作用的方面。生产力状况决定生产关系的性质；生产力的发展决定生产关系的改变。②<span class=\"rd\">生产关系对生产力具有能动的反作用</span>。当生产关系适合生产力发展的客观要求时，对生产力的发展起推动作用；当生产关系不适合生产力发展的客观要求时，就会阻碍生产力的发展\n(2)意义：①在人类思想史上彻底否定了单纯以道德作为评判历史功过是非标准的思想体系，<span class=\"rd\">第一次科学地</span><span class=\"rd\">确立了生产力发展是“社会进步的最高标准”，把生产力与生产关系矛盾运动的规律作为判断时代变革的</span><span class=\"rd\">客观依据</span>。②<span class=\"rd\">是马克思主义政党制定路线、方针和政策的重要依据</span>"}, {"id": "简24", "ch": "第三章 人类社会及其发展规律", "type": "简答", "page": "P140", "q": "观念上层建筑和政治上层建筑的关系", "qh": "观念上层建筑和政治上层建筑的关系<span class=\"pg\">P140</span>", "a": "政治上层建筑是在一定意识形态指导下建立起来的，是统治阶级意志的体现；政治上层建筑一旦形成，就成为一种现实的力量，影响并制约着人们的思想理论观点。", "o": "(1)政治上层建筑是在一定意识形态指导下建立起来的，是统治阶级意志的体现\n(2)政治上层建筑一旦形成，就成为一种现实的力量，影响并制约着人们的思想理论观点"}, {"id": "简25", "ch": "第三章 人类社会及其发展规律", "type": "简答", "page": "P149", "q": "社会形态更替统一性与多样性的表现", "qh": "社会形态更替统一性、多样性的表现<span class=\"pg\">P149</span>", "a": "依据经济基础特别是生产关系的不同性质，社会历史可划分为五种社会形态：原始社会、奴隶社会、封建社会、资本主义社会和共产主义社会（社会主义社会是共产主义社会的第一阶段）。这五种社会形态的依次更替表现了统一性。多样性表现为：有些国家超越了一个甚至几个社会形态而跨越式地向前发展；有些国家社会形态性质不够典型甚至多种特征交叉渗透；同一社会形态在不同国家也显现出不同特点。", "o": "(1)依据经济基础特别是生产关系的不同性质，社会历史可划分为五种(经济)社会形态：<span class=\"rd\">原始社会、奴</span><span class=\"rd\">隶社会、封建社会、资本主义社会和共产主义社会</span>。社会主义社会是共产主义社会的第一阶段(初级阶段或低级阶段)。这五种社会形态的依次更替，表现了社会形态更替的统一性\n(2)<span class=\"rd\">有些国家</span>在发展中<span class=\"rd\">经历了</span>几种<span class=\"rd\">社会形态依次更替</span>的典型过程，也<span class=\"rd\">有些国家</span>在发展中超越了一个甚至几个社会形态而<span class=\"rd\">跨越式</span>地<span class=\"rd\">向前发展</span>；<span class=\"rd\">有些国家</span>在历史发展的<span class=\"rd\">一定阶段上社会形态性质不够典型</span>，甚至多种社会形态特征交叉渗透；<span class=\"rd\">有些国家</span>在一定时期由较为落后的社会形态快速<span class=\"rd\">跃进为先进的社会形态</span>，而<span class=\"rd\">有些国家</span>的社会形态<span class=\"rd\">长期</span>陷于<span class=\"rd\">停滞状态</span>；<span class=\"rd\">即使</span>是<span class=\"rd\">同一种社会形态</span>，在<span class=\"rd\">不同国家</span>也会显现出<span class=\"rd\">不同特点</span>。这些体现了社会形态更替形式的多样性"}, {"id": "简26", "ch": "第三章 人类社会及其发展规律", "type": "简答", "page": "P154-156", "q": "社会基本矛盾在历史发展中的作用", "qh": "社会基本矛盾在历史发展中的作用<span class=\"pg\">P154-156</span>", "a": "（1）生产力是社会基本矛盾运动中最基本的动力因素，是人类社会发展和进步的最终决定力量；（2）社会基本矛盾特别是生产力和生产关系的矛盾，决定着社会中其他矛盾的存在和发展；（3）社会基本矛盾具有不同的表现形式和解决方式，并从根本上影响和促进社会形态的变化和发展。", "o": "社会基本矛盾是历史发展的根本动力\n(1)生产力是社会基本矛盾运动中最基本的动力因素，是人类社会发展和进步的最终决定力量\n(2)社会基本矛盾特别是生产力和生产关系的矛盾，决定着社会中其他矛盾的存在和发展\n(3)社会基本矛盾具有不同的表现形式和解决方式，并从根本上影响和促进社会形态的变化和发展"}, {"id": "简27", "ch": "第三章 人类社会及其发展规律", "type": "简答", "page": "P162", "q": "革命在社会发展中的作用", "qh": "革命在社会发展中的作用<span class=\"pg\">P162</span>", "a": "（1）革命是历史的火车头，是社会进步和政治进步的强大推动力，是实现社会形态更替的重要手段和决定性环节；（2）能充分发挥人民群众创造历史的积极性和伟大作用；（3）能够极大地教育和锻炼包括革命阶级在内的广大人民群众。", "o": "(1)革命是历史的火车头，是社会进步和政治进步的强大推动力，是实现社会形态更替的重要手段和决定性环节\n(2)能充分发挥人民群众创造历史的积极性和伟大作用\n(3)能够极大地教育和锻炼包括革命阶级在内的广大人民群众"}, {"id": "简28", "ch": "第三章 人类社会及其发展规律", "type": "简答", "page": "P164-165", "q": "改革在社会发展中的作用", "qh": "改革在社会发展中的作用<span class=\"pg\">P164-165</span>", "a": "（1）改革是社会制度的自我调整和完善，是推动社会发展的重要动力；（2）改革是解决社会基本矛盾、促进生产力发展、推动社会进步的有效途径和手段；（3）中国的社会主义改革是社会主义制度的自我完善和自我发展，改革是社会主义社会发展的强大动力。", "o": "(1)改革是社会制度的自我调整和完善，是推动社会发展的重要动力\n(2)改革是解决社会基本矛盾、促进生产力发展、推动社会进步的有效途径和手段\n(3)中国的社会主义改革是社会主义制度的自我完善和自我发展，改革是社会主义社会发展的强大动力"}, {"id": "简29", "ch": "第三章 人类社会及其发展规律", "type": "简答", "page": "P174-178", "q": "人民群众是历史创造者及坚持群众路线的现实意义", "qh": "人民群众是历史创造者的原理以及坚持党的群众路线的现实意义<span class=\"pg\">P174-178</span>", "a": "人民群众是社会历史的主体，是历史的创造者。从质上看是指一切对社会历史发展起推动作用的人，从量上看是指社会人口中的绝大多数。人民群众是社会物质财富的创造者、社会精神财富的创造者、社会变革的决定力量。群众路线是我们党的生命线和根本工作路线，要把群众路线贯彻到治国理政全部活动之中，坚持以人民为中心的发展思想。", "o": "(1)<span class=\"rd\">人民群众是社会历史的主体，是历史的创造者</span>。从质上看，人民群众指一切对社会历史发展起推动作用的人；从量上看，人民群众指社会人口中的绝大多数。在推动社会历史发展过程中，人民群众起着决定性的作用：<span class=\"rd\">人民群众是社会物质财富的创造者；是社会精神财富的创造者；是社会变革的决定力量</span>\n(2)群众路线<span class=\"rd\">是我们党的生命线和根本工作路线，是党在革命、建设改革中不断取得胜利的重要法宝</span>。要把群众路线贯彻到治国理政全部活动之中。无论是作决策还是抓工作、促落实，都要坚持人民至上，坚持以人民为中心的发展思想，始终走好群众路线"}, {"id": "单85", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P186", "q": "商品经济的基本规律", "qh": "商品经济的基本规律即<span class=\"rd\">【价值规律】</span><span class=\"pg\">P186</span>", "a": "价值规律是商品生产和商品交换的基本规律，即商品经济的基本规律。"}, {"id": "单86", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P187-188", "q": "商品的二因素", "qh": "商品的二因素：<span class=\"rd\">【使用价值和价值】</span><span class=\"pg\">P187-188</span>(1)<span class=\"rd\">【使用价值】</span>指商品能满足人的某种需要的有用性，是商品的自然属性(2)<span class=\"rd\">【价值】</span>是凝结在商品中的无差别的一般人类劳动，是商品特有的社会属性(3)商品的使用价值和价值之间是对立统一的关系。对立性表现在<span class=\"rd\">【商品的使用价值和价值是相互排斥的，</span><span class=\"rd\">二者不可兼得】</span>。统一性表现在<span class=\"rd\">【商品同时具有使用价值和价值两个因素】</span>", "a": "商品是用来交换、能满足人的某种需要的劳动产品，具有使用价值和价值两个因素或两种属性，是使用价值和价值的矛盾统一体。使用价值是指商品能满足人的某种需要的有用性，反映的是人与自然之间的物质关系，是商品的自然属性；价值是凝结在商品中的无差别的一般人类劳动，即人的脑力和体力的耗费，是商品特有的社会属性。商品的使用价值和价值之间是对立统一的关系：其对立性表现在，商品的使用价值和价值是相互排斥的，二者不可兼得；其统一性表现在，作为商品，必须同时具有使用价值和价值两个因素。"}, {"id": "单87", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P189", "q": "劳动的二重性", "qh": "生产商品的劳动具有二重性：<span class=\"rd\">【具体劳动和抽象劳动】</span><span class=\"pg\">P189</span>(1)<span class=\"rd\">【具体劳动】</span>指生产一定使用价值的具体形式的劳动(2)<span class=\"rd\">【抽象劳动】</span>指撇开一切具体形式的、无差别的一般人类劳动，即人的脑力和体力的耗费(3)商品二因素与劳动二重性的关系：<span class=\"rd\">【生产商品的具体劳动创造商品的使用价值，抽象劳动形成商品的价</span><span class=\"rd\">值。劳动的二重性决定了商品的二因素】</span>(4)具体劳动与抽象劳动是<span class=\"rd\">【对立统一的关系】</span>：它们在时间上和空间上是统一的，是商品生产者的同一劳动过程不可分割的两个方面；具体劳动所反映的是人与自然的关系，是劳动的自然属性，抽象劳动所反映的是商品生产者的社会关系，是劳动的社会属性", "a": "商品是劳动产品，生产商品的劳动具有二重性，即具体劳动和抽象劳动。具体劳动是指生产一定使用价值的具体形式的劳动；抽象劳动是指撇开一切具体形式的、无差别的一般人类劳动，即人的脑力和体力的耗费。生产商品的具体劳动创造商品的使用价值，抽象劳动形成商品的价值——劳动的二重性决定了商品的二因素。具体劳动和抽象劳动也是对立统一的关系：一方面，它们在时间上和空间上是统一的，是商品生产者的同一劳动过程不可分割的两个方面；另一方面，具体劳动所反映的是人与自然的关系，是劳动的自然属性，而抽象劳动所反映的是商品生产者的社会关系，是劳动的社会属性。"}, {"id": "单88", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P190", "q": "商品价值量与劳动生产率", "qh": "商品的价值量与生产商品所耗费的社会必要劳动时间成正比，与劳动生产率<span class=\"rd\">【成反比】</span><span class=\"pg\">P190</span>", "a": "决定商品价值量的不是生产商品的个别劳动时间，而是社会必要劳动时间。劳动生产率水平越高，单位时间内生产的商品数量越多，生产每件商品所需要的社会必要劳动时间就越少，单位商品的价值量就越小，反之就越大。商品的价值量与生产商品所耗费的社会必要劳动时间成正比，与劳动生产率成反比。"}, {"id": "单89", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P190", "q": "社会必要劳动时间", "qh": "社会必要劳动时间是在现有的社会正常的生产条件下，在<span class=\"rd\">【社会平均的劳动熟练程度和劳动强度】</span>下制造某种使用价值所需要的劳动时间<span class=\"pg\">P190</span>", "a": "社会必要劳动时间是在现有的社会正常的生产条件下，在社会平均的劳动熟练程度和劳动强度下制造某种使用价值所需要的劳动时间。"}, {"id": "单90", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P191", "q": "价值形式发展的四个阶段", "qh": "商品的价值形式经历了四个阶段：<span class=\"rd\">【简单的或偶然的价值形式、总和的或扩大的价值形式、一般价值</span><span class=\"rd\">形式、货币形式】</span><span class=\"pg\">P191</span>", "a": "从历史上看，商品价值形式的发展经历了四个阶段，即简单的或偶然的价值形式、总和的或扩大的价值形式、一般价值形式，以及货币形式。"}, {"id": "单91", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P191", "q": "货币的本质和职能", "qh": "货币是在长期交换过程中形成的<span class=\"rd\">【固定充当一般等价物的商品】</span>(货币的本质)。货币具有<span class=\"rd\">【价值尺度、</span><span class=\"rd\">流通手段、贮藏手段、支付手段和世界货币】</span>等职能。<span class=\"rd\">【价值尺度和流通手段】</span>是最基本的职能<span class=\"pg\">P191</span>", "a": "货币是在长期交换过程中形成的固定充当一般等价物的商品，是商品经济内在矛盾发展的产物，货币的本质体现一种社会关系。货币具有价值尺度、流通手段、贮藏手段、支付手段和世界货币等职能，其中价值尺度和流通手段是最基本的职能。"}, {"id": "单92", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P192", "q": "价值规律的内容与表现形式", "qh": "价值规律：<span class=\"pg\">P192</span>(1)是商品生产和商品交换的基本规律(2)主要内容和客观要求：<span class=\"rd\">【商品的价值量由生产商品的社会必要劳动时间决定，商品交换以价值量为基础，</span><span class=\"rd\">按照等价交换的原则进行】</span>(3)表现形式：<span class=\"rd\">【商品的价格围绕商品的价值自发波动】</span>", "a": "价值规律的主要内容和客观要求是：商品的价值量由生产商品的社会必要劳动时间决定，商品交换以价值量为基础，按照等价交换的原则进行。在商品经济中，价值规律的表现形式是：商品的价格围绕商品的价值自发波动。"}, {"id": "单93", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P193-194", "q": "商品经济与交换", "qh": "商品经济是以交换为目的的经济形式。<span class=\"rd\">【交换】</span>是解决私人劳动和社会劳动之间矛盾的唯一途径<span class=\"pg\">P193-194</span>", "a": "商品经济是以交换为目的的经济形式。私人劳动和社会劳动的矛盾构成私有制基础上商品经济的基本矛盾；商品经济的交换本质正是由私人劳动和社会劳动的矛盾决定的，交换是解决私人劳动和社会劳动之间矛盾的唯一途径。"}, {"id": "单94", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P197", "q": "马克思劳动价值论的意义", "qh": "马克思劳动价值论的意义：<span class=\"rd\">【①扬弃了英国古典政治经济学的观点，为剩余价值论的创立奠定了基础。②</span><span class=\"rd\">揭示了私有制条件下商品经济的基本矛盾，为从物与物的关系背后揭示人与人的关系提供了理论依据。③揭</span><span class=\"rd\">示了商品经济的一般规律，对理解社会主义市场经济具有指导意义】</span><span class=\"pg\">P197-198</span>", "a": "第一，马克思劳动价值论扬弃了英国古典政治经济学的观点，为剩余价值论的创立奠定了基础；第二，马克思劳动价值论揭示了私有制条件下商品经济的基本矛盾，为从物与物的关系背后揭示人与人的关系提供了理论依据；第三，马克思劳动价值论揭示了商品经济的一般规律，对理解社会主义市场经济具有指导意义。"}, {"id": "单95", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P203", "q": "资本主义的产生", "qh": "资本主义萌芽于14世纪末15世纪初地中海沿岸的一些城市，其产生途径：<span class=\"rd\">【从小商品经济中分化出</span><span class=\"rd\">来；从商人和高利贷者转化而来】</span><span class=\"pg\">P203</span>", "a": "资本主义萌芽于14世纪末15世纪初地中海沿岸的一些城市。资本主义产生的途径有两个：一是从小商品经济中分化出来，二是从商人和高利贷者转化而来（作坊主丧失独立生产者身份，连同其帮工和学徒成了商人和高利贷者的雇佣工人，商人和高利贷者则成为工业资本家）。"}, {"id": "单96", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P205", "q": "资本原始积累的途径", "qh": "资本原始积累主要的途径：<span class=\"rd\">【用暴力手段剥夺农民的土地；用暴力手段掠夺货币财富】</span><span class=\"pg\">P205</span>", "a": "资本原始积累主要是通过两个途径进行的：一是用暴力手段剥夺农民的土地（这是资本原始积累过程的基础，在英国表现得最为典型），二是用暴力手段掠夺货币财富。"}, {"id": "单97", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P208-209", "q": "劳动力商品的特点与资本", "qh": "劳动力商品的特点：<span class=\"pg\">P208-209</span>(1)具有价值和使用价值。劳动力的价值由生产、发展、维持和延续劳动力所必需的生活必需品的价值决定，包括：<span class=\"rd\">【维持劳动者本人生存所必需的生活资料的价值；维持劳动者家属的生存所必需的生活资料的价值；</span><span class=\"rd\">劳动者接受教育和训练所支出的费用】</span>。劳动力价值的构成包含<span class=\"rd\">【历史和道德的因素】</span>(2)它的使用价值是价值的源泉，在消费过程中<span class=\"rd\">【能够创造新的价值】</span>，而且这个新的价值比劳动力本身的价值更大。一旦货币购买的<span class=\"rd\">【劳动力】</span>带来剩余价值，货币也就变成了资本。资本是能够带来剩余价值的价值", "a": "劳动力商品也具有价值和使用价值。劳动力的价值由生产、发展、维持和延续劳动力所必需的生活必需品的价值决定，包括三个部分：（1）维持劳动者本人生存所必需的生活资料的价值；（2）维持劳动者家属的生存所必需的生活资料的价值；（3）劳动者接受教育和训练所支出的费用；由于劳动力价值的构成包含历史和道德的因素，在不同的国家或在同一国家的不同历史时期，劳动者所必需的生活资料的数量和构成是有区别的。劳动力商品在使用价值上有一个很突出的特点，就是它的使用价值是价值的源泉，在消费过程中能够创造新的价值，而且这个新的价值比劳动力本身的价值更大。而一旦货币购买的劳动力带来剩余价值，货币也就变成了资本——资本是能够带来剩余价值的价值。"}, {"id": "单98", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P209", "q": "剩余价值的源泉", "qh": "剩余价值是由<span class=\"rd\">【雇佣工人的剩余劳动】</span>创造的<span class=\"pg\">P209</span>", "a": "剩余价值是由雇佣工人的剩余劳动创造的。雇佣工人的劳动分为两部分：一部分是必要劳动，用于再生产劳动力价值；另一部分是剩余劳动，用于无偿地为资本家生产剩余价值。"}, {"id": "单99", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P210", "q": "资本主义生产过程的二重性", "qh": "资本主义生产过程是<span class=\"rd\">【劳动过程与价值增殖过程】</span>的统一<span class=\"pg\">P210</span>(1)资本主义劳动过程的特点：工人在资本家的监督下劳动，他们的劳动隶属于资本家；劳动的成果或者产品全部归资本家所有(2)价值增殖过程是剩余价值的生产过程，是超过劳动力价值的补偿这个一定点而延长了的价值形成过程", "a": "资本主义生产过程具有二重性：一方面是生产物质资料的劳动过程，另一方面是生产剩余价值的过程即价值增殖过程，资本主义生产过程是劳动过程和价值增殖过程的统一。由于资本主义劳动过程的要素都为资本家所占有，这就决定了资本主义劳动过程的两个特点：其一，工人在资本家的监督下劳动，他们的劳动隶属于资本家；其二，劳动的成果或者产品全部归资本家所有。所谓价值增殖过程，是超过劳动力价值的补偿这个一定点而延长了的价值形成过程。"}, {"id": "单100", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P214", "q": "超额剩余价值", "qh": "超额剩余价值的生产方法：<span class=\"rd\">【超额剩余价值】</span>指企业由于提高劳动生产率而使商品的个别价值低于社会价值的差额。在资本主义商品生产条件下，每个资本家总是力图不断改进技术，改善经营管理，提高劳动生产率，使其生产的商品的个别劳动时间少于社会必要劳动时间，个别价值低于社会价值，从而获得超额剩余价值<span class=\"pg\">P214</span>", "a": "超额剩余价值是指企业由于提高劳动生产率而使商品的个别价值低于社会价值的差额。在资本主义商品生产条件下，每个资本家总是力图不断改进技术，改善经营管理，提高劳动生产率，使其生产的商品的个别劳动时间少于社会必要劳动时间，个别价值低于社会价值，从而获得超额剩余价值。单个资本家改进技术的主观动机是追求超额剩余价值，但其客观后果则是整个社会各个生产部门的劳动生产率普遍提高，导致生活资料价值下降和必要劳动时间缩短，剩余劳动时间相对延长，整个资本家阶级普遍获得更多的相对剩余价值。"}, {"id": "单101", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P216-218", "q": "资本积累", "qh": "资本积累：<span class=\"pg\">P216-218</span>(1)是把剩余价值转化为资本，剩余价值的资本化(2)本质：<span class=\"rd\">【资本家不断利用无偿占有的工人创造的剩余价值来扩大自己的资本规模，进一步扩大和加强对</span><span class=\"rd\">工人的剥削和统治】</span>(3)源泉：<span class=\"rd\">【剩余价值】</span>(4)后果：<span class=\"rd\">【社会财富两极分化；资本有机构成提高；工人失业，形成相对过剩人口】</span>", "a": "把剩余价值转化为资本，或者说，剩余价值的资本化，就是资本积累；资本积累是资本主义扩大再生产的源泉。资本积累的本质，就是资本家不断地利用无偿占有的工人创造的剩余价值来扩大自己的资本规模，从而进一步扩大和加强对工人的剥削和统治。资本积累的源泉是剩余价值。资本积累的后果：资本积累不但是社会财富占有两极分化的重要原因，而且是资本主义社会失业现象产生的根源。"}, {"id": "单102", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P217-218", "q": "资本的构成", "qh": "由生产的技术水平所决定的生产资料和劳动力之间的比例叫作<span class=\"rd\">【资本的技术构成】</span>。不变资本和可变资本价值之间的比例叫作<span class=\"rd\">【资本的价值构成】</span>。由资本的技术构成决定并反映技术构成变化的资本价值构成叫作<span class=\"rd\">【资本的有机构成】</span><span class=\"pg\">P217-218</span>", "a": "这种由生产的技术水平所决定的生产资料和劳动力之间的比例，叫作资本的技术构成；不变资本和可变资本价值之间的比例，叫作资本的价值构成；这种由资本的技术构成决定并反映技术构成变化的资本价值构成，叫作资本的有机构成。在资本主义生产过程中，资本有机构成的提高是一般趋势，这是由资本的本性决定的。"}, {"id": "单103", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P216-218", "q": "资本主义生产目的、相对过剩人口", "qh": "资本主义生产的唯一动机和直接目的是<span class=\"rd\">【追求剩余价值】</span>。<span class=\"rd\">【相对过剩人口】</span>就是劳动力供给超过了资本的需要<span class=\"pg\">P218</span>", "a": "资本主义生产的唯一动机和直接目的就是追求剩余价值。在资本有机构成提高的情况下，由于可变资本的相对量的减少，资本对劳动力的需求日益相对减少，其结果就是不可避免地造成大批工人失业，形成相对过剩人口；所谓相对过剩人口，就是劳动力供给超过了资本的需要。相对过剩人口基本上有三种形式：流动的过剩人口、潜在的过剩人口、停滞的过剩人口。"}, {"id": "单104", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P220-221", "q": "影响资本周转快慢的因素", "qh": "影响资本周转快慢的因素：<span class=\"rd\">【资本周转的时间；生产资本的固定资本和流动资本的构成】</span><span class=\"pg\">P220-221</span>", "a": "影响资本周转快慢的因素有许多，关键的因素有两个：一是资本周转的时间，二是生产资本的固定资本和流动资本的构成。要加快资本周转速度，获得更多剩余价值，就要缩短资本周转时间，加快流动资本的周转速度。"}, {"id": "单105", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P221", "q": "社会再生产的核心问题", "qh": "社会再生产的核心问题是<span class=\"rd\">【社会总产品的实现问题】</span>，即社会总产品的<span class=\"rd\">【价值补偿和实物补偿问题】</span><span class=\"pg\">P221</span>", "a": "社会再生产的核心问题是社会总产品的实现问题，即社会总产品的价值补偿和实物补偿问题。"}, {"id": "单106", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P221", "q": "社会总产品的构成", "qh": "社会总产品<span class=\"pg\">P221</span>(1)是社会在一定时期(通常为一年)所生产的全部物质资料的总和(2)在物质形态上，根据最终用途分为<span class=\"rd\">【用于生产消费的生产资料、用于生活消费的消费资料】</span>", "a": "社会总产品就是社会在一定时期（通常为一年）所生产的全部物质资料的总和。社会总产品在物质形态上，根据其最终用途可以划分为用于生产消费的生产资料和用于生活消费的消费资料；相应地，社会生产可以划分为两大部类：第一部类（Ⅰ）由生产生产资料的部门所构成，其产品进入生产消费领域；第二部类（Ⅱ）由生产消费资料的部门所构成，其产品进入生活消费领域。"}, {"id": "单107", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P222-223", "q": "工资本质、剩余价值率与利润率", "qh": "在资本主义制度下，工人的工资是<span class=\"rd\">【劳动力的价值或价格】</span>，这是资本主义工资的本质。剩余价值率是剩余价值与<span class=\"rd\">【可变资本】</span>的比率，反映的是资本家对工人的剥削程度；利润率是剩余价值与<span class=\"rd\">【全部预付</span><span class=\"rd\">资本】</span>的比率，反映的是预付总资本的增殖程度<span class=\"pg\">P222-223</span>", "a": "在资本主义制度下，工人的工资是劳动力的价值或价格，这是资本主义工资的本质（工资表现为\"劳动的价格\"或工人全部劳动的报酬，这就模糊了工人必要劳动和剩余劳动的界限，掩盖了资本主义的剥削关系）。剩余价值率是剩余价值与可变资本的比率，反映的是资本家对工人的剥削程度；利润率则是剩余价值与全部预付资本的比率，反映的是预付总资本的增殖程度。"}, {"id": "单108", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P212", "q": "剩余价值率的另一表示方法", "qh": "剩余价值率还可以用<span class=\"rd\">【剩余劳动与必要劳动的比率】</span>，或者剩余劳动时间与必要劳动时间的比率来表示<span class=\"pg\">P212</span>", "a": "由于工人的必要劳动是用来再生产劳动力价值或可变资本的价值的，而剩余劳动则是生产剩余价值的，因此，剩余价值率还可以用剩余劳动与必要劳动的比率，或者剩余劳动时间与必要劳动时间的比率来表示。"}, {"id": "单109", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P223-224", "q": "平均利润的形成", "qh": "平均利润的形成：为了得到尽可能高的利润率和利润，<span class=\"rd\">【不同生产部门的资本家之间必然展开竞争】</span>，大量资本必然从利润率低的部门转投到利润率高的部门，从而导致利润率平均化。在利润率平均化的过程中，形成社会的平均利润率，按照平均利润率计算和获得的利润叫作平均利润。利润转化为平均利润，是<span class=\"rd\">【剩余价值规律和竞争规律作用的必然结果】</span>，体现着不同部门的资本家集团要求按照等量资本获得等量利润的原则来瓜分剩余价值的关系。平均利润率是<span class=\"rd\">【剩余价值总量与社会总资本的比率】</span><span class=\"pg\">P223-224</span>", "a": "为了得到尽可能高的利润率和尽可能多的利润，不同生产部门的资本家之间必然展开激烈的竞争，大量资本必然从利润率低的部门转投到利润率高的部门，从而导致利润率平均化。在利润率平均化的过程中，形成了社会的平均利润率，按照平均利润率计算和获得的利润叫作平均利润。利润转化为平均利润，是剩余价值规律和竞争规律作用的必然结果，体现着不同部门的资本家集团要求按照等量资本获得等量利润的原则来瓜分剩余价值的关系。平均利润率是剩余价值总量与社会总资本的比率。"}, {"id": "单110", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P224", "q": "生产价格", "qh": "生产价格是商品价值的转化形式，是<span class=\"rd\">【生产成本与平均利润】</span>之和<span class=\"pg\">P224</span>", "a": "利润转化为平均利润，价值也就转化为生产价格。生产价格是商品价值的转化形式，是生产成本与平均利润之和。在价值转化为生产价格的条件下，价值规律作用的形式发生了变化：商品不再以价值而是以生产价格为基础进行交换，市场价格的变动不再以价值为中心，而是以生产价格为中心。"}, {"id": "单111", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P225", "q": "剩余价值理论的意义", "qh": "剩余价值理论的意义：<span class=\"rd\">【揭露资本主义生产关系的剥削本质，阐明资产阶级与无产阶级之间阶级斗争</span><span class=\"rd\">的经济根源，指出无产阶级革命的历史必然性；是马克思经济学说的核心内容和基石，是无产阶级反对资</span><span class=\"rd\">产阶级、揭示资本主义制度剥削本质的锐利武器】</span><span class=\"pg\">P225</span>", "a": "马克思通过分析剩余价值的生产、积累、流通以及分配过程，揭示了资本主义生产关系的剥削本质，阐明了资产阶级与无产阶级之间阶级斗争的经济根源，指出了无产阶级革命的历史必然性。剩余价值理论是马克思经济学说的核心内容和基石，是无产阶级反对资产阶级、揭示资本主义制度剥削本质的锐利武器。"}, {"id": "单112", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P225", "q": "资本主义的基本矛盾", "qh": "<span class=\"rd\">【生产社会化和生产资料资本主义私人占有之间的矛盾】</span>是资本主义的基本矛盾<span class=\"pg\">P225</span>", "a": "生产社会化和生产资料资本主义私人占有之间的矛盾，是资本主义的基本矛盾。"}, {"id": "单113", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P226-227", "q": "资本主义经济危机", "qh": "<span class=\"rd\">【生产(相对)过剩】</span>是资本主义经济危机的本质特征。资本主义经济危机爆发的根本原因是<span class=\"rd\">【资本主</span><span class=\"rd\">义的基本矛盾】</span><span class=\"pg\">P226-227</span>", "a": "资本主义发展到一定阶段，就会发生以生产过剩为基本特征的经济危机。生产过剩是资本主义经济危机的本质特征，但是这种过剩是相对过剩，即相对于劳动人民有支付能力的需求来说社会生产的商品显得过剩，而不是与劳动人民的实际需要相比的绝对过剩。资本主义经济危机爆发的根本原因是资本主义的基本矛盾，这一基本矛盾具体表现在两个方面：其一，生产无限扩大的趋势与劳动人民有支付能力的需求相对缩小的矛盾；其二，单个企业内部生产的有组织性和整个社会生产的无政府状态之间的矛盾。"}, {"id": "单114", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P227-228", "q": "社会资本再生产的周期", "qh": "社会资本再生产的周期包括四个阶段：<span class=\"rd\">【危机(基本、必经阶段)、萧条、复苏和高涨】</span><span class=\"pg\">P227-228</span>", "a": "资本主义经济危机具有周期性，这是由资本主义基本矛盾运动的阶段性决定的。社会资本再生产的周期一般包括四个阶段，即危机、萧条、复苏和高涨。这四个阶段是相互联系的，其中危机阶段是周期的基本阶段；资本主义的再生产不一定都经过四个阶段，但是危机阶段是必经阶段，没有危机阶段，就不存在资本主义再生产的周期性。"}, {"id": "单115", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P230", "q": "资本主义国家的本质", "qh": "资本主义国家本质上是<span class=\"rd\">【资产阶级进行阶级统治的工具】</span><span class=\"pg\">P230</span>", "a": "资本主义国家本质上是资产阶级进行阶级统治的工具。"}, {"id": "单116", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P231", "q": "资本主义国家的政权组织形式", "qh": "资本主义国家政权组织形式是<span class=\"rd\">【分权(包括立法权、行政权、司法权)制衡】</span>。立法权属于<span class=\"rd\">【国会】</span><span class=\"pg\">P231</span>", "a": "资本主义国家政权采取分权制衡的组织形式，即国家的立法权、行政权、司法权分别由三个权力主体独立行使，形成各主体之间的\"制衡\"。以美国为例，在这种政权结构中，立法权属于由参、众两院组成的合众国国会，国会的立法权受到宪法保护和严格限制；行政权由行政首脑即总统来行使；司法权属于最高法院及下级法院，法院独立于总统和国会。"}, {"id": "单117", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P233", "q": "资本主义政治制度的本质", "qh": "资本主义政治制度本质上是<span class=\"rd\">【资产阶级实行政治统治和社会管理的手段和方式】</span><span class=\"pg\">P233</span>", "a": "资本主义政治制度本质上是资产阶级实行政治统治和社会管理的手段和方式，是为资产阶级专政服务的，因此它不可避免地有其阶级的和历史的局限性。"}, {"id": "单118", "ch": "第四章 资本主义的本质及规律", "type": "单选", "page": "P233-235", "q": "资本主义政治制度的进步作用与局限性", "qh": "资本主义政治制度在人类社会历史发展进程中的进步作用和局限性<span class=\"pg\">P233-235</span>(1)进步作用：<span class=\"rd\">【①在战胜封建社会的生产方式，保护、促进和完善资本主义生产方式方面起重要作用，推</span><span class=\"rd\">动社会生产力大幅度发展，促进社会进步。②使人们摆脱封建专制主义条件下的分封割据状态、等级压迫</span><span class=\"rd\">制度和人身依附关系，使人们享有比在封建专制主义条件下更多的政治自由，历史性地推进人的发展，促</span><span class=\"rd\">进人类的进步。③在其历史发展进程中积累相当丰富的政治统治和社会管理经验，对推动社会进步同样具</span><span class=\"rd\">有重要的积极意义】</span>(2)局限性：<span class=\"rd\">【①资本主义的民主是金钱操纵下的民主，是资产阶级精英统治下的民主。资本主义政治制度</span><span class=\"rd\">中的选举是有钱人的游戏，是资本玩弄民意的过程。②法律名义上的平等掩盖着事实上的不平等。③资本主</span><span class=\"rd\">义国家的政党制是维护资产阶级统治的政治制度。④政党恶斗相互掣肘，决策效率低下，激化社会矛盾】</span>", "a": "（进步作用）第一，资本主义政治制度作为上层建筑，在战胜封建社会的生产方式，保护、促进和完善资本主义生产方式方面起了重要作用，推动社会生产力大幅度发展，促进了社会进步；第二，它使人们摆脱了封建专制主义条件下的分封割据状态、等级压迫制度和人身依附关系，因而使人们享有了比在封建专制主义条件下更多的政治自由，历史性地推进了人的发展，促进了人类的进步；第三，资本主义政治制度在其历史发展进程中积累了相当丰富的政治统治和社会管理经验，这对推动社会进步同样具有十分重要的积极意义。（局限性）第一，资本主义的民主是金钱操纵下的民主，实际是资产阶级精英统治下的民主（资本主义政治制度中的选举事实上是有钱人的游戏，是资本玩弄民意的过程）；第二，法律名义上的平等掩盖着事实上的不平等；第三，资本主义国家的政党制是一种维护资产阶级统治的政治制度。"}, {"id": "简30", "ch": "第四章 资本主义的本质及规律", "type": "简答", "page": "P187", "q": "商品经济得以产生的社会历史条件", "qh": "商品经济得以产生的社会历史条件<span class=\"pg\">P187</span>", "a": "商品经济得以产生的社会历史条件有两个：一是存在社会分工（所谓社会分工，是指社会劳动划分和独立化为不同部门和行业）；二是生产资料和劳动产品属于不同的所有者。", "o": "(1)存在社会分工\n(2)生产资料和劳动产品属于不同的所有者"}, {"id": "简31", "ch": "第四章 资本主义的本质及规律", "type": "简答", "page": "P192-193", "q": "价值规律的作用及消极后果", "qh": "价值规律的作用及消极后果<span class=\"pg\">P192-193</span>", "a": "（积极作用）价值规律在市场配置资源过程中的作用表现在：第一，自发地调节生产资料和劳动力在社会各生产部门之间的分配比例；第二，自发地刺激社会生产力的发展；第三，自发地调节社会收入的分配。（消极后果）价值规律在对经济活动进行自发调节时，也会产生一些消极的后果：其一，导致社会资源浪费；其二，阻碍技术进步；其三，导致收入两极分化。", "o": "(1)在市场配置资源过程中的作用：<span class=\"rd\">自发地调节生产资料和劳动力在社会各生产部门之间的分配比例；</span><span class=\"rd\">自发地刺激社会生产力的发展；自发地调节社会收入的分配</span>\n(2)在对经济活动进行自发调节时的消极后果：<span class=\"rd\">导致社会资源浪费；阻碍技术进步；导致收入两极分化</span>"}, {"id": "简32", "ch": "第四章 资本主义的本质及规律", "type": "简答", "page": "P208", "q": "劳动力成为商品的基本条件", "qh": "劳动力成为商品的条件<span class=\"pg\">P208</span>", "a": "劳动力是指人的劳动能力，是人的脑力和体力的总和。劳动力成为商品，要具备两个基本条件：其一，劳动者在法律上是自由人，能够把自己的劳动力当作自己的商品来支配；其二，劳动者没有任何生产资料，没有生活资料来源，因而不得不依靠出卖劳动力为生。劳动力成为商品的两个条件是在封建社会后期发生的资本原始积累过程中逐渐形成的，劳动力成为商品标志着简单商品生产发展到资本主义商品生产的新阶段。", "o": "(1)<span class=\"rd\">劳动者在法律上是自由人</span>，能够把自己的劳动力当作自己的商品来支配\n(2)<span class=\"rd\">劳动者没有任何生产资料，没有生活资料来源</span>，不得不依靠出卖劳动力为生"}, {"id": "简33", "ch": "第四章 资本主义的本质及规律", "type": "简答", "page": "P211-212", "q": "不变资本与可变资本的划分及其意义", "qh": "不变资本和可变资本的划分及其意义<span class=\"pg\">P211-212</span>", "a": "根据资本在剩余价值生产中所起的不同作用，可以将资本划分为不变资本与可变资本。不变资本（c）是以生产资料形态存在的资本，在生产过程中只转移自己的价值量，不发生增殖；可变资本（v）是用来购买劳动力的那部分资本，其价值在生产过程中不是被转移到新产品中去，而是由工人的劳动再生产出来，是一个可变的量。划分的意义：把资本划分为不变资本和可变资本，进一步揭示了剩余价值的源泉——剩余价值既不是由全部资本创造的，也不是由不变资本创造的，而是由可变资本雇佣的劳动者创造的，雇佣劳动者的剩余劳动是剩余价值的唯一源泉；同时，为确定资本家对雇佣劳动者的剥削程度提供了科学依据（应拿剩余价值同可变资本相比，而不是同全部资本相比）。", "o": "(1)根据资本在剩余价值生产中所起的不同作用，资本分为\n①<span class=\"rd\">不变资本</span>：是以生产资料形态存在的资本\n②<span class=\"rd\">可变资本</span>：是用来购买劳动力的那部分资本\n(2)划分的意义：<span class=\"rd\">进一步揭示了剩余价值的源泉；雇佣劳动者的剩余劳动是剩余价值的唯一源泉；为确定资</span><span class=\"rd\">本家对雇佣劳动者的剥削程度提供了科学依据</span>"}, {"id": "简34", "ch": "第四章 资本主义的本质及规律", "type": "简答", "page": "P212-214", "q": "剩余价值生产的两种基本方法", "qh": "剩余价值生产的基本方法<span class=\"pg\">P212-214</span>", "a": "（1）绝对剩余价值生产：绝对剩余价值是指在必要劳动时间不变的条件下，由于延长工作日的长度或提高劳动强度而生产的剩余价值。在必要劳动时间既定的条件下，工作日越长，剩余劳动时间越长，资本家从工人身上榨取的剩余价值就越多，从而剩余价值率就越高；除了使用延长劳动时间的方法，资本家还使用提高工人劳动强度的方法，迫使工人更加紧张地劳动。（2）相对剩余价值生产：相对剩余价值是指在工作日长度不变的条件下，通过缩短必要劳动时间而相对延长剩余劳动时间所生产的剩余价值。缩短必要劳动时间是通过全社会劳动生产率的提高实现的，而全社会劳动生产率的提高是资本家追逐超额剩余价值的结果。", "o": "(1)<span class=\"rd\">绝对剩余价值生产</span>。绝对剩余价值指在必要劳动时间不变的条件下，由于<span class=\"rd\">延长工作日的长度或提高</span><span class=\"rd\">劳动强度</span>而生产的剩余价值。在必要劳动时间既定的条件下，工作日越长，剩余劳动时间越长，资本家从工人身上榨取的剩余价值就越多，从而剩余价值率就越高。为了让工人生产更多的剩余价值，资本家除了使用延长劳动时间的方法，还使用提高工人劳动强度的方法，迫使工人更加紧张地劳动，让他们在同样长的劳动时间内比以前耗费更多的脑力和体力\n(2)<span class=\"rd\">相对剩余价值生产</span>。相对剩余价值指在工作日长度不变的条件下，通过<span class=\"rd\">缩短必要劳动时间而相对延长剩</span><span class=\"rd\">余劳动时间</span>所生产的剩余价值。为了在工作日长度既定的条件下提高剥削程度，资本家在调整必要劳动时间与剩余劳动时间的比例上下功夫，通过缩短必要劳动时间、相对延长剩余劳动时间，增加剩余价值的生产。缩短必要劳动时间是通过<span class=\"rd\">全社会劳动生产率的提高</span>实现的"}, {"id": "简35", "ch": "第四章 资本主义的本质及规律", "type": "简答", "page": "P219-220", "q": "产业资本循环的三个阶段及其执行的职能", "qh": "产业资本的循环阶段及其执行的职能<span class=\"pg\">P219-220</span>", "a": "第一个阶段是购买阶段，即生产资料和劳动力的购买阶段，属于商品的流通过程，在这一阶段产业资本执行的是货币资本的职能；第二个阶段是生产阶段，即生产资料与劳动力按比例结合在一起从事资本主义生产的阶段，在这一阶段生产资料与劳动者相结合生产物质财富并使生产资本得以增殖，产业资本执行的是生产资本的职能；第三个阶段是售卖阶段，即商品资本向货币资本的转化阶段，在此阶段产业资本执行的是商品资本的职能，通过商品售卖不仅要实现商品的价值，还要实现剩余价值。产业资本的运动必须具备两个基本前提条件：产业资本的三种职能形式必须在空间上并存，在时间上继起。", "o": "(1)<span class=\"rd\">购买阶段</span>：即生产资料和劳动力的购买阶段；属于商品的流通过程；执行<span class=\"rd\">货币资本</span>职能\n(2)<span class=\"rd\">生产阶段</span>：即生产资料与劳动力按比例结合在一起从事资本主义生产的阶段；生产资料与劳动者相结合生产物质财富并使生产资本得以增殖；执行<span class=\"rd\">生产资本</span>职能\n(3)<span class=\"rd\">售卖阶段</span>：即商品资本向货币资本的转化阶段；执行<span class=\"rd\">商品资本</span>职能，通过商品售卖要实现商品的价值，还要实现剩余价值"}, {"id": "单119", "ch": "第五章 资本主义的发展及其趋势", "type": "单选", "page": "P241", "q": "资本主义发展的两个阶段", "qh": "资本主义的发展阶段：<span class=\"rd\">【自由竞争资本主义和垄断资本主义(19世纪末20世纪初形成)】</span><span class=\"pg\">P241</span>", "a": "资本主义的发展经历了两个阶段：自由竞争资本主义和垄断资本主义。19世纪70年代以前，资本主义处于自由竞争阶段；从19世纪70年代开始，自由竞争资本主义逐步向垄断资本主义发展；19世纪末20世纪初，垄断代替自由竞争并占据统治地位，垄断资本主义得以形成。这一时期，垄断资本主义主要以私人垄断资本为基础，所以又叫私人垄断资本主义；私人垄断资本主义是在生产集中和资本集中的基础上形成的。"}, {"id": "单120", "ch": "第五章 资本主义的发展及其趋势", "type": "单选", "page": "P241", "q": "垄断形成的规律", "qh": "<span class=\"rd\">【自由竞争引起生产集中和资本集中】</span>，生产集中和资本集中发展到一定阶段必然引起垄断，这是资本主义发展的客观规律<span class=\"pg\">P241</span>", "a": "自由竞争引起生产集中和资本集中，生产集中和资本集中发展到一定阶段必然引起垄断，这是资本主义发展的客观规律。生产集中是指生产资料、劳动力和商品的生产日益集中于少数大企业的过程；资本集中是指大资本吞并小资本，或由许多小资本合并而成大资本的过程。生产集中和资本集中是资本家追求剩余价值的结果。"}, {"id": "单121", "ch": "第五章 资本主义的发展及其趋势", "type": "单选", "page": "P242", "q": "垄断产生的原因", "qh": "垄断的产生原因：<span class=\"rd\">【①当生产集中发展到相当高的程度，极少数企业就会联合起来，操纵和控制本部</span><span class=\"rd\">门的生产和销售，实行垄断，以获得高额利润；②企业规模巨大，形成对竞争的限制，会产生垄断；③激烈的竞</span><span class=\"rd\">争给竞争各方带来的损失越来越严重，为了避免两败俱伤，企业之间会达成妥协，联合起来，实行垄断】</span><span class=\"pg\">P242</span>", "a": "垄断的产生有以下原因：第一，当生产集中发展到相当高的程度，极少数企业就会联合起来，操纵和控制本部门的生产和销售，实行垄断，以获得高额利润；第二，企业规模巨大，形成对竞争的限制，也会产生垄断；第三，激烈的竞争给竞争各方带来的损失越来越严重，为了避免两败俱伤，企业之间会达成妥协，联合起来，实行垄断。"}, {"id": "单122", "ch": "第五章 资本主义的发展及其趋势", "type": "单选", "page": "P243", "q": "垄断不能消除竞争的原因", "qh": "垄断并不能消除竞争(垄断阶级竞争依然存在)，这是因为：<span class=\"rd\">【①垄断没有消除产生竞争的经济条件。</span><span class=\"rd\">竞争是商品经济的一般规律；②垄断必须通过竞争来维持；③社会生产是复杂多样的，任何垄断组织都不</span><span class=\"rd\">可能把包罗万象的社会生产全部包下来。垄断组织内部、垄断组织之间、垄断组织同非垄断组织之间以及</span><span class=\"rd\">中小企业之间，都存在竞争】</span><span class=\"pg\">P243</span>", "a": "垄断是在自由竞争中形成的，是作为自由竞争的对立面产生的，但垄断并不能消除竞争，反而使竞争变得更加复杂和剧烈。这是因为：第一，垄断没有消除产生竞争的经济条件（竞争是商品经济的一般规律）；第二，垄断必须通过竞争来维持；第三，社会生产是复杂多样的，任何垄断组织都不可能把包罗万象的社会生产全部包下来。垄断组织内部、垄断组织之间、垄断组织同非垄断组织之间以及中小企业之间，都存在竞争。"}, {"id": "单123", "ch": "第五章 资本主义的发展及其趋势", "type": "单选", "page": "P244", "q": "金融资本与金融寡头", "qh": "<span class=\"rd\">【金融资本】</span>是由工业垄断资本和银行垄断资本融合而形成的垄断资本。<span class=\"rd\">【金融寡头】</span>指操纵国民经济命脉，并在实际上控制国家政权的少数垄断资本家或垄断资本家集团。金融寡头在经济领域中的统治主要是通过<span class=\"rd\">【参与制】</span>实现的，对国家机器(政治上)的控制主要是通过同政府的<span class=\"rd\">【个人联合】</span>来实现的<span class=\"pg\">P244</span>", "a": "金融资本是由工业垄断资本和银行垄断资本融合在一起而形成的一种垄断资本；通过金融联系、资本参与和人事参与，银行垄断资本和工业垄断资本密切地融合在一起，产生了金融资本。在金融资本形成的基础上，产生了金融寡头。金融寡头是指操纵国民经济命脉，并在实际上控制国家政权的少数垄断资本家或垄断资本家集团。金融寡头在经济领域中的统治主要是通过\"参与制\"（通过掌握一定数量的股票来层层控制企业的制度）实现的；对国家机器的控制，主要是通过同政府的\"个人联合\"来实现的。"}, {"id": "单124", "ch": "第五章 资本主义的发展及其趋势", "type": "单选", "page": "P245-248", "q": "垄断利润、垄断价格、国家垄断资本主义", "qh": "垄断资本的实质在于<span class=\"rd\">【获取垄断利润】</span>。垄断利润主要是通过垄断组织制定的<span class=\"rd\">【垄断价格】</span>来实现的。国家垄断资本主义是<span class=\"rd\">【国家政权和私人垄断资本融合在一起】</span>的垄断资本主义，其产生原因包括<span class=\"rd\">【社会生</span><span class=\"rd\">产力的发展，要求资本主义生产资料在更大范围内被支配；经济波动和经济危机的深化；缓和社会矛盾、</span><span class=\"rd\">协调利益关系的需求】</span><span class=\"pg\">P245-248</span>", "a": "垄断资本的实质在于获取垄断利润，垄断利润是垄断资本家凭借其在社会生产和流通中的垄断地位而获得的超过平均利润的高额利润；垄断利润主要是通过垄断组织制定的垄断价格来实现的（垄断价格包括垄断高价和垄断低价两种形式，垄断价格的产生没有否定价值规律，它是价值规律在垄断资本主义阶段作用的具体体现）。国家垄断资本主义是国家政权和私人垄断资本融合在一起的垄断资本主义，其产生原因：首先，社会生产力的发展，要求资本主义生产资料在更大范围内被支配；其次，经济波动和经济危机的深化；最后，缓和社会矛盾、协调利益关系的需求。"}, {"id": "单125", "ch": "第五章 资本主义的发展及其趋势", "type": "单选", "page": "P251", "q": "金融垄断资本发展的作用", "qh": "金融垄断资本发展的作用/影响：<span class=\"rd\">【(1)促进了资本主义经济的发展；(2)造成了经济过度虚拟化，导</span><span class=\"rd\">致金融危机频繁发生，不仅给资本主义经济带来灾难，也给全球经济带来灾难】</span><span class=\"pg\">P251</span>", "a": "金融垄断资本的发展，一方面促进了资本主义经济的发展，另一方面也造成了经济过度虚拟化，导致金融危机频繁发生，不仅给资本主义经济带来灾难，也给全球经济带来灾难。"}, {"id": "单126", "ch": "第五章 资本主义的发展及其趋势", "type": "单选", "page": "P251-252", "q": "垄断资本向世界范围扩展", "qh": "垄断资本向世界范围扩展<span class=\"pg\">P251-252</span>(1)是通过<span class=\"rd\">【跨国公司】</span>实现的(2)经济动因：<span class=\"rd\">【将国内过剩的资本输出，以便在国外谋求高额利润；将部分非要害的技术转移到国外，以</span><span class=\"rd\">取得在别国的垄断优势，攫取高额垄断利润；争夺商品销售市场；确保原材料和能源的可靠来源】</span>(3)基本形式有<span class=\"rd\">【借贷资本输出、生产资本输出、商品资本输出】</span>", "a": "垄断资本向世界范围扩展的主要经济动因是：首先，将国内过剩的资本输出，以便在国外谋求高额利润；其次，将部分非要害的技术转移到国外，以取得在别国的垄断优势，攫取高额垄断利润；再次，争夺商品销售市场；最后，确保原材料和能源的可靠来源。扩展的基本形式有三种：借贷资本输出、生产资本输出（在国外直接投资，独立创办企业，与国外资本合营，或收购国外已有的企业）、商品资本输出。垄断资本向世界范围的扩展是通过跨国公司这一国际垄断组织形式实现的。"}, {"id": "单127", "ch": "第五章 资本主义的发展及其趋势", "type": "单选", "page": "P253-254", "q": "国际垄断同盟与国际经济组织", "qh": "国际垄断同盟：早期主要是国际卡特尔，当代以<span class=\"rd\">【国家垄断资本主义的国际联盟】</span>为主。二战以来，从事国际经济协调、维护国际经济秩序的国际经济组织有<span class=\"rd\">【国际货币基金组织、世界银行、世界贸易组织】</span><span class=\"pg\">P253-254</span>", "a": "各资本主义国家的垄断组织通过订立协议建立起国际垄断资本的联盟，即国际垄断同盟，以便在世界范围内形成垄断，并在经济上瓜分世界。早期的国际垄断同盟主要是国际卡特尔；当代国际垄断同盟的形式以国家垄断资本主义的国际联盟为主。第二次世界大战以来，从事国际经济协调、维护国际经济秩序的国际经济组织主要有三个，即国际货币基金组织、世界银行和世界贸易组织。"}, {"id": "单128", "ch": "第五章 资本主义的发展及其趋势", "type": "单选", "page": "P254-255", "q": "垄断资本主义（帝国主义）的五个基本特征与实质", "qh": "列宁指出，资本主义发展到垄断资本主义，进而发展到帝国主义，便具有五个基本特征：<span class=\"rd\">【①垄断组织在</span><span class=\"rd\">经济生活中起决定作用；②在金融资本的基础上形成金融寡头的统治；③资本输出有了特别重要的意义；④</span><span class=\"rd\">瓜分世界的资本家国际垄断同盟已经形成；⑤最大资本主义大国已把世界上的领土瓜分完毕】</span>。这些特征集中体现了帝国主义的实质，即<span class=\"rd\">【垄断资本凭借垄断地位，获取高额垄断利润】</span><span class=\"pg\">P254-255</span>", "a": "列宁指出，资本主义发展到垄断资本主义，进而发展到帝国主义，便具有五个基本特征：（1）垄断组织在经济生活中起决定作用；（2）在金融资本的基础上形成金融寡头的统治；（3）资本输出有了特别重要的意义；（4）瓜分世界的资本家国际垄断同盟已经形成；（5）最大资本主义大国已把世界上的领土瓜分完毕。这些特征集中体现了帝国主义的实质，即垄断资本凭借垄断地位，获取高额垄断利润。"}, {"id": "单129", "ch": "第五章 资本主义的发展及其趋势", "type": "单选", "page": "P269-271", "q": "当代资本主义变化的新特征", "qh": "当代资本主义变化的新特征：<span class=\"rd\">【①科技创新加速资本主义生产方式变化。②国际金融垄断资本主义影响</span><span class=\"rd\">日益显现。③社会阶级层级结构呈现复杂性、多样化。④发达资本主义国家凭借经济、科技、文化传播等</span><span class=\"rd\">超级优势，在世界范围内推行霸权主义和强权政治】</span>。<span class=\"rd\">【国际金融资本的垄断】</span>成为当代资本主义最突出、最鲜明、最主要的特征<span class=\"pg\">P269-271</span>", "a": "第一，科技创新加速资本主义生产方式变化。第二，国际金融垄断资本主义影响日益显现——资本积累方式从一般产业资本积累向国际金融垄断资本积累转变，国际金融资本的垄断成为当代资本主义最突出、最鲜明、最主要的特征；国际金融垄断资本主义经济日益证券化、数字化、虚拟化，实体经济迅速衰退。第三，社会阶级层级结构呈现复杂性、多样化。第四，发达资本主义国家凭借经济、科技、文化传播等超级优势，在世界范围内推行霸权主义和强权政治。"}, {"id": "单130", "ch": "第五章 资本主义的发展及其趋势", "type": "单选", "page": "P272-274", "q": "世界大变局下资本主义的矛盾与冲突", "qh": "世界大变局下资本主义的矛盾与冲突：①<span class=\"rd\">【经济发展失调】</span>。虚拟经济与实体经济发展失衡；福利风险增加；债务负担沉重。②<span class=\"rd\">【政治体制失灵】</span>。西式选举往往难以选贤；政党利益可能凌驾于国家利益之上；“民主陷阱”会阻碍国家治理；传统精英政治走向衰落。③<span class=\"rd\">【社会融合机制失效】</span>。社会极端思潮抬头；社会流动性退化；社会矛盾激化<span class=\"pg\">P272-274</span>", "a": "第一，经济发展失调：一是虚拟经济与实体经济发展失衡，二是福利风险增加，三是债务负担沉重。第二，政治体制失灵：一是西式选举往往难以选贤，二是政党利益可能凌驾于国家利益之上，三是\"民主陷阱\"会阻碍国家治理，四是传统精英政治走向衰落。第三，社会融合机制失效：一是社会极端思潮抬头，二是社会流动性退化，三是社会矛盾激化。"}, {"id": "简36", "ch": "第五章 资本主义的发展及其趋势", "type": "简答", "page": "P236-238", "q": "资本主义意识形态的含义、本质、历史进步性与阶级局限性", "qh": "资本主义意识形态的含义、本质、历史进步性、阶级局限性<span class=\"pg\">P236-238</span>", "a": "资本主义意识形态是在资本主义国家中占统治地位、反映了作为统治阶级的资产阶级利益和要求的各种思想理论和观念的总和，其中一以贯之的核心思想，主要是私有制神圣不可侵犯观念和个人主义价值观。（本质）第一，资本主义意识形态是资本主义社会的观念上层建筑，是为资本主义的经济基础服务的，因而是为资本主义国家的政治上层建筑服务的；第二，资本主义意识形态是资产阶级的阶级意识的集中体现。（历史进步性）特别是在资本主义国家建立起来以前，那些文艺复兴时期和资产阶级革命时期的资产阶级思想理论和观念，在反对封建主义和宗教神学、推动资产阶级革命的发展以及促进资本主义国家建立的过程中曾起过积极的作用，因而其主要社会作用是推动历史前进的，是进步的；对于资本主义意识形态中的文明进步成分，我们应该加以研究、参考和借鉴。（阶级局限性）资本主义意识形态具有欺骗性和虚伪性，它\"用歪曲的形式把自己的特殊利益冒充为普遍的利益\"；作为资产阶级经济和政治的集中反映，是为巩固资产阶级的政治统治、维护资本主义的政治制度，为资产阶级的阶级剥削和阶级压迫服务的，因而具有极大的阶级的和历史的局限性，必须加以分析、批判和摒弃。", "o": "(1)是在资本主义国家中占统治地位、反映了作为统治阶级的资产阶级利益和要求的各种思想理论和观念的总和\n(2)本质：①是资本主义社会的观念上层建筑，<span class=\"rd\">是为资本主义的经济基础服务的，是为资本主义国家的政治</span><span class=\"rd\">上层建筑服务的</span>。②<span class=\"rd\">是资产阶级的阶级意识的集中体现</span>\n(3)历史进步性：资本主义在长期发展中<span class=\"rd\">创造出物质财富，也创造出精神成果</span>。这些精神成果有相当一部分是以意识形态的形式被保存下来。这些成果中包含着人类文明进步的成就。特别是在资本主义国家建立起来以前，文艺复兴时期和资产阶级革命时期的资产阶级思想理论和观念，<span class=\"rd\">在反对封建主义和宗教神学、推</span><span class=\"rd\">动资产阶级革命的发展以及促进资本主义国家建立的过程中曾起积极作用</span>，因而其<span class=\"rd\">主要社会作用是推动历</span><span class=\"rd\">史前进</span>的，是进步的。我们应该加以研究、参考和借鉴\n(4)阶级局限性：资本主义意识形态作为资产阶级经济和政治的集中反映，<span class=\"rd\">是为巩固资产阶级的政治统治、</span><span class=\"rd\">维护资本主义的政治制度，为资产阶级的阶级剥削和阶级压迫服务的</span>。我们必须加以分析、批判和摒弃"}, {"id": "简37", "ch": "第五章 资本主义的发展及其趋势", "type": "简答", "page": "P243-244", "q": "垄断条件下竞争的新特点", "qh": "同自由竞争相比垄断条件下竞争的新特点<span class=\"pg\">P243-244</span>", "a": "垄断条件下的竞争同自由竞争相比，具有一些新特点：在竞争目的上，自由竞争主要是为获得更多的利润或超额利润，不断扩大资本的积累，而垄断条件下的竞争则是为获取高额垄断利润，并不断巩固和扩大自己的垄断地位和统治权力；在竞争手段上，自由竞争主要运用经济手段，如通过改进技术、提高劳动生产率、降低产品成本等以战胜对手，而垄断条件下的竞争除了采取各种形式的经济手段外，还采取非经济的手段，使竞争变得更加复杂、激烈；在竞争范围上，自由竞争时期，竞争主要是在经济领域，而且主要是在国内市场上进行的，垄断时期，国际市场上的竞争越来越激烈，经济领域的竞争多种多样，还扩大到经济领域以外，规模大、时间长、手段残酷、程度激烈，具有更大的破坏性。", "o": "(1)<span class=\"rd\">竞争目的</span>：自由竞争是为获得更多的<span class=\"rd\">利润或超额利润</span>，不断扩大资本的积累。垄断条件下的竞争是为获取高额<span class=\"rd\">垄断利润</span>，并不断巩固和扩大自己的垄断地位和统治权力\n(2)<span class=\"rd\">竞争手段</span>：自由竞争运用<span class=\"rd\">经济手段</span>，如通过改进技术、提高劳动生产率、降低产品成本。垄断条件下的竞争除了采取各种形式的经济手段外，<span class=\"rd\">还采取非经济的手段</span>\n(3)<span class=\"rd\">竞争范围</span>：自由竞争时期，竞争<span class=\"rd\">主要</span>是<span class=\"rd\">在经济领域</span>，主要是在国内市场上进行的。垄断时期，国际市场上的竞争越来越激烈，经济领域的竞争多种多样，<span class=\"rd\">还扩大到经济领域以外</span>，规模大、时间长、手段残酷、程度激烈，具有更大的破坏性"}, {"id": "简38", "ch": "第五章 资本主义的发展及其趋势", "type": "简答", "page": "P245-246", "q": "垄断利润及其来源", "qh": "垄断利润及其来源<span class=\"pg\">P245-246</span>", "a": "垄断利润是垄断资本家凭借其在社会生产和流通中的垄断地位而获得的超过平均利润的高额利润。垄断利润的形成，关键在于垄断组织在经济生活中起了决定性作用，从而阻碍了资本在各部门之间的自由转移，限制了利润平均化的趋势。垄断利润归根到底来自无产阶级和其他劳动人民所创造的剩余价值，其来源大体有：第一，通过对本国无产阶级和其他劳动人民剥削的加强获得更多利润；第二，由于垄断资本可以通过垄断高价和垄断低价来控制市场，使得它能获得一些其他企业特别是非垄断企业的利润；第三，通过加强对其他国家劳动人民的剥削和掠夺从国外获取利润；第四，通过资本主义国家政权进行有利于垄断资本的再分配，从而将劳动人民创造的国民收入的一部分变成垄断资本的收入。", "o": "(1)垄断利润是垄断资本家凭借其在社会生产和流通中的垄断地位而获得的超过平均利润的高额利润\n(2)垄断利润归根到底来自无产阶级和其他劳动人民所创造的剩余价值。来源大体有\n①通过对本国无产阶级和其他劳动人民剥削的加强获得更多利润\n②由于垄断资本可以通过垄断高价和垄断低价来控制市场，使得它能获得一些其他企业特别是非垄断企业的利润\n③通过加强对其他国家劳动人民的剥削和掠夺从国外获取利润\n④通过资本主义国家政权进行有利于垄断资本的再分配，从而将劳动人民创造的国民收入的一部分变成垄断资本的收入"}, {"id": "简39", "ch": "第五章 资本主义的发展及其趋势", "type": "简答", "page": "P248-249", "q": "国家垄断资本主义的形式", "qh": "国家垄断资本主义的形式<span class=\"pg\">P248-249</span>", "a": "国家垄断资本主义的主要形式有五种：第一种是国家所有并直接经营企业，包括满足国家机构自身需要的国有企业，提供公共产品的国有企业，高科技、高风险的新兴工业部门中的国有企业和一般工业部门中的国有企业；第二种是国家与私人共有、合营企业；第三种是国家通过多种形式参与私人垄断资本的再生产过程，包括国家作为商品和劳务的采购者向私人垄断企业大量订货，国家通过各种形式的津贴和补助资助私人垄断企业，国家通过社会福利开支提高社会购买力、扩大消费需求；第四种是宏观调节，主要是国家运用财政政策、货币政策等经济手段，对社会总供给和总需求进行调节，以实现经济快速增长、充分就业、物价稳定和国际收支平衡的基本目标；第五种是微观规制，主要是国家运用法律手段规范市场秩序，限制垄断，保护竞争，维护社会公众的合法权益，主要有三种类型：反托拉斯法、公共事业规制、社会经济规制。", "o": "(1)国家所有并直接经营企业\n(2)国家与私人共有、合营企业\n(3)国家通过多种形式参与私人垄断资本的再生产过程\n(4)宏观调节，以实现经济快速增长、充分就业、物价稳定和国际收支平衡的基本目标\n(5)微观规制，主要有反托拉斯法、公共事业规制、社会经济规制"}, {"id": "简40", "ch": "第五章 资本主义的发展及其趋势", "type": "简答", "page": "P249-250", "q": "国家垄断资本主义对资本主义经济发展的作用", "qh": "国家垄断资本主义对资本主义经济发展的作用<span class=\"pg\">P249-250</span>", "a": "（积极作用）首先，国家垄断资本主义的出现在一定程度上有利于社会生产力的发展；其次，资本主义国家凌驾于私人垄断资本之上，代表整个垄断资产阶级的利益，调节经济过程和经济活动，这在一定范围内突破了私人垄断资本的狭隘界限；再次，通过国家的收入再分配手段，劳动人民生活水平有所改善和提高；最后，在国家垄断资本主义的参与和干预下，各主要资本主义国家现代化水平迅速提高，社会生产和社会生活的面貌改观，加快了这些国家国民经济的现代化进程。（消极方面）但是，国家垄断资本主义的出现并没有根本改变垄断资本主义的性质，它在本质上是资产阶级国家力量同垄断组织力量结合在一起的垄断资本主义，它在促进生产力发展的同时，却加大对劳动人民的剥削和掠夺，更好地保证垄断资产阶级获得高额垄断利润，更有利于维护资本主义制度；国家垄断资本主义的出现是资本主义经济制度内的经济关系调整，并没有从根本上消除资本主义的基本矛盾。", "o": "(1)积极：①<span class=\"rd\">有利于社会生产力的发展</span>。②资本主义国家凌驾于私人垄断资本之上，代表整个垄断资产阶级的利益，调节经济过程和经济活动，<span class=\"rd\">突破私人垄断资本的狭隘界限</span>。③通过国家的收入再分配手段，<span class=\"rd\">劳动人民生活水平有所改善和提高</span>。④在国家垄断资本主义的参与和干预下，<span class=\"rd\">各主要资本主义国家现代化</span><span class=\"rd\">水平迅速提高，社会生产和社会生活的面貌改观</span>，加快这些国家国民经济的现代化进程\n(2)消极：①国家垄断资本主义的出现<span class=\"rd\">并没有根本改变垄断资本主义的性质</span>。国家垄断资本主义在本质上是资产阶级国家力量同垄断组织力量结合在一起的垄断资本主义。它<span class=\"rd\">在促进生产力发展的同时，却加大对劳</span><span class=\"rd\">动人民的剥削和掠夺</span>，更好保证垄断资产阶级获得高额垄断利润，更有利于维护资本主义制度。②国家垄断资本主义的出现是资本主义经济制度内的经济关系调整，<span class=\"rd\">并没有从根本上消除资本主义的基本矛盾</span>。国家垄断资本主义有各种不同的具体形式，其<span class=\"rd\">实质都是私人垄断资本利用国家机器来为其发展服务的手段，是</span><span class=\"rd\">私人垄断资本为了维护垄断统治和获取高额垄断利润</span>，而与国家政权相结合的垄断资本主义形式，是资产阶级国家在直接参与社会资本的再生产过程中，代表资产阶级总利益并凌驾于个别垄断资本之上，对社会经济进行调节的形式"}, {"id": "简41", "ch": "第五章 资本主义的发展及其趋势", "type": "简答", "page": "P252-253", "q": "垄断资本向世界范围扩展的社会经济后果", "qh": "垄断资本向世界范围扩展(资本输出)对输出国及输入国产生的社会经济后果<span class=\"pg\">P252-253</span>", "a": "对于资本输出国来讲，资本输出为其带来了巨额利润，加速了资本积累，增强了垄断资本的实力；带动和扩大了商品输出，巩固和扩大了垄断资本的销售市场和投资场所；对发展中国家的经济命脉形成控制，进一步巩固和扩大了垄断优势地位。在资本输出过程中，资本输出国可能出现产业空心化，资本输出国与发展中国家和其他发达国家之间的矛盾会加深，但是这些都不能改变垄断资本通过资本输出攫取巨大利益和扩大垄断实力的实质。对于资本输入国（主要是发展中国家）而言，积极作用主要是：吸收经济发展所需要的资金，为经济发展提供条件；引进比较先进的机器设备和工艺技术，培训一批适应现代化生产需要的技术人员、熟练工人和经营管理人员；利用外资和技术，建立一批现代工业，改造老企业和旧设备，优化产业结构；利用外资扩大生产，增加产品产量，提高产品质量，扩大出口。不利影响主要是：付出了较大的经济代价以及环境污染、能源资源消耗的代价；产业调整和布局有可能受制于外资的投资战略；外来资本和跨国公司投资增加，冲击本国的民族工业，并影响到国民经济的控制权；债务负担加重，影响经济的持续稳定发展；对国际资本的依赖性增强，容易受到国际经济波动的影响。", "o": "(1)对于资本输出国：资本输出为其<span class=\"rd\">带来巨额利润</span>，加速资本积累，增强垄断资本的实力；<span class=\"rd\">带动和扩大</span><span class=\"rd\">商品输出</span>，巩固和扩大垄断资本的销售市场和投资场所；<span class=\"rd\">对发展中国家的经济命脉形成控制</span>，进一步巩固和扩大垄断优势地位。在资本输出中，<span class=\"rd\">资本输出国可能出现产业空心化，资本输出国与发展中国家和其他</span><span class=\"rd\">发达国家之间的矛盾会加深</span>，但是这些都不能改变垄断资本通过资本输出攫取巨大利益和扩大垄断实力的实质\n(2)对于资本输入国(主要是发展中国家)：①积极作用：主要是<span class=\"rd\">吸收</span>经济发展所需要的<span class=\"rd\">资金</span>，<span class=\"rd\">为经济发展提</span><span class=\"rd\">供条件</span>；<span class=\"rd\">引进</span>比较先进的机器<span class=\"rd\">设备和</span>工艺<span class=\"rd\">技术</span>，培训一批适应现代化生产需要的技术人员、熟练工人和经营管理人员；<span class=\"rd\">利用外资和技术</span>，建立一批现代工业，改造老企业和旧设备，<span class=\"rd\">优化产业结构</span>；<span class=\"rd\">利用外资扩大</span><span class=\"rd\">生产</span>，增加产品产量，提高产品质量，扩大出口，<span class=\"rd\">促进对外贸易的发展</span>；<span class=\"rd\">推动经济的发展</span>，增加就业机会，<span class=\"rd\">提高收入水平</span>。②不利影响：主要是<span class=\"rd\">付出较大的经济代价以及环境污染、能源资源消耗的代价</span>；<span class=\"rd\">产业调整</span><span class=\"rd\">和布局</span>有可能<span class=\"rd\">受制于外资的投资战略</span>；外来资本和跨国公司投资增加，<span class=\"rd\">冲击本国的民族工业</span>，并<span class=\"rd\">影响到国</span><span class=\"rd\">民经济的控制权</span>；<span class=\"rd\">债务负担加重</span>，影响经济的持续稳定发展；<span class=\"rd\">对国际资本的依赖性增强</span>，容易受到国际经济波动的影响"}, {"id": "简42", "ch": "第五章 资本主义的发展及其趋势", "type": "简答", "page": "P256-260", "q": "经济全球化的含义、表现、动因、影响", "qh": "经济全球化的含义、表现、动因、影响<span class=\"pg\">P256-260</span>", "a": "（含义）经济全球化是指在生产不断发展、科技加速进步、社会分工和国际分工不断深化、生产的社会化和国际化程度不断提高的情况下，世界各国、各地区的经济活动越来越超出某一国家和地区的范围而相互联系、相互依存的过程。（表现）第一，生产全球化；第二，贸易全球化；第三，金融全球化。（动因）从本质上讲，经济全球化是生产力发展和社会化大生产的必然要求；导致经济全球化迅猛发展的因素主要有三点：一是科学技术的进步和生产力的发展为经济全球化提供了坚实的物质基础和根本的推动力；二是跨国公司的发展为经济全球化提供了适宜的企业组织形式；三是各国经济体制的变革和国际经济组织的发展是经济全球化的体制与组织保障。（影响）经济全球化是一把\"双刃剑\"：一方面，社会分工得以在更大的范围内进行，资金、技术等生产要素可以在国际社会流动和优化配置，由此带来巨大的分工利益，推动世界生产力的发展，不仅发达国家从中受益，一些发展中国家在参与经济全球化进程中也得到了快速发展（为发展中国家提供先进技术和管理经验、更多的就业机会，推动发展中国家国际贸易和跨国公司的发展）；另一方面，发达国家与发展中国家在经济全球化进程中的地位和收益不平等、不平衡，加剧了发展中国家的资源短缺和环境污染，并增加全球经济发展的不稳定性和经济风险。", "o": "(1)含义：指在生产不断发展、科技加速进步、社会分工和国际分工不断深化、生产的社会化和国际化程度不断提高的情况下，<span class=\"rd\">世界各国、各地区的经济活动越来越超出某一国家和地区的范围而相互联系、相</span><span class=\"rd\">互依存的过程</span>\n(2)表现(内容)：<span class=\"rd\">生产全球化、贸易全球化、金融全球化</span>\n(3)动因：①从本质上讲，经济全球化是<span class=\"rd\">生产力发展和社会化大生产</span>的必然要求。②导致经济全球化迅猛发展的因素：<span class=\"rd\">科学技术的进步和生产力的发展</span>为经济全球化提供坚实的物质基础和根本的推动力；<span class=\"rd\">跨国公司的</span><span class=\"rd\">发展</span>为经济全球化提供适宜的企业组织形式；<span class=\"rd\">各国经济体制的变革和国际经济组织的发展</span>是经济全球化的体制与组织保障\n(4)经济全球化是一把双刃剑：①积极作用：资金、技术等生产要素可以在国际社会流动和优化配置，由此<span class=\"rd\">带来巨大的分工利益</span>，<span class=\"rd\">推动世界生产力的发展</span>。不仅发达国家从中受益，一些发展中国家在参与经济全球化进程中也得到了快速发展。对发展中国家的积极作用主要表现在：<span class=\"rd\">为发展中国家提供先进技术和管理经</span><span class=\"rd\">验</span>；为发展中国家<span class=\"rd\">提供更多的就业机会</span>；<span class=\"rd\">推动</span>发展中国家<span class=\"rd\">国际贸易的发展</span>；<span class=\"rd\">促进</span>发展中国家<span class=\"rd\">跨国公司的发</span><span class=\"rd\">展</span>。②负面影响：<span class=\"rd\">发达国家与发展中国家</span>在经济全球化进程中的<span class=\"rd\">地位和收益不平等、不平衡</span>；<span class=\"rd\">加剧了发展</span><span class=\"rd\">中国家资源短缺和环境污染</span>；一定程度上<span class=\"rd\">增加了经济风险</span>"}, {"id": "简43", "ch": "第五章 资本主义的发展及其趋势", "type": "简答", "page": "P266-268", "q": "二战后资本主义发生变化的原因和实质", "qh": "二战后(当代)资本主义发生变化的原因和实质<span class=\"pg\">P266-268</span>", "a": "（原因）首先，科学技术革命和生产力的发展，是资本主义发生变化的根本推动力量；其次，工人阶级争取自身权利和利益的斗争，是推动资本主义发生变化的重要力量；再次，社会主义制度初步显示的优越性对资本主义产生了重要影响；最后，主张改良主义的政党对资本主义制度的改革，也对资本主义发生变化起到了重要作用。（实质）第一，第二次世界大战后资本主义发生的变化从根本上说是人类社会发展一般规律和资本主义经济规律作用的结果，是资本主义生产方式为适应生产力发展要求而作出自我调节的结果；第二，这些变化是在资本主义制度基本框架内的变化，并不意味着资本主义生产关系的根本性质发生了变化（只要生产资料私有制和雇佣劳动还存在，只要生产剩余价值的规律还发生作用，资本主义生产关系的根本性质就不会发生变化）；第三，这些变化并没有改变资本主义制度的本质，并没有克服资本主义的基本矛盾，也没有改变马克思主义关于资本主义的基本论断的科学性，根源于资本主义基本矛盾的经济危机依然是资本主义不可克服的痼疾。", "o": "(1)原因：①<span class=\"rd\">科学技术革命和生产力的发展</span>，是资本主义发生变化的根本推动力量。②<span class=\"rd\">工人阶级争取自</span><span class=\"rd\">身权利和利益的斗争</span>，是推动资本主义发生变化的重要力量。③<span class=\"rd\">社会主义制度初步显示的优越性</span>对资本主义产生重要影响。④<span class=\"rd\">主张改良主义的政党对资本主义制度的改革</span>，也对资本主义发生变化起到了重要作用\n(2)实质：①二战后资本主义发生的变化从根本上说<span class=\"rd\">是人类社会发展一般规律和资本主义经济规律作用的结</span><span class=\"rd\">果</span>。②二战后资本主义发生的变化<span class=\"rd\">是在资本主义制度基本框架内的变化</span>，并不意味着资本主义生产关系的根本性质发生变化。③二战后资本主义发生的变化<span class=\"rd\">并没有改变资本主义制度的本质</span>，并没有克服资本主义的基本矛盾，也没有改变马克思主义关于资本主义的基本论断的科学性"}, {"id": "简44", "ch": "第五章 资本主义的发展及其趋势", "type": "简答", "page": "P276-277", "q": "资本主义历史进步性无法掩盖自身局限性的表现", "qh": "资本主义历史进步性无法掩盖自身局限性的表现(资本主义的局限性)<span class=\"pg\">P276-277</span>", "a": "第一，资本主义的基本矛盾阻碍社会生产力的发展；第二，资本主义制度下财富占有两极分化，引发经济危机（一极是资本家阶级占有巨额财富，另一极是广大的工人阶级只占有少部分财富，由此引发广大劳动者有支付能力的需求远远赶不上资本主义生产无限扩张趋势的矛盾）；第三，资产阶级支配和控制资本主义经济和政治的发展和运行，不断激化社会矛盾和冲突。", "o": "(1)资本主义的基本矛盾阻碍社会生产力的发展\n(2)资本主义制度下财富占有两极分化，引发经济危机\n(3)资产阶级支配和控制资本主义经济和政治的发展和运行，不断激化社会矛盾和冲突"}, {"id": "单131", "ch": "第六章 社会主义的发展及其规律", "type": "单选", "page": "P280", "q": "国家垄断资本主义是社会主义的前阶", "qh": "<span class=\"rd\">【国家垄断资本主义】</span>是社会主义的最充分的物质准备，是社会主义的前阶<span class=\"pg\">P280</span>", "a": "在马克思、恩格斯看来，资本国有化将为社会主义革命提供直接的物质前提，是无产阶级社会主义革命的入口处。到了国家垄断资本主义阶段，生产社会化、资本社会化和管理社会化都达到了资本主义生产方式的更高程度，从而为全社会共同占有生产资料和共同组织社会化生产准备了充分的物质条件和社会条件。\"国家垄断资本主义是社会主义的最充分的物质准备，是社会主义的前阶，是历史阶梯上的一级，在这一级和叫做社会主义的那一级之间，没有任何中间级。\"（列宁）"}, {"id": "单132", "ch": "第六章 社会主义的发展及其规律", "type": "单选", "page": "P283-284", "q": "空想社会主义", "qh": "空想社会主义：<span class=\"pg\">P283-284</span>(1)产生于16世纪初期，开山之作是<span class=\"rd\">【1516年莫尔的《乌托邦》】</span>(2)到19世纪上半叶达到顶峰，代表人物有<span class=\"rd\">【圣西门、傅立叶、欧文】</span>", "a": "空想社会主义产生于16世纪初期，到19世纪上半叶达到顶峰（发展到最高阶段），代表人物有法国的圣西门、傅立叶和英国的欧文。空想社会主义的开山之作是1516年英国人托马斯·莫尔所著《乌托邦》一书；受其影响，意大利的康帕内拉于1602年写出《太阳城》。19世纪初期以圣西门、傅立叶、欧文为代表的空想社会主义是科学社会主义的直接思想来源，但空想社会主义\"没有能够指出真正的出路\"，并不是科学的思想体系。"}, {"id": "单133", "ch": "第六章 社会主义的发展及其规律", "type": "单选", "page": "P289", "q": "十月革命与第一个社会主义国家", "qh": "1917年列宁领导的俄国十月革命胜利，建立起世界上第一个人民当家作主的社会主义国家--<span class=\"rd\">【苏维</span><span class=\"rd\">埃俄国】</span><span class=\"pg\">P289</span>", "a": "列宁根据对俄国国内革命形势和国际状况的科学分析，得出了社会主义可能在经济文化相对落后的俄国首先取得胜利的结论，并领导了俄国十月革命。十月革命实现了社会主义从理想到现实的伟大飞跃，开辟了人类历史的新纪元。十月革命胜利后，年轻的苏维埃政权不仅面临着巩固政权的任务，而且面临着在经济文化相对落后的条件下建设社会主义的任务。列宁领导的苏维埃俄国对社会主义道路的探索，大体上经历了三个时期：进一步巩固苏维埃政权时期、战时共产主义时期、由战时共产主义转变为新经济政策时期。"}, {"id": "单134", "ch": "第六章 社会主义的发展及其规律", "type": "单选", "page": "P292-293", "q": "二战后社会主义发展到多个国家", "qh": "<span class=\"rd\">【二战后】</span>社会主义发展到多个国家(实现从一国到多国的发展)<span class=\"pg\">P292-293</span>", "a": "（四）社会主义发展到多个国家——俄国十月革命的胜利，苏联社会主义建设的成就，殖民地半殖民地国家民族民主革命的蓬勃发展，帝国主义力量的削弱，极大地鼓舞了世界各国人民，促进了世界社会主义运动的发展。二战后，社会主义在世界范围内获得大发展，实现了从一国到多国的发展；中国革命的胜利，是继十月革命之后20世纪最重大的事件。"}, {"id": "单135", "ch": "第六章 社会主义的发展及其规律", "type": "单选", "page": "P298-306", "q": "科学社会主义基本原则的主要内容", "qh": "科学社会主义基本原则的主要内容<span class=\"pg\">P298-306</span>(1)核心命题：<span class=\"rd\">【资本主义必然灭亡，社会主义必然胜利】</span>。“两个必然”的根本依据是人类社会发展规律(2)无产阶级是最先进最革命的阶级，肩负着推翻资本主义旧世界、建立社会主义和共产主义新世界的历史使命(3)无产阶级革命是无产阶级进行斗争的最高形式，以建立无产阶级专政的国家政权为目的(4)要在生产资料公有制基础上组织生产，以<span class=\"rd\">【满足全体社会成员的需要】</span>为生产的根本目的(5)要对社会生产进行有计划的指导和调节，实行<span class=\"rd\">【按劳分配原则】</span>(6)要合乎自然规律地改造和利用自然，努力实现人与自然的和谐共生(7)必须坚持科学的理论指导，大力发展社会主义先进文化(8)无产阶级政党是无产阶级的先锋队，社会主义事业必须始终坚持无产阶级政党的领导即共产党的领导。无产阶级政党实行民主集中制的组织原则(9)社会主义社会要大力解放和发展生产力，逐步消灭剥削和消除两极分化，实现共同富裕和社会全面进步，最终向<span class=\"rd\">【共产主义社会】</span>过渡(10)共产主义是人类最美好的社会制度，<span class=\"rd\">【实现共产主义】</span>是共产党人的最高理想", "a": "第一，资本主义必然灭亡，社会主义必然胜利——\"两个必然\"是科学社会主义的核心命题，其根本依据是人类社会发展规律。第二，无产阶级是最先进最革命的阶级，肩负着推翻资本主义旧世界、建立社会主义和共产主义新世界的历史使命。第三，无产阶级革命是无产阶级进行斗争的最高形式，以建立无产阶级专政的国家政权为目的。第四，要在生产资料公有制基础上组织生产，以满足全体社会成员的需要为生产的根本目的。第五，要对社会生产进行有计划的指导和调节，实行按劳分配原则。第六，要合乎自然规律地改造和利用自然，努力实现人与自然的和谐共生（牢固树立绿水青山就是金山银山的理念）。第七，必须坚持科学的理论指导，大力发展社会主义先进文化。第八，无产阶级政党是无产阶级的先锋队，社会主义事业必须始终坚持无产阶级政党的领导。第九，社会主义社会要大力解放和发展生产力，逐步消灭剥削和消除两极分化，实现共同富裕和社会全面进步，并最终向共产主义社会过渡。"}, {"id": "单136", "ch": "第六章 社会主义的发展及其规律", "type": "单选", "page": "P300-302", "q": "无产阶级革命的根本问题、公有制的地位、按劳分配的原因", "qh": "无产阶级革命是以政治革命为核心的社会革命，其根本问题是<span class=\"rd\">【国家政权问题】</span>。<span class=\"rd\">【生产资料公有制】</span>是社会主义经济制度的根基。社会主义社会实行按劳分配制度的原因：<span class=\"rd\">【社会主义社会生产力的发展还不</span><span class=\"rd\">够充分，还存在旧的社会分工，存在脑力劳动和体力劳动的差别，劳动还是谋生的手段】</span><span class=\"pg\">P300-302</span>", "a": "无产阶级革命是以政治革命为核心的社会革命，其根本问题是国家政权问题。社会主义社会必须坚持生产资料公有制，生产资料公有制是社会主义经济制度的根基，社会主义国家任何时候都不能放弃。社会主义社会要实行按劳分配的制度，但由于社会主义社会生产力的发展还不够充分，还存在旧的社会分工，存在脑力劳动和体力劳动的差别，劳动还是谋生的手段，因而个人消费品的分配还不能实行按需分配，而只能实行按劳分配，即等量劳动领取等量产品。"}, {"id": "简45", "ch": "第六章 社会主义的发展及其规律", "type": "简答", "page": "P306-308", "q": "如何正确把握科学社会主义的基本原则", "qh": "如何正确把握科学社会主义的基本原则<span class=\"pg\">P306-308</span>", "a": "第一，必须始终坚持科学社会主义基本原则，反对任何背离科学社会主义基本原则的错误倾向（科学社会主义基本原则揭示了资本主义生产方式的基本矛盾，阐明了社会主义代替资本主义的历史必然性；19世纪末20世纪初伯恩施坦否定基本原则，走上修正主义道路）。第二，要善于把科学社会主义基本原则与本国实际和时代特征相结合，创造性地回答和解决社会主义革命、建设、改革中的重大问题（共产党人必须将基本原则运用于实践，发挥这些原则指导实践的巨大威力）。第三，紧跟时代和实践的发展，在不断总结新鲜经验中进一步丰富和发展科学社会主义基本原则（科学社会主义基本原则不是一成不变的教条，而是随着社会主义实践而不断丰富和发展的学说）。", "o": "(1)必须始终坚持科学社会主义基本原则，反对任何背离科学社会主义基本原则的错误倾向\n(2)要善于把科学社会主义基本原则与本国实际和时代特征相结合，创造性地回答和解决社会主义革命、建设、改革中的重大问题\n(3)紧跟时代和实践的发展，在不断总结新鲜经验中进一步丰富和发展科学社会主义基本原则"}, {"id": "简46", "ch": "第六章 社会主义的发展及其规律", "type": "简答", "page": "P312-314", "q": "经济文化相对落后国家社会主义建设的艰巨性和长期性", "qh": "经济文化相对落后的国家社会主义建设的艰巨性和长期性<span class=\"pg\">P312-314</span>", "a": "社会主义是一项崭新的事业，其建设必然是一个不断探索的长期过程。在经济文化相对落后的国家建设社会主义，更具有历史长期性。第一，生产力发展状况的制约：在一个相当长的历史时期内，社会主义国家在经济上落后于发达资本主义国家，这就决定了必须把大力发展生产力作为根本任务，努力完成工业化和生产社会化、商品化、现代化的艰巨任务，需要很长时间的努力。第二，经济基础和上层建筑发展状况的制约：发展公有制经济、改造小农经济、建立巩固和完善社会主义经济基础是十分艰巨的任务；社会主义民主政治建设受到经济、政治、文化条件的严重制约，将是一个长期的过程。第三，国际环境的严峻挑战：社会主义国家尚处于强大的资本主义世界的包围之中，受到资本主义列强的遏制和扼杀，攻击方式由武力为主转变为以\"和平演变\"为主。第四，马克思主义执政党对社会主义发展道路的探索和对社会主义建设规律的认识，需要一个长期的过程。", "o": "社会主义建设必然是不断探索的长期过程。在经济文化相对落后的国家建设社会主义，更具有历史长期性。\n(1)<span class=\"rd\">生产力发展状况的制约</span>。在相当长的历史时期内，社会主义国家在经济上落后于发达资本主义国家，这就决定了在社会主义制度下必须把大力发展生产力作为根本任务，努力完成发达资本主义国家在资本主义条件下已经实现的工业化和生产社会化、商品化、现代化的艰巨任务，需要很长时间的努力\n(2)<span class=\"rd\">经济基础和上层建筑发展状况的制约</span>。社会主义民主政治建设受到国家的经济、政治、文化条件的严重制约，面临许多现实问题和困难，将是一个长期的过程\n(3)<span class=\"rd\">国际环境的严峻挑战</span>。社会主义国家尚处于强大的资本主义世界的包围之中，受到资本主义列强的遏制和扼杀，面临异常严峻的国际环境\n(4)<span class=\"rd\">马克思主义执政党对社会主义发展道路的探索和对社会主义建设规律的认识，需要长期的过程</span>"}, {"id": "简47", "ch": "第六章 社会主义的发展及其规律", "type": "简答", "page": "P316-317", "q": "如何探索适合本国国情的社会主义发展道路", "qh": "如何探索适合本国国情的社会主义发展道路<span class=\"pg\">P316-317</span>", "a": "既然社会主义发展道路具有多样性，那么努力探索适合本国国情的社会主义发展道路，就是无产阶级执政党必须领导全国人民为之奋斗的神圣使命和光荣任务。第一，探索社会主义发展道路，必须坚持对待马克思主义的科学态度（马克思主义经典作家并没有提供各国社会主义发展道路的现成方案）。第二，必须从当时当地的历史条件出发，坚持\"走自己的路\"（立足本国国情，走自己的路，是社会主义建设历史经验的总结）。第三，必须充分吸收人类一切优秀文明成果（社会主义要赢得与资本主义相比较的优势，就必须大胆吸收和借鉴人类社会创造的一切优秀文明成果，包括发达资本主义国家一切反映现代化生产规律的先进经营方式和管理方法）。", "o": "(1)必须坚持对待马克思主义的科学态度\n(2)必须从当时当地的历史条件出发，坚持走自己的路\n(3)必须充分吸收人类一切优秀文明成果"}, {"id": "简48", "ch": "第六章 社会主义的发展及其规律", "type": "简答", "page": "P318-325", "q": "试述社会主义在实践探索中开拓前进", "qh": "试述社会主义在实践探索中开拓前进<span class=\"pg\">P318-325</span>", "a": "（一）在实践中开拓前进是社会主义事业发展的必然要求。首先，社会主义是亿万人民群众的伟大实践；其次，社会主义实践是一个不断探索的过程；再次，实践探索中出现某种曲折并不改变社会主义的前进趋势；最后，推进社会主义实践发展必须有开拓奋进的精神状态。（二）社会主义在实践中开拓前进必须遵循客观规律：必须遵循人类社会发展规律，必须遵循社会主义建设规律，必须遵循共产党执政规律。（三）以自信担当、开拓奋进的姿态走向社会主义光明未来：首先，正确看待21世纪世界社会主义的形势（东欧剧变、苏联解体使世界社会主义进入低潮，但这并不意味着社会主义的失败；社会主义具有强大生命力，这种生命力归根结底是真理的力量，也是道义的力量）；其次，充分认识中国特色社会主义的成功实践对世界社会主义发展的意义；最后，坚定信心、振奋精神，以开拓奋进的姿态走向社会主义光明未来。", "o": "(1)<span class=\"rd\">在实践中开拓前进是社会主义事业发展的必然要求</span>。①社会主义是亿万人民群众的伟大实践。②社会主义实践是一个不断探索的过程。③实践探索中出现某种曲折并不改变社会主义的前进趋势。④推进社会主义实践发展必须有开拓奋进的精神状态\n(2)<span class=\"rd\">社会主义在实践中开拓前进必须遵循客观规律</span>。①必须遵循人类社会发展规律。②必须遵循社会主义建设规律。③必须遵循共产党执政规律\n(3)<span class=\"rd\">以自信担当、开拓奋进的姿态走向社会主义光明未来</span>。①正确看待21世纪世界社会主义的形势。②充分认识中国特色社会主义的成功实践对世界社会主义发展的意义。③坚定信心、振奋精神，以开拓奋进的姿态走向社会主义光明未来"}, {"id": "单137", "ch": "第七章 共产主义崇高理想及其最终实现", "type": "单选", "page": "P344-345", "q": "实现共产主义是人类最伟大的事业", "qh": "实现共产主义是人类最伟大的事业<span class=\"pg\">P344-345</span>(1)<span class=\"rd\">【实现共产主义理想】</span>是广大人民群众的共同愿望(2)实现共产主义，必须找到现实的阶级力量，这就是现代工人阶级或无产阶级(3)<span class=\"rd\">【无产阶级的解放与全人类的解放是完全一致的】</span>", "a": "（二）实现共产主义是人类最伟大的事业。实现共产主义理想是广大人民群众的共同愿望；实现共产主义，必须找到现实的阶级力量，这就是现代工人阶级或无产阶级；无产阶级的解放与全人类的解放是完全一致的。"}, {"id": "单138", "ch": "第七章 共产主义崇高理想及其最终实现", "type": "单选", "page": "P345-348", "q": "实现共产主义是长期的历史过程", "qh": "实现共产主义是长期的历史过程：<span class=\"rd\">【①资本主义的灭亡和向社会主义的转变是一个长期的历史过程。②</span><span class=\"rd\">社会主义社会的充分发展和最终向共产主义过渡需要很长的历史时期】</span>。<span class=\"rd\">【社会主义】</span>是共产主义的初级阶段，也是实现共产主义的必由之路。<span class=\"pg\">P345-348</span>", "a": "共产主义一定要实现，共产主义一定能够实现，但共产主义的实现是一个十分漫长而且充满艰难曲折的历史过程。资本主义从兴盛走向衰落和灭亡需要相当长的历史时期；从资本主义到社会主义有一个过渡时期，这是一个充满矛盾和斗争的复杂历史过程；共产主义社会的初级阶段即社会主义社会是一个长期的历史过程，特别是从不发达的社会主义到发达的社会主义，更有一个长期发展的过程；最后，从发达的社会主义向共产主义的转变和过渡，也需要一定的历史时期。社会主义是共产主义的初级阶段，也是实现共产主义的必由之路。"}, {"id": "单139", "ch": "第七章 共产主义崇高理想及其最终实现", "type": "单选", "page": "P350", "q": "中国特色社会主义是中华民族通向共产主义的必由之路", "qh": "坚持和发展<span class=\"rd\">【中国特色社会主义】</span>是中华民族通向共产主义的必由之路<span class=\"pg\">P350</span>", "a": "坚持和发展中国特色社会主义是中华民族通向共产主义的必由之路。马克思主义奠定了共产党人坚定理想信念的理论基础；中国特色社会主义道路是中华民族最终走向共产主义的必由之路。"}, {"id": "单140", "ch": "第七章 共产主义崇高理想及其最终实现", "type": "单选", "page": "P351-352", "q": "共产主义远大理想与中国特色社会主义共同理想的关系", "qh": "共产主义远大理想和中国特色社会主义共同理想的关系<span class=\"pg\">P351-352</span>(1)从时间上看，远大理想与共同理想的关系是<span class=\"rd\">【最终理想与阶段性理想】</span>的关系(2)从层次上看，远大理想与共同理想的关系是<span class=\"rd\">【最高纲领与最低纲领】</span>的关系(3)从范围上看，远大理想与共同理想的关系也是<span class=\"rd\">【全人类理想与全体中国人民理想】</span>的关系", "a": "首先，从时间上看，远大理想与共同理想的关系是最终理想与阶段性理想的关系（共产主义远大理想也就是我们的最终理想，它的实现需要许多代人的接续奋斗）。其次，从层次上看，远大理想与共同理想的关系是最高纲领与最低纲领的关系（坚定中国特色社会主义共同理想，进一步推进中国特色社会主义事业，就是我们党的最低纲领在当前的要求）。再次，从范围上看，远大理想与共同理想的关系也是全人类理想与全体中国人民理想的关系。习近平明确指出：\"中国特色社会主义是党的最高纲领和基本纲领的统一。\""}, {"id": "简49", "ch": "第七章 共产主义崇高理想及其最终实现", "type": "简答", "page": "P333-340", "q": "共产主义社会的基本特征", "qh": "共产主义社会的基本特征(马克思主义经典作家对共产主义社会的展望)<span class=\"pg\">P333-340</span>", "a": "（一）物质财富极大丰富，消费资料按需分配。社会生产力高度发展，产品极大丰富，是实现共产主义的必要条件；只有在生产力增长起来，在集体财富的一切源泉都充分涌流之后，才能实行共产主义\"各尽所能，按需分配\"的分配原则；在共产主义社会，个人消费品的分配方式是\"各尽所能，按需分配\"。（二）社会关系高度和谐，人们精神境界极大提高。在共产主义社会，阶级将会消亡，国家将会消亡，工业与农业、城市与乡村、脑力劳动与体力劳动的差别即\"三大差别\"必将归于消失。（三）实现每个人自由而全面的发展，人类从必然王国向自由王国飞跃。实现人的自由而全面的发展，是马克思主义追求的根本价值目标，也是共产主义社会的根本特征；在共产主义社会，劳动不再是单纯的谋生手段，而成为\"生活的第一需要\"；人类将最终从支配他们生活和命运的异己力量中解放出来，实现从必然王国向自由王国的飞跃。", "o": "(1)<span class=\"rd\">物质财富极大丰富，消费资料按需分配</span>。社会生产力高度发展，产品极大丰富是实现共产主义的必要条件。在共产主义社会，个人消费品的分配方式是“各尽所能，按需分配”\n(2)<span class=\"rd\">社会关系高度和谐，人们精神境界极大提高</span>。在共产主义社会，阶级将会消亡,国家将会消亡,工业与农业、城市与乡村、脑力劳动与体力劳动的差别即“三大差别”必将归于消失\n(3)<span class=\"rd\">实现每个人自由而全面的发展，人类从必然王国向自由王国飞跃</span>。实现人的自由而全面的发展，是马克思主义追求的根本价值目标，也是共产主义社会的根本特征。在共产主义社会，劳动不再是单纯的谋生手段，而成为“生活的第一需要”"}, {"id": "简50", "ch": "第七章 共产主义崇高理想及其最终实现", "type": "简答", "page": "P342-343", "q": "为什么说共产主义理想的实现是历史发展的必然？", "qh": "为什么说共产主义理想的实现是历史发展的必然？<span class=\"pg\">P342-343</span>", "a": "第一，共产主义理想是能够实现的理想，它与一切空想和幻想有着本质区别（共产主义理想是在对人类社会发展规律正确认识基础上作出的科学预见）。第二，共产主义理想一定会实现，是以人类社会发展规律以及资本主义社会的基本矛盾发展为依据的。第三，社会主义运动的实践，特别是社会主义国家的兴起和不断发展，已经并正在用事实证明共产主义理想实现的必然性。", "o": "(1)共产主义理想是能够实现的理想，它与一切空想和幻想有着本质区别\n(2)共产主义理想一定会实现，是以人类社会发展规律以及资本主义社会的基本矛盾发展为依据的\n(3)社会主义运动的实践，特别是社会主义国家的兴起和不断发展，已经并正在用事实证明共产主义理想实现的必然性"}];

window.QUIZPAPERS = [{"name": "押题卷（一）", "items": [{"id": "单129", "kind": "单选", "ch": "第五章 资本主义的发展及其趋势", "page": "P269-271", "q": "当代资本主义变化的新特征", "qh": "当代资本主义变化的新特征：<span class=\"rd\">【①科技创新加速资本主义生产方式变化。②国际金融垄断资本主义影响</span><span class=\"rd\">日益显现。③社会阶级层级结构呈现复杂性、多样化。④发达资本主义国家凭借经济、科技、文化传播等</span><span class=\"rd\">超级优势，在世界范围内推行霸权主义和强权政治】</span>。<span class=\"rd\">【国际金融资本的垄断】</span>成为当代资本主义最突出、最鲜明、最主要的特征<span class=\"pg\">P269-271</span>", "o": "", "a": "第一，科技创新加速资本主义生产方式变化。第二，国际金融垄断资本主义影响日益显现——资本积累方式从一般产业资本积累向国际金融垄断资本积累转变，国际金融资本的垄断成为当代资本主义最突出、最鲜明、最主要的特征；国际金融垄断资本主义经济日益证券化、数字化、虚拟化，实体经济迅速衰退。第三，社会阶级层级结构呈现复杂性、多样化。第四，发达资本主义国家凭借经济、科技、文化传播等超级优势，在世界范围内推行霸权主义和强权政治。", "freq": 13, "years": ["16.10", "17.04", "17.10", "18.4单", "19.10", "20.08", "21.10", "25.10"], "paper": "押题卷（一）"}, {"id": "单124", "kind": "单选", "ch": "第五章 资本主义的发展及其趋势", "page": "P245-248", "q": "垄断利润、垄断价格、国家垄断资本主义", "qh": "垄断资本的实质在于<span class=\"rd\">【获取垄断利润】</span>。垄断利润主要是通过垄断组织制定的<span class=\"rd\">【垄断价格】</span>来实现的。国家垄断资本主义是<span class=\"rd\">【国家政权和私人垄断资本融合在一起】</span>的垄断资本主义，其产生原因包括<span class=\"rd\">【社会生</span><span class=\"rd\">产力的发展，要求资本主义生产资料在更大范围内被支配；经济波动和经济危机的深化；缓和社会矛盾、</span><span class=\"rd\">协调利益关系的需求】</span><span class=\"pg\">P245-248</span>", "o": "", "a": "垄断资本的实质在于获取垄断利润，垄断利润是垄断资本家凭借其在社会生产和流通中的垄断地位而获得的超过平均利润的高额利润；垄断利润主要是通过垄断组织制定的垄断价格来实现的（垄断价格包括垄断高价和垄断低价两种形式，垄断价格的产生没有否定价值规律，它是价值规律在垄断资本主义阶段作用的具体体现）。国家垄断资本主义是国家政权和私人垄断资本融合在一起的垄断资本主义，其产生原因：首先，社会生产力的发展，要求资本主义生产资料在更大范围内被支配；其次，经济波动和经济危机的深化；最后，缓和社会矛盾、协调利益关系的需求。", "freq": 11, "years": ["16.04", "17.04", "20.10", "21.4单", "22.4单", "23.10", "24.4简", "25.10"], "paper": "押题卷（一）"}, {"id": "单2", "kind": "单选", "ch": "导论", "page": "P5", "q": "直接理论来源与自然科学前提", "qh": "<span class=\"rd\">【德国古典哲学、英国古典政治经济学（代表人物：斯密、李嘉图）、英法空想社会主义】</span>为马克思主义的创立提供了直接的理论来源。19世纪的三大科学发现，即<span class=\"rd\">【细胞学说、能量守恒与转化定律、生物进</span><span class=\"rd\">化论】</span>为马克思主义的产生提供了自然科学前提<span class=\"pg\">P5</span>", "o": "", "a": "德国古典哲学、英国古典政治经济学、英法空想社会主义为马克思主义的创立提供了直接的理论来源；19世纪的三大科学发现，即细胞学说、能量守恒与转化定律、生物进化论，为马克思主义的产生提供了自然科学前提。（英国古典政治经济学代表人物：斯密、李嘉图）", "freq": 8, "years": ["18.10", "18.4单", "19.04", "20.10", "23.4单", "25.10", "25.4单", "2604单"], "paper": "押题卷（一）"}, {"id": "单135", "kind": "单选", "ch": "第六章 社会主义的发展及其规律", "page": "P298-306", "q": "科学社会主义基本原则的主要内容", "qh": "科学社会主义基本原则的主要内容<span class=\"pg\">P298-306</span>(1)核心命题：<span class=\"rd\">【资本主义必然灭亡，社会主义必然胜利】</span>。“两个必然”的根本依据是人类社会发展规律(2)无产阶级是最先进最革命的阶级，肩负着推翻资本主义旧世界、建立社会主义和共产主义新世界的历史使命(3)无产阶级革命是无产阶级进行斗争的最高形式，以建立无产阶级专政的国家政权为目的(4)要在生产资料公有制基础上组织生产，以<span class=\"rd\">【满足全体社会成员的需要】</span>为生产的根本目的(5)要对社会生产进行有计划的指导和调节，实行<span class=\"rd\">【按劳分配原则】</span>(6)要合乎自然规律地改造和利用自然，努力实现人与自然的和谐共生(7)必须坚持科学的理论指导，大力发展社会主义先进文化(8)无产阶级政党是无产阶级的先锋队，社会主义事业必须始终坚持无产阶级政党的领导即共产党的领导。无产阶级政党实行民主集中制的组织原则(9)社会主义社会要大力解放和发展生产力，逐步消灭剥削和消除两极分化，实现共同富裕和社会全面进步，最终向<span class=\"rd\">【共产主义社会】</span>过渡(10)共产主义是人类最美好的社会制度，<span class=\"rd\">【实现共产主义】</span>是共产党人的最高理想", "o": "", "a": "第一，资本主义必然灭亡，社会主义必然胜利——\"两个必然\"是科学社会主义的核心命题，其根本依据是人类社会发展规律。第二，无产阶级是最先进最革命的阶级，肩负着推翻资本主义旧世界、建立社会主义和共产主义新世界的历史使命。第三，无产阶级革命是无产阶级进行斗争的最高形式，以建立无产阶级专政的国家政权为目的。第四，要在生产资料公有制基础上组织生产，以满足全体社会成员的需要为生产的根本目的。第五，要对社会生产进行有计划的指导和调节，实行按劳分配原则。第六，要合乎自然规律地改造和利用自然，努力实现人与自然的和谐共生（牢固树立绿水青山就是金山银山的理念）。第七，必须坚持科学的理论指导，大力发展社会主义先进文化。第八，无产阶级政党是无产阶级的先锋队，社会主义事业必须始终坚持无产阶级政党的领导。第九，社会主义社会要大力解放和发展生产力，逐步消灭剥削和消除两极分化，实现共同富裕和社会全面进步，并最终向共产主义社会过渡。", "freq": 7, "years": ["16.04", "18.10", "19.10", "20.08", "22.10", "24.10", "2604单"], "paper": "押题卷（一）"}, {"id": "单5", "kind": "单选", "ch": "导论", "page": "P13-16", "q": "马克思主义的基本特征", "qh": "马克思主义的基本特征：包括<span class=\"rd\">【科学性、人民性、实践性、发展性】</span>，用一句话概括为<span class=\"rd\">【科学性与革命</span><span class=\"rd\">性的统一】</span><span class=\"pg\">P13-16</span>(1)<span class=\"rd\">【人民性】</span>是马克思主义的本质属性。人民至上是马克思主义的政治立场(2)<span class=\"rd\">【实践观点】</span>是马克思主义首要的和基本的观点(3)马克思主义具有<span class=\"rd\">【与时俱进】</span>的理论品质", "o": "", "a": "马克思主义具有鲜明的科学性、人民性、实践性、发展性。（1）人民性是马克思主义的本质属性，人民至上是马克思主义的政治立场；（2）实践观点是马克思主义首要的和基本的观点；（3）马克思主义是不断发展的开放的学说，具有与时俱进的理论品质；（4）概括为科学性与革命性的统一——马克思主义\"把严格的和高度的科学性同革命性结合起来\"。", "freq": 7, "years": ["16.10", "19.04", "25.10", "25.4单"], "paper": "押题卷（一）"}, {"id": "单113", "kind": "单选", "ch": "第四章 资本主义的本质及规律", "page": "P226-227", "q": "资本主义经济危机", "qh": "<span class=\"rd\">【生产(相对)过剩】</span>是资本主义经济危机的本质特征。资本主义经济危机爆发的根本原因是<span class=\"rd\">【资本主</span><span class=\"rd\">义的基本矛盾】</span><span class=\"pg\">P226-227</span>", "o": "", "a": "资本主义发展到一定阶段，就会发生以生产过剩为基本特征的经济危机。生产过剩是资本主义经济危机的本质特征，但是这种过剩是相对过剩，即相对于劳动人民有支付能力的需求来说社会生产的商品显得过剩，而不是与劳动人民的实际需要相比的绝对过剩。资本主义经济危机爆发的根本原因是资本主义的基本矛盾，这一基本矛盾具体表现在两个方面：其一，生产无限扩大的趋势与劳动人民有支付能力的需求相对缩小的矛盾；其二，单个企业内部生产的有组织性和整个社会生产的无政府状态之间的矛盾。", "freq": 7, "years": ["19.04", "20.10", "22.10", "24.4单", "25.10"], "paper": "押题卷（一）"}, {"id": "单51", "kind": "单选", "ch": "第三章 人类社会及其发展规律", "page": "P126", "q": "社会历史观的基本问题", "qh": "<span class=\"rd\">【社会存在与社会意识的关系问题】</span>是社会历史观的基本问题<span class=\"pg\">P126</span>", "o": "", "a": "社会存在与社会意识的关系问题，是社会历史观的基本问题。正确认识社会存在与社会意识的关系，是科学把握人类社会发展规律的基础和前提。", "freq": 6, "years": ["16.04", "24.10", "24.4单", "25.10", "2604简"], "paper": "押题卷（一）"}, {"id": "单44", "kind": "单选", "ch": "第二章 实践与认识及其发展规律", "page": "P109", "q": "社会主义核心价值观", "qh": "我国社会主义核心价值观的基本内容<span class=\"pg\">P109</span>(1)国家层面：<span class=\"rd\">【富强、民主、文明、和谐】</span>(2)社会层面：<span class=\"rd\">【自由、平等、公正、法治】</span>(3)公民层面：<span class=\"rd\">【爱国、敬业、诚信、友善】</span>", "o": "", "a": "我国社会主义核心价值观的基本内容包括：富强、民主、文明、和谐（国家层面），自由、平等、公正、法治（社会层面），爱国、敬业、诚信、友善（公民层面）。它回答了建设什么样的国家、建设什么样的社会、培育什么样的公民的重大问题。", "freq": 6, "years": ["16.04", "16.10", "17.04", "17.10", "2604简"], "paper": "押题卷（一）"}, {"id": "单40", "kind": "单选", "ch": "第二章 实践与认识及其发展规律", "page": "P101", "q": "实践是检验真理的唯一标准", "qh": "实践之所以能够作为检验真理的唯一标准，是由真理的本性和实践的特点决定的<span class=\"pg\">P101</span>(1)真理是人们对客观事物及其发展规律的正确反映，它的本性在于<span class=\"rd\">【主观和客观相符合】</span>。检验真理就是检验人的主观认识同客观实际是否相符合以及符合的程度(2)实践具有<span class=\"rd\">【直接现实性】</span>，这是它的客观实在性的具体表现", "o": "", "a": "第一，从真理的本性看，真理是人们对客观事物及其发展规律的正确反映，它的本性在于主观和客观相符合，检验真理就是检验主观认识同客观实际是否相符合；第二，从实践的特点看，实践具有直接现实性，这是它的客观实在性的具体表现。实践，只有实践，才是检验真理的唯一标准。", "freq": 6, "years": ["20.08", "21.10", "25.10", "25.4简"], "paper": "押题卷（一）"}, {"id": "单94", "kind": "单选", "ch": "第四章 资本主义的本质及规律", "page": "P197", "q": "马克思劳动价值论的意义", "qh": "马克思劳动价值论的意义：<span class=\"rd\">【①扬弃了英国古典政治经济学的观点，为剩余价值论的创立奠定了基础。②</span><span class=\"rd\">揭示了私有制条件下商品经济的基本矛盾，为从物与物的关系背后揭示人与人的关系提供了理论依据。③揭</span><span class=\"rd\">示了商品经济的一般规律，对理解社会主义市场经济具有指导意义】</span><span class=\"pg\">P197-198</span>", "o": "", "a": "第一，马克思劳动价值论扬弃了英国古典政治经济学的观点，为剩余价值论的创立奠定了基础；第二，马克思劳动价值论揭示了私有制条件下商品经济的基本矛盾，为从物与物的关系背后揭示人与人的关系提供了理论依据；第三，马克思劳动价值论揭示了商品经济的一般规律，对理解社会主义市场经济具有指导意义。", "freq": 5, "years": ["17.04", "18.10", "19.10", "20.08"], "paper": "押题卷（一）"}, {"id": "简8", "kind": "简答", "ch": "第一章 世界的物质性及发展规律", "page": "P47", "q": "矛盾的普遍性与特殊性辩证关系及现实意义", "qh": "矛盾的普遍性与特殊性辩证关系的原理及其现实意义<span class=\"pg\">P47</span>", "o": "(1)二者是辩证统一关系。<span class=\"rd\">矛盾的普遍性即矛盾的共性，矛盾的特殊性即矛盾的个性</span>。矛盾的共性是无条件的、绝对的，矛盾的个性是有条件的、相对的。<span class=\"rd\">任何现实存在的事物的矛盾都是共性和个性的有机统</span><span class=\"rd\">一</span>，共性寓于个性之中，没有离开个性的共性，也没有离开共性的个性。矛盾的共性和个性相统一的关系，既是客观事物固有的辩证法，也是科学的认识方法\n(2)二者的辩证关系原理<span class=\"rd\">是马克思主义基本原理同各国实际相结合的哲学基础</span>。中国共产党坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，不断推进马克思主义中国化时代化，取得一系列重大理论成果，指引中国革命、建设、改革取得伟大胜利，同时又用中国经验和理论创新丰富发展了马克思主义", "a": "矛盾的普遍性即共性（无条件的、绝对的），特殊性即个性（有条件的、相对的）；任何现实存在的事物的矛盾都是共性和个性的有机统一，共性寓于个性之中。这一原理是马克思主义基本原理同各国实际相结合的哲学基础；中国共产党坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，推进马克思主义中国化时代化。", "freq": 14, "years": ["17.04", "18.10", "20.08", "21.4简", "22.4简", "2604简"], "paper": "押题卷（一）"}, {"id": "简49", "kind": "简答", "ch": "第七章 共产主义崇高理想及其最终实现", "page": "P333-340", "q": "共产主义社会的基本特征", "qh": "共产主义社会的基本特征(马克思主义经典作家对共产主义社会的展望)<span class=\"pg\">P333-340</span>", "o": "(1)<span class=\"rd\">物质财富极大丰富，消费资料按需分配</span>。社会生产力高度发展，产品极大丰富是实现共产主义的必要条件。在共产主义社会，个人消费品的分配方式是“各尽所能，按需分配”\n(2)<span class=\"rd\">社会关系高度和谐，人们精神境界极大提高</span>。在共产主义社会，阶级将会消亡,国家将会消亡,工业与农业、城市与乡村、脑力劳动与体力劳动的差别即“三大差别”必将归于消失\n(3)<span class=\"rd\">实现每个人自由而全面的发展，人类从必然王国向自由王国飞跃</span>。实现人的自由而全面的发展，是马克思主义追求的根本价值目标，也是共产主义社会的根本特征。在共产主义社会，劳动不再是单纯的谋生手段，而成为“生活的第一需要”", "a": "（一）物质财富极大丰富，消费资料按需分配。社会生产力高度发展，产品极大丰富，是实现共产主义的必要条件；只有在生产力增长起来，在集体财富的一切源泉都充分涌流之后，才能实行共产主义\"各尽所能，按需分配\"的分配原则；在共产主义社会，个人消费品的分配方式是\"各尽所能，按需分配\"。（二）社会关系高度和谐，人们精神境界极大提高。在共产主义社会，阶级将会消亡，国家将会消亡，工业与农业、城市与乡村、脑力劳动与体力劳动的差别即\"三大差别\"必将归于消失。（三）实现每个人自由而全面的发展，人类从必然王国向自由王国飞跃。实现人的自由而全面的发展，是马克思主义追求的根本价值目标，也是共产主义社会的根本特征；在共产主义社会，劳动不再是单纯的谋生手段，而成为\"生活的第一需要\"；人类将最终从支配他们生活和命运的异己力量中解放出来，实现从必然王国向自由王国的飞跃。", "freq": 6, "years": ["16.10", "22.10", "25.10", "25.4单"], "paper": "押题卷（一）"}, {"id": "简17", "kind": "简答", "ch": "第二章 实践与认识及其发展规律", "page": "P86-87", "q": "感性认识与理性认识的辩证关系；反对经验主义和教条主义", "qh": "感性认识和理性认识的辩证关系以及反对经验主义和教条主义的原因(实践意义)<span class=\"pg\">P86-87</span>", "o": "(1)二者是辩证统一的。①<span class=\"rd\">理性认识依赖于感性认识</span>。②<span class=\"rd\">感性认识有待于发展和深化为理性认识</span>。③<span class=\"rd\">感</span><span class=\"rd\">性认识和理性认识相互渗透、相互包含</span>。感性中有理性，理性中有感性\n(2)二者的辩证统一关系是在实践的基础上形成的，也需要在实践中发展。如果<span class=\"rd\">割裂二者的辩证统一关系</span>，<span class=\"rd\">要么走向唯理论</span>，即轻视感性认识而片面夸大理性认识的作用，在实际工作中<span class=\"rd\">犯教条主义</span>的错误；<span class=\"rd\">要么走</span><span class=\"rd\">向经验论</span>，即轻视理性认识而片面夸大感性认识的作用，<span class=\"rd\">导致</span>实践中的<span class=\"rd\">经验主义</span>", "a": "（1）理性认识依赖于感性认识；（2）感性认识有待于发展和深化为理性认识；（3）二者相互渗透、相互包含，感性中有理性，理性中有感性。割裂二者的辩证统一，要么走向唯理论（轻视感性认识、夸大理性认识，犯教条主义错误），要么走向经验论（轻视理性认识、夸大感性认识，导致经验主义）。", "freq": 6, "years": ["16.04", "17.10", "20.10", "23.4单"], "paper": "押题卷（一）"}, {"id": "简47", "kind": "简答", "ch": "第六章 社会主义的发展及其规律", "page": "P316-317", "q": "如何探索适合本国国情的社会主义发展道路", "qh": "如何探索适合本国国情的社会主义发展道路<span class=\"pg\">P316-317</span>", "o": "(1)必须坚持对待马克思主义的科学态度\n(2)必须从当时当地的历史条件出发，坚持走自己的路\n(3)必须充分吸收人类一切优秀文明成果", "a": "既然社会主义发展道路具有多样性，那么努力探索适合本国国情的社会主义发展道路，就是无产阶级执政党必须领导全国人民为之奋斗的神圣使命和光荣任务。第一，探索社会主义发展道路，必须坚持对待马克思主义的科学态度（马克思主义经典作家并没有提供各国社会主义发展道路的现成方案）。第二，必须从当时当地的历史条件出发，坚持\"走自己的路\"（立足本国国情，走自己的路，是社会主义建设历史经验的总结）。第三，必须充分吸收人类一切优秀文明成果（社会主义要赢得与资本主义相比较的优势，就必须大胆吸收和借鉴人类社会创造的一切优秀文明成果，包括发达资本主义国家一切反映现代化生产规律的先进经营方式和管理方法）。", "freq": 6, "years": ["17.10", "23.10", "2604简"], "paper": "押题卷（一）"}]}, {"name": "押题卷（二）", "items": [{"id": "单78", "kind": "单选", "ch": "第三章 人类社会及其发展规律", "page": "P165-167", "q": "科学技术在社会发展中的作用", "qh": "科学技术在社会发展中的作用：科技革命是推动经济和社会发展的强大杠杆。<span class=\"rd\">【①对生产方式产生了深</span><span class=\"rd\">刻影响。改变了社会生产力的构成要素；改变了人们的劳动形式；改变了社会经济结构；②对生活方式产生了</span><span class=\"rd\">巨大影响；③促进了思维方式的变革】</span><span class=\"pg\">P165-167</span>", "o": "", "a": "科技革命是推动经济和社会发展的强大杠杆。第一，对生产方式产生了深刻影响：改变了社会生产力的构成要素，改变了人们的劳动形式，改变了社会经济结构；第二，对生活方式产生了巨大影响；第三，促进了思维方式的变革。", "freq": 5, "years": ["19.10", "23.10", "23.4单", "24.4简"], "paper": "押题卷（二）"}, {"id": "单33", "kind": "单选", "ch": "第二章 实践与认识及其发展规律", "page": "P83", "q": "辩证唯物主义认识论与唯心、旧唯物认识论的根本区别", "qh": "辩证唯物主义认识论<span class=\"rd\">【坚持以科学的社会实践为特征的实践观】</span>，即实践是人类能动地改造世界的社会性的物质活动。这是马克思主义认识论即辩证唯物主义认识论与唯心主义认识论、旧唯物主义认识论的根本区别<span class=\"pg\">P83</span>", "o": "", "a": "坚持以科学的社会实践为特征的实践观，即实践是人类能动地改造世界的社会性的物质活动。这是马克思主义认识论即辩证唯物主义认识论与唯心主义认识论、旧唯物主义认识论的根本区别。", "freq": 5, "years": ["16.04", "19.04", "22.10", "2604单"], "paper": "押题卷（二）"}, {"id": "单87", "kind": "单选", "ch": "第四章 资本主义的本质及规律", "page": "P189", "q": "劳动的二重性", "qh": "生产商品的劳动具有二重性：<span class=\"rd\">【具体劳动和抽象劳动】</span><span class=\"pg\">P189</span>(1)<span class=\"rd\">【具体劳动】</span>指生产一定使用价值的具体形式的劳动(2)<span class=\"rd\">【抽象劳动】</span>指撇开一切具体形式的、无差别的一般人类劳动，即人的脑力和体力的耗费(3)商品二因素与劳动二重性的关系：<span class=\"rd\">【生产商品的具体劳动创造商品的使用价值，抽象劳动形成商品的价</span><span class=\"rd\">值。劳动的二重性决定了商品的二因素】</span>(4)具体劳动与抽象劳动是<span class=\"rd\">【对立统一的关系】</span>：它们在时间上和空间上是统一的，是商品生产者的同一劳动过程不可分割的两个方面；具体劳动所反映的是人与自然的关系，是劳动的自然属性，抽象劳动所反映的是商品生产者的社会关系，是劳动的社会属性", "o": "", "a": "商品是劳动产品，生产商品的劳动具有二重性，即具体劳动和抽象劳动。具体劳动是指生产一定使用价值的具体形式的劳动；抽象劳动是指撇开一切具体形式的、无差别的一般人类劳动，即人的脑力和体力的耗费。生产商品的具体劳动创造商品的使用价值，抽象劳动形成商品的价值——劳动的二重性决定了商品的二因素。具体劳动和抽象劳动也是对立统一的关系：一方面，它们在时间上和空间上是统一的，是商品生产者的同一劳动过程不可分割的两个方面；另一方面，具体劳动所反映的是人与自然的关系，是劳动的自然属性，而抽象劳动所反映的是商品生产者的社会关系，是劳动的社会属性。", "freq": 5, "years": ["16.10", "22.4单", "23.10", "25.10"], "paper": "押题卷（二）"}, {"id": "单102", "kind": "单选", "ch": "第四章 资本主义的本质及规律", "page": "P217-218", "q": "资本的构成", "qh": "由生产的技术水平所决定的生产资料和劳动力之间的比例叫作<span class=\"rd\">【资本的技术构成】</span>。不变资本和可变资本价值之间的比例叫作<span class=\"rd\">【资本的价值构成】</span>。由资本的技术构成决定并反映技术构成变化的资本价值构成叫作<span class=\"rd\">【资本的有机构成】</span><span class=\"pg\">P217-218</span>", "o": "", "a": "这种由生产的技术水平所决定的生产资料和劳动力之间的比例，叫作资本的技术构成；不变资本和可变资本价值之间的比例，叫作资本的价值构成；这种由资本的技术构成决定并反映技术构成变化的资本价值构成，叫作资本的有机构成。在资本主义生产过程中，资本有机构成的提高是一般趋势，这是由资本的本性决定的。", "freq": 4, "years": ["16.04", "17.04", "17.10", "25.4单"], "paper": "押题卷（二）"}, {"id": "单138", "kind": "单选", "ch": "第七章 共产主义崇高理想及其最终实现", "page": "P345-348", "q": "实现共产主义是长期的历史过程", "qh": "实现共产主义是长期的历史过程：<span class=\"rd\">【①资本主义的灭亡和向社会主义的转变是一个长期的历史过程。②</span><span class=\"rd\">社会主义社会的充分发展和最终向共产主义过渡需要很长的历史时期】</span>。<span class=\"rd\">【社会主义】</span>是共产主义的初级阶段，也是实现共产主义的必由之路。<span class=\"pg\">P345-348</span>", "o": "", "a": "共产主义一定要实现，共产主义一定能够实现，但共产主义的实现是一个十分漫长而且充满艰难曲折的历史过程。资本主义从兴盛走向衰落和灭亡需要相当长的历史时期；从资本主义到社会主义有一个过渡时期，这是一个充满矛盾和斗争的复杂历史过程；共产主义社会的初级阶段即社会主义社会是一个长期的历史过程，特别是从不发达的社会主义到发达的社会主义，更有一个长期发展的过程；最后，从发达的社会主义向共产主义的转变和过渡，也需要一定的历史时期。社会主义是共产主义的初级阶段，也是实现共产主义的必由之路。", "freq": 4, "years": ["17.04", "17.10", "24.4单"], "paper": "押题卷（二）"}, {"id": "单53", "kind": "单选", "ch": "第三章 人类社会及其发展规律", "page": "P127-129", "q": "社会存在", "qh": "<span class=\"rd\">【社会存在】</span>指社会物质生活条件，是社会生活的物质方面，包括<span class=\"pg\">P127-129</span>(1)自然地理环境：其优劣对<span class=\"rd\">【劳动生产率的提高产生积极或消极的影响，并对社会发展起促进或延缓的作</span><span class=\"rd\">用】</span>(2)人口因素：人口的数量、质量和结构等因素<span class=\"rd\">【对生产发展和社会进步起加速或延缓的作用】</span>。适度的人口对社会发展起加速作用，过密或过疏的人口则对社会发展起延缓作用(3)物质生产方式：指人们为获取物质生活资料而进行的生产活动的方式，是<span class=\"rd\">【生产力和生产关系】</span>的统一体", "o": "", "a": "社会存在是指社会物质生活条件，是社会生活的物质方面，主要包括自然地理环境、人口因素和物质生产方式。（1）自然地理环境是人们生活和生产的自然基础，其优劣对劳动生产率的提高产生积极或消极影响，对社会发展起促进或延缓的作用；（2）人口因素对社会发展起加速或延缓的作用，适度人口起加速作用，过密或过疏则起延缓作用；（3）物质生产方式是人们为获取物质生活资料而进行的生产活动的方式，是生产力和生产关系的统一体。", "freq": 4, "years": ["17.10", "23.4简", "25.10"], "paper": "押题卷（二）"}, {"id": "单111", "kind": "单选", "ch": "第四章 资本主义的本质及规律", "page": "P225", "q": "剩余价值理论的意义", "qh": "剩余价值理论的意义：<span class=\"rd\">【揭露资本主义生产关系的剥削本质，阐明资产阶级与无产阶级之间阶级斗争</span><span class=\"rd\">的经济根源，指出无产阶级革命的历史必然性；是马克思经济学说的核心内容和基石，是无产阶级反对资</span><span class=\"rd\">产阶级、揭示资本主义制度剥削本质的锐利武器】</span><span class=\"pg\">P225</span>", "o": "", "a": "马克思通过分析剩余价值的生产、积累、流通以及分配过程，揭示了资本主义生产关系的剥削本质，阐明了资产阶级与无产阶级之间阶级斗争的经济根源，指出了无产阶级革命的历史必然性。剩余价值理论是马克思经济学说的核心内容和基石，是无产阶级反对资产阶级、揭示资本主义制度剥削本质的锐利武器。", "freq": 4, "years": ["17.10", "18.4单", "22.10"], "paper": "押题卷（二）"}, {"id": "单15", "kind": "单选", "ch": "第一章 世界的物质性及发展规律", "page": "P39-40", "q": "世界的物质统一性原理", "qh": "世界的物质统一性原理<span class=\"pg\">P39-40</span>(1)马克思主义认为，世界的统一性在于它的物质性，世界统一于物质：<span class=\"rd\">【自然界是物质的；人类社会本质</span><span class=\"rd\">上是生产实践基础上形成的物质体系；人的意识统一于物质】</span>(2)现实意义：世界的物质统一性原理是辩证唯物主义最基本、最核心的观点，是马克思主义的基石。有助于树立唯物主义科学世界观，为进一步确立正确的人生观和价值观奠定坚实的基础。有助于确立正确的思想路线和思想方法，在认识世界和改造世界中，遵循一切从实际出发、实事求是的原则。一切从实际出发是在坚持和发展中国特色社会主义伟大实践中想问题、办事情的根本立足点", "o": "", "a": "\"世界的真正的统一性在于它的物质性\"——自然界是物质的，人类社会本质上是生产实践基础上形成的物质体系，人的意识统一于物质。世界的物质统一性原理是辩证唯物主义最基本、最核心的观点，是马克思主义的基石；有助于树立唯物主义科学世界观，有助于确立正确的思想路线和思想方法，遵循一切从实际出发、实事求是的原则。", "freq": 4, "years": ["19.04", "20.08", "21.10", "22.4单"], "paper": "押题卷（二）"}, {"id": "单31", "kind": "单选", "ch": "第二章 实践与认识及其发展规律", "page": "P81", "q": "认识的本质", "qh": "认识的本质是<span class=\"rd\">【主体在实践基础上对客体的能动反映】</span>，这是辩证唯物主义认识论对认识本质的科学回答<span class=\"pg\">P81</span>", "o": "", "a": "认识的本质是主体在实践基础上对客体的能动反映，这是辩证唯物主义认识论对认识本质的科学回答。", "freq": 4, "years": ["19.10", "20.08", "23.4单", "25.10"], "paper": "押题卷（二）"}, {"id": "单74", "kind": "单选", "ch": "第三章 人类社会及其发展规律", "page": "P155-156", "q": "两对社会基本矛盾的关系", "qh": "两对社会基本矛盾之间的关系：<span class=\"rd\">【生产力和生产关系的矛盾是更为基本的矛盾，它决定经济基础和上</span><span class=\"rd\">层建筑的矛盾的产生和发展；经济基础和上层建筑的矛盾也会影响和制约生产力和生产关系的矛盾，生产</span><span class=\"rd\">力和生产关系矛盾的最终解决有赖于经济基础和上层建筑矛盾的解决】</span><span class=\"pg\">P155-156</span>", "o": "", "a": "生产力和生产关系的矛盾是更为基本的矛盾，它决定经济基础和上层建筑的矛盾的产生和发展；经济基础和上层建筑的矛盾也会影响和制约生产力和生产关系的矛盾，生产力和生产关系矛盾的最终解决有赖于经济基础和上层建筑矛盾的解决。", "freq": 4, "years": ["19.10", "20.10", "21.4简"], "paper": "押题卷（二）"}, {"id": "简1", "kind": "简答", "ch": "导论", "page": "P2", "q": "什么是马克思主义？", "qh": "什么是马克思主义？<span class=\"pg\">P2</span>", "o": "马克思主义是<span class=\"rd\">由马克思、恩格斯创立</span>并为后继者所不断发展的科学理论体系，是关于自然、社会和人类思维发展一般规律的学说，是关于社会主义必然代替资本主义、最终实现共产主义的学说，是关于无产阶级解放、全人类解放和每个人自由而全面发展的学说，是无产阶级政党和社会主义国家的指导思想，是指引人民创造美好生活的行动指南", "a": "马克思主义是由马克思、恩格斯创立并为后继者所不断发展的科学理论体系，是关于自然、社会和人类思维发展一般规律的学说，是关于社会主义必然代替资本主义、最终实现共产主义的学说，是关于无产阶级解放、全人类解放和每个人自由而全面发展的学说，是无产阶级政党和社会主义国家的指导思想，是指引人民创造美好生活的行动指南。马克思主义哲学、马克思主义政治经济学和科学社会主义是其三个基本组成部分。", "freq": 6, "years": ["18.4简", "22.4简", "25.4简"], "paper": "押题卷（二）"}, {"id": "简34", "kind": "简答", "ch": "第四章 资本主义的本质及规律", "page": "P212-214", "q": "剩余价值生产的两种基本方法", "qh": "剩余价值生产的基本方法<span class=\"pg\">P212-214</span>", "o": "(1)<span class=\"rd\">绝对剩余价值生产</span>。绝对剩余价值指在必要劳动时间不变的条件下，由于<span class=\"rd\">延长工作日的长度或提高</span><span class=\"rd\">劳动强度</span>而生产的剩余价值。在必要劳动时间既定的条件下，工作日越长，剩余劳动时间越长，资本家从工人身上榨取的剩余价值就越多，从而剩余价值率就越高。为了让工人生产更多的剩余价值，资本家除了使用延长劳动时间的方法，还使用提高工人劳动强度的方法，迫使工人更加紧张地劳动，让他们在同样长的劳动时间内比以前耗费更多的脑力和体力\n(2)<span class=\"rd\">相对剩余价值生产</span>。相对剩余价值指在工作日长度不变的条件下，通过<span class=\"rd\">缩短必要劳动时间而相对延长剩</span><span class=\"rd\">余劳动时间</span>所生产的剩余价值。为了在工作日长度既定的条件下提高剥削程度，资本家在调整必要劳动时间与剩余劳动时间的比例上下功夫，通过缩短必要劳动时间、相对延长剩余劳动时间，增加剩余价值的生产。缩短必要劳动时间是通过<span class=\"rd\">全社会劳动生产率的提高</span>实现的", "a": "（1）绝对剩余价值生产：绝对剩余价值是指在必要劳动时间不变的条件下，由于延长工作日的长度或提高劳动强度而生产的剩余价值。在必要劳动时间既定的条件下，工作日越长，剩余劳动时间越长，资本家从工人身上榨取的剩余价值就越多，从而剩余价值率就越高；除了使用延长劳动时间的方法，资本家还使用提高工人劳动强度的方法，迫使工人更加紧张地劳动。（2）相对剩余价值生产：相对剩余价值是指在工作日长度不变的条件下，通过缩短必要劳动时间而相对延长剩余劳动时间所生产的剩余价值。缩短必要劳动时间是通过全社会劳动生产率的提高实现的，而全社会劳动生产率的提高是资本家追逐超额剩余价值的结果。", "freq": 5, "years": ["17.04", "21.10", "21.4简"], "paper": "押题卷（二）"}, {"id": "简36", "kind": "简答", "ch": "第五章 资本主义的发展及其趋势", "page": "P236-238", "q": "资本主义意识形态的含义、本质、历史进步性与阶级局限性", "qh": "资本主义意识形态的含义、本质、历史进步性、阶级局限性<span class=\"pg\">P236-238</span>", "o": "(1)是在资本主义国家中占统治地位、反映了作为统治阶级的资产阶级利益和要求的各种思想理论和观念的总和\n(2)本质：①是资本主义社会的观念上层建筑，<span class=\"rd\">是为资本主义的经济基础服务的，是为资本主义国家的政治</span><span class=\"rd\">上层建筑服务的</span>。②<span class=\"rd\">是资产阶级的阶级意识的集中体现</span>\n(3)历史进步性：资本主义在长期发展中<span class=\"rd\">创造出物质财富，也创造出精神成果</span>。这些精神成果有相当一部分是以意识形态的形式被保存下来。这些成果中包含着人类文明进步的成就。特别是在资本主义国家建立起来以前，文艺复兴时期和资产阶级革命时期的资产阶级思想理论和观念，<span class=\"rd\">在反对封建主义和宗教神学、推</span><span class=\"rd\">动资产阶级革命的发展以及促进资本主义国家建立的过程中曾起积极作用</span>，因而其<span class=\"rd\">主要社会作用是推动历</span><span class=\"rd\">史前进</span>的，是进步的。我们应该加以研究、参考和借鉴\n(4)阶级局限性：资本主义意识形态作为资产阶级经济和政治的集中反映，<span class=\"rd\">是为巩固资产阶级的政治统治、</span><span class=\"rd\">维护资本主义的政治制度，为资产阶级的阶级剥削和阶级压迫服务的</span>。我们必须加以分析、批判和摒弃", "a": "资本主义意识形态是在资本主义国家中占统治地位、反映了作为统治阶级的资产阶级利益和要求的各种思想理论和观念的总和，其中一以贯之的核心思想，主要是私有制神圣不可侵犯观念和个人主义价值观。（本质）第一，资本主义意识形态是资本主义社会的观念上层建筑，是为资本主义的经济基础服务的，因而是为资本主义国家的政治上层建筑服务的；第二，资本主义意识形态是资产阶级的阶级意识的集中体现。（历史进步性）特别是在资本主义国家建立起来以前，那些文艺复兴时期和资产阶级革命时期的资产阶级思想理论和观念，在反对封建主义和宗教神学、推动资产阶级革命的发展以及促进资本主义国家建立的过程中曾起过积极的作用，因而其主要社会作用是推动历史前进的，是进步的；对于资本主义意识形态中的文明进步成分，我们应该加以研究、参考和借鉴。（阶级局限性）资本主义意识形态具有欺骗性和虚伪性，它\"用歪曲的形式把自己的特殊利益冒充为普遍的利益\"；作为资产阶级经济和政治的集中反映，是为巩固资产阶级的政治统治、维护资本主义的政治制度，为资产阶级的阶级剥削和阶级压迫服务的，因而具有极大的阶级的和历史的局限性，必须加以分析、批判和摒弃。", "freq": 5, "years": ["20.08", "22.4简", "23.10"], "paper": "押题卷（二）"}, {"id": "简21", "kind": "简答", "ch": "第二章 实践与认识及其发展规律", "page": "P117", "q": "党的思想路线的基本内涵和核心", "qh": "党思想路线的基本内涵和核心<span class=\"pg\">P117</span>", "o": "思想路线就是人们在实践活动中用以指导行动的基本原则和方法，是化为指导思想用以支配行动的认识路线。中国共产党思想路线的基本内涵：<span class=\"rd\">一切从实际出发，理论联系实际，实事求是，在实践中检验和</span><span class=\"rd\">发展真理</span>，其核心是<span class=\"rd\">实事求是</span>", "a": "思想路线是化为指导思想用以支配行动的认识路线。中国共产党思想路线的基本内涵是：一切从实际出发，理论联系实际，实事求是，在实践中检验和发展真理，其核心是实事求是。", "freq": 3, "years": ["20.10", "23.10", "25.10"], "paper": "押题卷（二）"}]}, {"name": "押题卷（三）", "items": [{"id": "单105", "kind": "单选", "ch": "第四章 资本主义的本质及规律", "page": "P221", "q": "社会再生产的核心问题", "qh": "社会再生产的核心问题是<span class=\"rd\">【社会总产品的实现问题】</span>，即社会总产品的<span class=\"rd\">【价值补偿和实物补偿问题】</span><span class=\"pg\">P221</span>", "o": "", "a": "社会再生产的核心问题是社会总产品的实现问题，即社会总产品的价值补偿和实物补偿问题。", "freq": 4, "years": ["19.10", "20.10", "23.4简"], "paper": "押题卷（三）"}, {"id": "单127", "kind": "单选", "ch": "第五章 资本主义的发展及其趋势", "page": "P253-254", "q": "国际垄断同盟与国际经济组织", "qh": "国际垄断同盟：早期主要是国际卡特尔，当代以<span class=\"rd\">【国家垄断资本主义的国际联盟】</span>为主。二战以来，从事国际经济协调、维护国际经济秩序的国际经济组织有<span class=\"rd\">【国际货币基金组织、世界银行、世界贸易组织】</span><span class=\"pg\">P253-254</span>", "o": "", "a": "各资本主义国家的垄断组织通过订立协议建立起国际垄断资本的联盟，即国际垄断同盟，以便在世界范围内形成垄断，并在经济上瓜分世界。早期的国际垄断同盟主要是国际卡特尔；当代国际垄断同盟的形式以国家垄断资本主义的国际联盟为主。第二次世界大战以来，从事国际经济协调、维护国际经济秩序的国际经济组织主要有三个，即国际货币基金组织、世界银行和世界贸易组织。", "freq": 4, "years": ["20.10", "23.10", "24.10"], "paper": "押题卷（三）"}, {"id": "单28", "kind": "单选", "ch": "第二章 实践与认识及其发展规律", "page": "P73-74", "q": "科学实践观及其意义", "qh": "科学实践观揭示了实践的本质，指明实践是<span class=\"rd\">【人类能动地改造世界的社会性的物质活动】</span>。科学实践观的意义：<span class=\"rd\">【克服了旧唯物主义的根本缺陷，为辩证唯物主义的创立奠定了科学的理论基础；揭示了实践</span><span class=\"rd\">对认识的决定作用，为能动的、革命的反映论的创立奠定了科学的理论基础；在人类思想史上第一次揭示</span><span class=\"rd\">了社会生活的实践本质，为唯物史观的创立奠定了科学的理论基础；为人们能动地认识世界和改造世界提</span><span class=\"rd\">供了基本的思想方法和工作方法】</span><span class=\"pg\">P73-74</span>", "o": "", "a": "实践是人类能动地改造世界的社会性的物质活动。科学实践观的意义：第一，克服了旧唯物主义的根本缺陷，为辩证唯物主义的创立奠定科学理论基础；第二，揭示了实践对认识的决定作用，为能动的、革命的反映论的创立奠定科学理论基础；第三，在人类思想史上第一次揭示了社会生活的实践本质，为唯物史观的创立奠定科学理论基础；第四，为人们能动地认识世界和改造世界提供了基本的思想方法和工作方法。", "freq": 4, "years": ["20.08", "21.4简"], "paper": "押题卷（三）"}, {"id": "单8", "kind": "单选", "ch": "第一章 世界的物质性及发展规律", "page": "P26-27", "q": "哲学基本问题", "qh": "<span class=\"rd\">【存在和思维的关系问题又称为物质和意识的关系问题】</span>构成了全部哲学的基本问题。哲学基本问题主要包括两方面内容：<span class=\"pg\">P26-27</span>(1)<span class=\"rd\">【存在和思维、物质和意识谁为本原的问题，即何者为第一性的问题】</span>；对这一问题的不同回答形成了<span class=\"rd\">【唯物主义和唯心主义】</span>(2)<span class=\"rd\">【存在和思维、物质和意识是否具有同一性的问题】</span>，即思维能否正确地反映存在、人能否认识或彻底认识世界的问题；对这一问题的不同回答产生了<span class=\"rd\">【可知论和不可知论】</span>", "o": "", "a": "存在和思维的关系问题又称为物质和意识的关系问题，构成了全部哲学的基本问题。包括两方面：一是存在和思维、物质和意识谁为本原即何者为第一性的问题，形成唯物主义和唯心主义；二是二者是否具有同一性的问题，产生可知论和不可知论。", "freq": 3, "years": ["16.10", "22.4单", "25.4单"], "paper": "押题卷（三）"}, {"id": "单58", "kind": "单选", "ch": "第三章 人类社会及其发展规律", "page": "P134", "q": "社会基本矛盾和基本规律", "qh": "<span class=\"rd\">【生产力与生产关系、经济基础与上层建筑之间的矛盾】</span>是人类社会基本矛盾。<span class=\"rd\">【生产力与生产关系</span><span class=\"rd\">矛盾运动的规律、经济基础与上层建筑矛盾运动的规律】</span>是人类社会发展的基本规律<span class=\"pg\">P134</span>", "o": "", "a": "生产力与生产关系、经济基础与上层建筑之间的矛盾，是人类社会基本矛盾；生产力与生产关系矛盾运动的规律、经济基础与上层建筑矛盾运动的规律，是人类社会发展的基本规律。", "freq": 3, "years": ["18.4单", "21.10"], "paper": "押题卷（三）"}, {"id": "单9", "kind": "单选", "ch": "第一章 世界的物质性及发展规律", "page": "P29", "q": "物质的唯一特性", "qh": "马克思主义的物质观认为<span class=\"rd\">【客观实在性】</span>是物质的唯一特性<span class=\"pg\">P29</span>", "o": "", "a": "马克思主义的物质观认为，客观实在性是物质的唯一特性，这既肯定了哲学物质范畴同自然科学物质结构理论的联系，又把它们区别开来。", "freq": 3, "years": ["19.04", "24.4单", "25.10"], "paper": "押题卷（三）"}, {"id": "单123", "kind": "单选", "ch": "第五章 资本主义的发展及其趋势", "page": "P244", "q": "金融资本与金融寡头", "qh": "<span class=\"rd\">【金融资本】</span>是由工业垄断资本和银行垄断资本融合而形成的垄断资本。<span class=\"rd\">【金融寡头】</span>指操纵国民经济命脉，并在实际上控制国家政权的少数垄断资本家或垄断资本家集团。金融寡头在经济领域中的统治主要是通过<span class=\"rd\">【参与制】</span>实现的，对国家机器(政治上)的控制主要是通过同政府的<span class=\"rd\">【个人联合】</span>来实现的<span class=\"pg\">P244</span>", "o": "", "a": "金融资本是由工业垄断资本和银行垄断资本融合在一起而形成的一种垄断资本；通过金融联系、资本参与和人事参与，银行垄断资本和工业垄断资本密切地融合在一起，产生了金融资本。在金融资本形成的基础上，产生了金融寡头。金融寡头是指操纵国民经济命脉，并在实际上控制国家政权的少数垄断资本家或垄断资本家集团。金融寡头在经济领域中的统治主要是通过\"参与制\"（通过掌握一定数量的股票来层层控制企业的制度）实现的；对国家机器的控制，主要是通过同政府的\"个人联合\"来实现的。", "freq": 3, "years": ["19.10", "23.10", "25.4单"], "paper": "押题卷（三）"}, {"id": "单66", "kind": "单选", "ch": "第三章 人类社会及其发展规律", "page": "P142-143", "q": "经济基础与上层建筑的辩证统一", "qh": "经济基础与上层建筑是辩证统一的：<span class=\"pg\">P142-143</span>(1)<span class=\"rd\">【经济基础决定上层建筑，上层建筑反作用于经济基础】</span>(2)经济基础与上层建筑的相互作用构成二者的矛盾运动(3)经济基础和上层建筑的内在联系构成了<span class=\"rd\">【上层建筑一定要适合经济基础状况的规律】</span>", "o": "", "a": "（1）经济基础决定上层建筑，上层建筑反作用于经济基础；（2）二者的相互作用构成矛盾运动；（3）经济基础和上层建筑的内在联系构成了上层建筑一定要适合经济基础状况的规律。", "freq": 3, "years": ["21.4单", "23.4单", "25.10"], "paper": "押题卷（三）"}, {"id": "单92", "kind": "单选", "ch": "第四章 资本主义的本质及规律", "page": "P192", "q": "价值规律的内容与表现形式", "qh": "价值规律：<span class=\"pg\">P192</span>(1)是商品生产和商品交换的基本规律(2)主要内容和客观要求：<span class=\"rd\">【商品的价值量由生产商品的社会必要劳动时间决定，商品交换以价值量为基础，</span><span class=\"rd\">按照等价交换的原则进行】</span>(3)表现形式：<span class=\"rd\">【商品的价格围绕商品的价值自发波动】</span>", "o": "", "a": "价值规律的主要内容和客观要求是：商品的价值量由生产商品的社会必要劳动时间决定，商品交换以价值量为基础，按照等价交换的原则进行。在商品经济中，价值规律的表现形式是：商品的价格围绕商品的价值自发波动。", "freq": 3, "years": ["21.10", "22.10"], "paper": "押题卷（三）"}, {"id": "单99", "kind": "单选", "ch": "第四章 资本主义的本质及规律", "page": "P210", "q": "资本主义生产过程的二重性", "qh": "资本主义生产过程是<span class=\"rd\">【劳动过程与价值增殖过程】</span>的统一<span class=\"pg\">P210</span>(1)资本主义劳动过程的特点：工人在资本家的监督下劳动，他们的劳动隶属于资本家；劳动的成果或者产品全部归资本家所有(2)价值增殖过程是剩余价值的生产过程，是超过劳动力价值的补偿这个一定点而延长了的价值形成过程", "o": "", "a": "资本主义生产过程具有二重性：一方面是生产物质资料的劳动过程，另一方面是生产剩余价值的过程即价值增殖过程，资本主义生产过程是劳动过程和价值增殖过程的统一。由于资本主义劳动过程的要素都为资本家所占有，这就决定了资本主义劳动过程的两个特点：其一，工人在资本家的监督下劳动，他们的劳动隶属于资本家；其二，劳动的成果或者产品全部归资本家所有。所谓价值增殖过程，是超过劳动力价值的补偿这个一定点而延长了的价值形成过程。", "freq": 3, "years": ["19.04", "22.10"], "paper": "押题卷（三）"}, {"id": "简43", "kind": "简答", "ch": "第五章 资本主义的发展及其趋势", "page": "P266-268", "q": "二战后资本主义发生变化的原因和实质", "qh": "二战后(当代)资本主义发生变化的原因和实质<span class=\"pg\">P266-268</span>", "o": "(1)原因：①<span class=\"rd\">科学技术革命和生产力的发展</span>，是资本主义发生变化的根本推动力量。②<span class=\"rd\">工人阶级争取自</span><span class=\"rd\">身权利和利益的斗争</span>，是推动资本主义发生变化的重要力量。③<span class=\"rd\">社会主义制度初步显示的优越性</span>对资本主义产生重要影响。④<span class=\"rd\">主张改良主义的政党对资本主义制度的改革</span>，也对资本主义发生变化起到了重要作用\n(2)实质：①二战后资本主义发生的变化从根本上说<span class=\"rd\">是人类社会发展一般规律和资本主义经济规律作用的结</span><span class=\"rd\">果</span>。②二战后资本主义发生的变化<span class=\"rd\">是在资本主义制度基本框架内的变化</span>，并不意味着资本主义生产关系的根本性质发生变化。③二战后资本主义发生的变化<span class=\"rd\">并没有改变资本主义制度的本质</span>，并没有克服资本主义的基本矛盾，也没有改变马克思主义关于资本主义的基本论断的科学性", "a": "（原因）首先，科学技术革命和生产力的发展，是资本主义发生变化的根本推动力量；其次，工人阶级争取自身权利和利益的斗争，是推动资本主义发生变化的重要力量；再次，社会主义制度初步显示的优越性对资本主义产生了重要影响；最后，主张改良主义的政党对资本主义制度的改革，也对资本主义发生变化起到了重要作用。（实质）第一，第二次世界大战后资本主义发生的变化从根本上说是人类社会发展一般规律和资本主义经济规律作用的结果，是资本主义生产方式为适应生产力发展要求而作出自我调节的结果；第二，这些变化是在资本主义制度基本框架内的变化，并不意味着资本主义生产关系的根本性质发生了变化（只要生产资料私有制和雇佣劳动还存在，只要生产剩余价值的规律还发生作用，资本主义生产关系的根本性质就不会发生变化）；第三，这些变化并没有改变资本主义制度的本质，并没有克服资本主义的基本矛盾，也没有改变马克思主义关于资本主义的基本论断的科学性，根源于资本主义基本矛盾的经济危机依然是资本主义不可克服的痼疾。", "freq": 3, "years": ["24.4单", "2604简"], "paper": "押题卷（三）"}, {"id": "简45", "kind": "简答", "ch": "第六章 社会主义的发展及其规律", "page": "P306-308", "q": "如何正确把握科学社会主义的基本原则", "qh": "如何正确把握科学社会主义的基本原则<span class=\"pg\">P306-308</span>", "o": "(1)必须始终坚持科学社会主义基本原则，反对任何背离科学社会主义基本原则的错误倾向\n(2)要善于把科学社会主义基本原则与本国实际和时代特征相结合，创造性地回答和解决社会主义革命、建设、改革中的重大问题\n(3)紧跟时代和实践的发展，在不断总结新鲜经验中进一步丰富和发展科学社会主义基本原则", "a": "第一，必须始终坚持科学社会主义基本原则，反对任何背离科学社会主义基本原则的错误倾向（科学社会主义基本原则揭示了资本主义生产方式的基本矛盾，阐明了社会主义代替资本主义的历史必然性；19世纪末20世纪初伯恩施坦否定基本原则，走上修正主义道路）。第二，要善于把科学社会主义基本原则与本国实际和时代特征相结合，创造性地回答和解决社会主义革命、建设、改革中的重大问题（共产党人必须将基本原则运用于实践，发挥这些原则指导实践的巨大威力）。第三，紧跟时代和实践的发展，在不断总结新鲜经验中进一步丰富和发展科学社会主义基本原则（科学社会主义基本原则不是一成不变的教条，而是随着社会主义实践而不断丰富和发展的学说）。", "freq": 3, "years": ["19.04", "24.4单"], "paper": "押题卷（三）"}, {"id": "简46", "kind": "简答", "ch": "第六章 社会主义的发展及其规律", "page": "P312-314", "q": "经济文化相对落后国家社会主义建设的艰巨性和长期性", "qh": "经济文化相对落后的国家社会主义建设的艰巨性和长期性<span class=\"pg\">P312-314</span>", "o": "社会主义建设必然是不断探索的长期过程。在经济文化相对落后的国家建设社会主义，更具有历史长期性。\n(1)<span class=\"rd\">生产力发展状况的制约</span>。在相当长的历史时期内，社会主义国家在经济上落后于发达资本主义国家，这就决定了在社会主义制度下必须把大力发展生产力作为根本任务，努力完成发达资本主义国家在资本主义条件下已经实现的工业化和生产社会化、商品化、现代化的艰巨任务，需要很长时间的努力\n(2)<span class=\"rd\">经济基础和上层建筑发展状况的制约</span>。社会主义民主政治建设受到国家的经济、政治、文化条件的严重制约，面临许多现实问题和困难，将是一个长期的过程\n(3)<span class=\"rd\">国际环境的严峻挑战</span>。社会主义国家尚处于强大的资本主义世界的包围之中，受到资本主义列强的遏制和扼杀，面临异常严峻的国际环境\n(4)<span class=\"rd\">马克思主义执政党对社会主义发展道路的探索和对社会主义建设规律的认识，需要长期的过程</span>", "a": "社会主义是一项崭新的事业，其建设必然是一个不断探索的长期过程。在经济文化相对落后的国家建设社会主义，更具有历史长期性。第一，生产力发展状况的制约：在一个相当长的历史时期内，社会主义国家在经济上落后于发达资本主义国家，这就决定了必须把大力发展生产力作为根本任务，努力完成工业化和生产社会化、商品化、现代化的艰巨任务，需要很长时间的努力。第二，经济基础和上层建筑发展状况的制约：发展公有制经济、改造小农经济、建立巩固和完善社会主义经济基础是十分艰巨的任务；社会主义民主政治建设受到经济、政治、文化条件的严重制约，将是一个长期的过程。第三，国际环境的严峻挑战：社会主义国家尚处于强大的资本主义世界的包围之中，受到资本主义列强的遏制和扼杀，攻击方式由武力为主转变为以\"和平演变\"为主。第四，马克思主义执政党对社会主义发展道路的探索和对社会主义建设规律的认识，需要一个长期的过程。", "freq": 3, "years": ["19.10", "25.4单"], "paper": "押题卷（三）"}, {"id": "简35", "kind": "简答", "ch": "第四章 资本主义的本质及规律", "page": "P219-220", "q": "产业资本循环的三个阶段及其执行的职能", "qh": "产业资本的循环阶段及其执行的职能<span class=\"pg\">P219-220</span>", "o": "(1)<span class=\"rd\">购买阶段</span>：即生产资料和劳动力的购买阶段；属于商品的流通过程；执行<span class=\"rd\">货币资本</span>职能\n(2)<span class=\"rd\">生产阶段</span>：即生产资料与劳动力按比例结合在一起从事资本主义生产的阶段；生产资料与劳动者相结合生产物质财富并使生产资本得以增殖；执行<span class=\"rd\">生产资本</span>职能\n(3)<span class=\"rd\">售卖阶段</span>：即商品资本向货币资本的转化阶段；执行<span class=\"rd\">商品资本</span>职能，通过商品售卖要实现商品的价值，还要实现剩余价值", "a": "第一个阶段是购买阶段，即生产资料和劳动力的购买阶段，属于商品的流通过程，在这一阶段产业资本执行的是货币资本的职能；第二个阶段是生产阶段，即生产资料与劳动力按比例结合在一起从事资本主义生产的阶段，在这一阶段生产资料与劳动者相结合生产物质财富并使生产资本得以增殖，产业资本执行的是生产资本的职能；第三个阶段是售卖阶段，即商品资本向货币资本的转化阶段，在此阶段产业资本执行的是商品资本的职能，通过商品售卖不仅要实现商品的价值，还要实现剩余价值。产业资本的运动必须具备两个基本前提条件：产业资本的三种职能形式必须在空间上并存，在时间上继起。", "freq": 2, "years": ["18.4单", "20.10"], "paper": "押题卷（三）"}]}, {"name": "押题卷（四）", "items": [{"id": "单97", "kind": "单选", "ch": "第四章 资本主义的本质及规律", "page": "P208-209", "q": "劳动力商品的特点与资本", "qh": "劳动力商品的特点：<span class=\"pg\">P208-209</span>(1)具有价值和使用价值。劳动力的价值由生产、发展、维持和延续劳动力所必需的生活必需品的价值决定，包括：<span class=\"rd\">【维持劳动者本人生存所必需的生活资料的价值；维持劳动者家属的生存所必需的生活资料的价值；</span><span class=\"rd\">劳动者接受教育和训练所支出的费用】</span>。劳动力价值的构成包含<span class=\"rd\">【历史和道德的因素】</span>(2)它的使用价值是价值的源泉，在消费过程中<span class=\"rd\">【能够创造新的价值】</span>，而且这个新的价值比劳动力本身的价值更大。一旦货币购买的<span class=\"rd\">【劳动力】</span>带来剩余价值，货币也就变成了资本。资本是能够带来剩余价值的价值", "o": "", "a": "劳动力商品也具有价值和使用价值。劳动力的价值由生产、发展、维持和延续劳动力所必需的生活必需品的价值决定，包括三个部分：（1）维持劳动者本人生存所必需的生活资料的价值；（2）维持劳动者家属的生存所必需的生活资料的价值；（3）劳动者接受教育和训练所支出的费用；由于劳动力价值的构成包含历史和道德的因素，在不同的国家或在同一国家的不同历史时期，劳动者所必需的生活资料的数量和构成是有区别的。劳动力商品在使用价值上有一个很突出的特点，就是它的使用价值是价值的源泉，在消费过程中能够创造新的价值，而且这个新的价值比劳动力本身的价值更大。而一旦货币购买的劳动力带来剩余价值，货币也就变成了资本——资本是能够带来剩余价值的价值。", "freq": 3, "years": ["24.10", "25.4简"], "paper": "押题卷（四）"}, {"id": "单3", "kind": "单选", "ch": "导论", "page": "P7", "q": "世界上第一个无产阶级政党的党纲", "qh": "世界上第一个无产阶级政党(共产主义者同盟)的党纲——<span class=\"rd\">【《共产党宣言》】</span><span class=\"pg\">P7</span>", "o": "", "a": "马克思、恩格斯接受国际性工人组织\"正义者同盟\"的邀请，将其改组为\"共产主义者同盟\"，并为其起草了世界上第一个无产阶级政党的党纲——《共产党宣言》。1848年2月《共产党宣言》发表，标志着马克思主义的公开问世。", "freq": 2, "years": ["16.04", "20.10"], "paper": "押题卷（四）"}, {"id": "单133", "kind": "单选", "ch": "第六章 社会主义的发展及其规律", "page": "P289", "q": "十月革命与第一个社会主义国家", "qh": "1917年列宁领导的俄国十月革命胜利，建立起世界上第一个人民当家作主的社会主义国家--<span class=\"rd\">【苏维</span><span class=\"rd\">埃俄国】</span><span class=\"pg\">P289</span>", "o": "", "a": "列宁根据对俄国国内革命形势和国际状况的科学分析，得出了社会主义可能在经济文化相对落后的俄国首先取得胜利的结论，并领导了俄国十月革命。十月革命实现了社会主义从理想到现实的伟大飞跃，开辟了人类历史的新纪元。十月革命胜利后，年轻的苏维埃政权不仅面临着巩固政权的任务，而且面临着在经济文化相对落后的条件下建设社会主义的任务。列宁领导的苏维埃俄国对社会主义道路的探索，大体上经历了三个时期：进一步巩固苏维埃政权时期、战时共产主义时期、由战时共产主义转变为新经济政策时期。", "freq": 2, "years": ["16.10", "23.10"], "paper": "押题卷（四）"}, {"id": "单16", "kind": "单选", "ch": "第一章 世界的物质性及发展规律", "page": "P41-43", "q": "联系和发展的观点；发展的实质", "qh": "<span class=\"rd\">【联系和发展的观点】</span>是唯物辩证法的总观点、总特征。发展的实质是<span class=\"rd\">【新事物的产生和旧事物的灭</span><span class=\"rd\">亡】</span><span class=\"pg\">P41-43</span>", "o": "", "a": "联系和发展的观点是唯物辩证法的总观点、总特征。物质世界的发展特别是人类社会的发展，其实质是新事物的产生和旧事物的灭亡；新事物是指合乎历史前进方向、具有远大前途的东西。", "freq": 2, "years": ["17.04", "18.10"], "paper": "押题卷（四）"}, {"id": "单119", "kind": "单选", "ch": "第五章 资本主义的发展及其趋势", "page": "P241", "q": "资本主义发展的两个阶段", "qh": "资本主义的发展阶段：<span class=\"rd\">【自由竞争资本主义和垄断资本主义(19世纪末20世纪初形成)】</span><span class=\"pg\">P241</span>", "o": "", "a": "资本主义的发展经历了两个阶段：自由竞争资本主义和垄断资本主义。19世纪70年代以前，资本主义处于自由竞争阶段；从19世纪70年代开始，自由竞争资本主义逐步向垄断资本主义发展；19世纪末20世纪初，垄断代替自由竞争并占据统治地位，垄断资本主义得以形成。这一时期，垄断资本主义主要以私人垄断资本为基础，所以又叫私人垄断资本主义；私人垄断资本主义是在生产集中和资本集中的基础上形成的。", "freq": 2, "years": ["18.10", "2604单"], "paper": "押题卷（四）"}, {"id": "单86", "kind": "单选", "ch": "第四章 资本主义的本质及规律", "page": "P187-188", "q": "商品的二因素", "qh": "商品的二因素：<span class=\"rd\">【使用价值和价值】</span><span class=\"pg\">P187-188</span>(1)<span class=\"rd\">【使用价值】</span>指商品能满足人的某种需要的有用性，是商品的自然属性(2)<span class=\"rd\">【价值】</span>是凝结在商品中的无差别的一般人类劳动，是商品特有的社会属性(3)商品的使用价值和价值之间是对立统一的关系。对立性表现在<span class=\"rd\">【商品的使用价值和价值是相互排斥的，</span><span class=\"rd\">二者不可兼得】</span>。统一性表现在<span class=\"rd\">【商品同时具有使用价值和价值两个因素】</span>", "o": "", "a": "商品是用来交换、能满足人的某种需要的劳动产品，具有使用价值和价值两个因素或两种属性，是使用价值和价值的矛盾统一体。使用价值是指商品能满足人的某种需要的有用性，反映的是人与自然之间的物质关系，是商品的自然属性；价值是凝结在商品中的无差别的一般人类劳动，即人的脑力和体力的耗费，是商品特有的社会属性。商品的使用价值和价值之间是对立统一的关系：其对立性表现在，商品的使用价值和价值是相互排斥的，二者不可兼得；其统一性表现在，作为商品，必须同时具有使用价值和价值两个因素。", "freq": 2, "years": ["16.04", "25.4单"], "paper": "押题卷（四）"}, {"id": "单116", "kind": "单选", "ch": "第四章 资本主义的本质及规律", "page": "P231", "q": "资本主义国家的政权组织形式", "qh": "资本主义国家政权组织形式是<span class=\"rd\">【分权(包括立法权、行政权、司法权)制衡】</span>。立法权属于<span class=\"rd\">【国会】</span><span class=\"pg\">P231</span>", "o": "", "a": "资本主义国家政权采取分权制衡的组织形式，即国家的立法权、行政权、司法权分别由三个权力主体独立行使，形成各主体之间的\"制衡\"。以美国为例，在这种政权结构中，立法权属于由参、众两院组成的合众国国会，国会的立法权受到宪法保护和严格限制；行政权由行政首脑即总统来行使；司法权属于最高法院及下级法院，法院独立于总统和国会。", "freq": 2, "years": ["17.04", "25.10"], "paper": "押题卷（四）"}, {"id": "单23", "kind": "单选", "ch": "第一章 世界的物质性及发展规律", "page": "P58", "q": "矛盾分析方法居于核心地位", "qh": "<span class=\"rd\">【矛盾分析方法】</span>在唯物辩证法的方法论体系中居于核心地位，是认识事物的根本方法<span class=\"pg\">P58</span>", "o": "", "a": "矛盾分析方法是对立统一规律在方法论上的体现，在唯物辩证法的方法论体系中居于核心地位，是我们认识事物的根本方法；其核心要求是善于分析矛盾的特殊性，做到具体问题具体分析。", "freq": 2, "years": ["17.10", "18.4单"], "paper": "押题卷（四）"}, {"id": "单81", "kind": "单选", "ch": "第三章 人类社会及其发展规律", "page": "P172-174", "q": "唯物史观考察历史创造者的方法论原则", "qh": "唯物史观在考察历史创造者问题上坚持的方法论原则：<span class=\"rd\">【唯物史观立足于现实的人及其本质来把握历</span><span class=\"rd\">史的创造者；立足于整体的社会历史过程来探究谁是历史的创造者；从社会历史发展的必然性入手来考察</span><span class=\"rd\">和说明谁是历史的创造者；从人与历史关系的不同层次上考察谁是历史的创造者】</span><span class=\"pg\">P172-174</span>", "o": "", "a": "第一，立足于现实的人及其本质来把握历史的创造者；第二，立足于整体的社会历史过程来探究谁是历史的创造者；第三，从社会历史发展的必然性入手来考察和说明谁是历史的创造者；第四，从人与历史关系的不同层次上考察谁是历史的创造者。", "freq": 2, "years": ["19.04", "23.10"], "paper": "押题卷（四）"}, {"id": "单76", "kind": "单选", "ch": "第三章 人类社会及其发展规律", "page": "P159-160", "q": "阶级斗争是阶级社会发展的直接动力", "qh": "<span class=\"rd\">【阶级斗争】</span>是阶级社会发展的直接动力。阶级是一个<span class=\"rd\">【经济范畴、历史范畴】</span>。阶级斗争根源于阶级之间<span class=\"rd\">【物质利益的根本对立】</span><span class=\"pg\">P159-160</span>", "o": "", "a": "阶级是一个经济范畴，也是一个历史范畴。阶级斗争是阶级利益根本冲突的对抗阶级之间的对立和斗争，根源于阶级之间物质利益的根本对立，根源于社会经济关系的冲突。一切阶级斗争归根结底都是围绕经济利益这个轴心展开的。", "freq": 2, "years": ["20.08", "24.4单"], "paper": "押题卷（四）"}, {"id": "简23", "kind": "简答", "ch": "第三章 人类社会及其发展规律", "page": "P137-139", "q": "生产力与生产关系的关系及其矛盾运动规律的意义", "qh": "生产力与生产关系的关系及其矛盾运动规律的意义<span class=\"pg\">P137-139</span>", "o": "(1)关系：①<span class=\"rd\">生产力决定生产关系</span>。生产力是居支配地位、起决定作用的方面。生产力状况决定生产关系的性质；生产力的发展决定生产关系的改变。②<span class=\"rd\">生产关系对生产力具有能动的反作用</span>。当生产关系适合生产力发展的客观要求时，对生产力的发展起推动作用；当生产关系不适合生产力发展的客观要求时，就会阻碍生产力的发展\n(2)意义：①在人类思想史上彻底否定了单纯以道德作为评判历史功过是非标准的思想体系，<span class=\"rd\">第一次科学地</span><span class=\"rd\">确立了生产力发展是“社会进步的最高标准”，把生产力与生产关系矛盾运动的规律作为判断时代变革的</span><span class=\"rd\">客观依据</span>。②<span class=\"rd\">是马克思主义政党制定路线、方针和政策的重要依据</span>", "a": "①生产力决定生产关系：生产力状况决定生产关系的性质，生产力的发展决定生产关系的改变；②生产关系对生产力具有能动的反作用：适合时起推动作用，不适合时起阻碍作用。意义：第一次科学地确立了生产力发展是\"社会进步的最高标准\"，把生产力与生产关系矛盾运动的规律作为判断时代变革的客观依据；是马克思主义政党制定路线、方针和政策的重要依据。", "freq": 2, "years": ["20.08", "21.10"], "paper": "押题卷（四）"}, {"id": "简32", "kind": "简答", "ch": "第四章 资本主义的本质及规律", "page": "P208", "q": "劳动力成为商品的基本条件", "qh": "劳动力成为商品的条件<span class=\"pg\">P208</span>", "o": "(1)<span class=\"rd\">劳动者在法律上是自由人</span>，能够把自己的劳动力当作自己的商品来支配\n(2)<span class=\"rd\">劳动者没有任何生产资料，没有生活资料来源</span>，不得不依靠出卖劳动力为生", "a": "劳动力是指人的劳动能力，是人的脑力和体力的总和。劳动力成为商品，要具备两个基本条件：其一，劳动者在法律上是自由人，能够把自己的劳动力当作自己的商品来支配；其二，劳动者没有任何生产资料，没有生活资料来源，因而不得不依靠出卖劳动力为生。劳动力成为商品的两个条件是在封建社会后期发生的资本原始积累过程中逐渐形成的，劳动力成为商品标志着简单商品生产发展到资本主义商品生产的新阶段。", "freq": 2, "years": ["21.4单", "25.10"], "paper": "押题卷（四）"}, {"id": "简22", "kind": "简答", "ch": "第三章 人类社会及其发展规律", "page": "P129", "q": "物质生产方式是社会存在和发展的基础及决定力量", "qh": "为什么说物质生产方式是社会存在和发展的基础及决定力量(生产方式在社会发展中的作用)<span class=\"pg\">P129</span>", "o": "生产方式是社会历史发展的决定力量\n(1)它是人类社会赖以存在和发展的基础，是人类其他一切活动的首要前提\n(2)它决定社会的结构、性质和面貌，制约着人们的经济生活、政治生活和精神生活等全部社会生活\n(3)它的变化发展决定整个社会历史的变化发展，决定社会形态从低级向高级的更替和发展", "a": "（1）它是人类社会赖以存在和发展的基础，是人类其他一切活动的首要前提；（2）它决定社会的结构、性质和面貌，制约着人们的经济生活、政治生活和精神生活等全部社会生活；（3）它的变化发展决定整个社会历史的变化发展，决定社会形态从低级向高级的更替和发展。", "freq": 2, "years": ["17.04"], "paper": "押题卷（四）"}, {"id": "简42", "kind": "简答", "ch": "第五章 资本主义的发展及其趋势", "page": "P256-260", "q": "经济全球化的含义、表现、动因、影响", "qh": "经济全球化的含义、表现、动因、影响<span class=\"pg\">P256-260</span>", "o": "(1)含义：指在生产不断发展、科技加速进步、社会分工和国际分工不断深化、生产的社会化和国际化程度不断提高的情况下，<span class=\"rd\">世界各国、各地区的经济活动越来越超出某一国家和地区的范围而相互联系、相</span><span class=\"rd\">互依存的过程</span>\n(2)表现(内容)：<span class=\"rd\">生产全球化、贸易全球化、金融全球化</span>\n(3)动因：①从本质上讲，经济全球化是<span class=\"rd\">生产力发展和社会化大生产</span>的必然要求。②导致经济全球化迅猛发展的因素：<span class=\"rd\">科学技术的进步和生产力的发展</span>为经济全球化提供坚实的物质基础和根本的推动力；<span class=\"rd\">跨国公司的</span><span class=\"rd\">发展</span>为经济全球化提供适宜的企业组织形式；<span class=\"rd\">各国经济体制的变革和国际经济组织的发展</span>是经济全球化的体制与组织保障\n(4)经济全球化是一把双刃剑：①积极作用：资金、技术等生产要素可以在国际社会流动和优化配置，由此<span class=\"rd\">带来巨大的分工利益</span>，<span class=\"rd\">推动世界生产力的发展</span>。不仅发达国家从中受益，一些发展中国家在参与经济全球化进程中也得到了快速发展。对发展中国家的积极作用主要表现在：<span class=\"rd\">为发展中国家提供先进技术和管理经</span><span class=\"rd\">验</span>；为发展中国家<span class=\"rd\">提供更多的就业机会</span>；<span class=\"rd\">推动</span>发展中国家<span class=\"rd\">国际贸易的发展</span>；<span class=\"rd\">促进</span>发展中国家<span class=\"rd\">跨国公司的发</span><span class=\"rd\">展</span>。②负面影响：<span class=\"rd\">发达国家与发展中国家</span>在经济全球化进程中的<span class=\"rd\">地位和收益不平等、不平衡</span>；<span class=\"rd\">加剧了发展</span><span class=\"rd\">中国家资源短缺和环境污染</span>；一定程度上<span class=\"rd\">增加了经济风险</span>", "a": "（含义）经济全球化是指在生产不断发展、科技加速进步、社会分工和国际分工不断深化、生产的社会化和国际化程度不断提高的情况下，世界各国、各地区的经济活动越来越超出某一国家和地区的范围而相互联系、相互依存的过程。（表现）第一，生产全球化；第二，贸易全球化；第三，金融全球化。（动因）从本质上讲，经济全球化是生产力发展和社会化大生产的必然要求；导致经济全球化迅猛发展的因素主要有三点：一是科学技术的进步和生产力的发展为经济全球化提供了坚实的物质基础和根本的推动力；二是跨国公司的发展为经济全球化提供了适宜的企业组织形式；三是各国经济体制的变革和国际经济组织的发展是经济全球化的体制与组织保障。（影响）经济全球化是一把\"双刃剑\"：一方面，社会分工得以在更大的范围内进行，资金、技术等生产要素可以在国际社会流动和优化配置，由此带来巨大的分工利益，推动世界生产力的发展，不仅发达国家从中受益，一些发展中国家在参与经济全球化进程中也得到了快速发展（为发展中国家提供先进技术和管理经验、更多的就业机会，推动发展中国家国际贸易和跨国公司的发展）；另一方面，发达国家与发展中国家在经济全球化进程中的地位和收益不平等、不平衡，加剧了发展中国家的资源短缺和环境污染，并增加全球经济发展的不稳定性和经济风险。", "freq": 2, "years": ["17.10"], "paper": "押题卷（四）"}]}, {"name": "押题卷（五）", "items": [{"id": "单1", "kind": "单选", "ch": "导论", "page": "P4", "q": "马克思主义产生于19世纪40年代", "qh": "马克思主义产生于<span class=\"rd\">【19世纪40年代】</span><span class=\"pg\">P4</span>", "o": "", "a": "马克思主义产生于19世纪40年代，创始人是马克思和恩格斯。马克思主义的产生具有深刻的社会根源、阶级基础和思想渊源。", "freq": 2, "years": ["21.10", "24.4单"], "paper": "押题卷（五）"}, {"id": "单52", "kind": "单选", "ch": "第三章 人类社会及其发展规律", "page": "P126", "q": "两种根本对立的历史观", "qh": "两种根本对立的历史观<span class=\"pg\">P126</span>(1)<span class=\"rd\">【唯心史观】</span>。从社会意识决定社会存在的前提出发，把社会历史看成精神发展史(2)<span class=\"rd\">【唯物史观】</span>。认为是人们的社会存在决定人们的意识", "o": "", "a": "唯心史观从社会意识决定社会存在的前提出发，把社会历史看成精神发展史；唯物史观认为不是人们的意识决定人们的存在，而是人们的社会存在决定人们的意识。", "freq": 2, "years": ["21.10", "25.10"], "paper": "押题卷（五）"}, {"id": "单88", "kind": "单选", "ch": "第四章 资本主义的本质及规律", "page": "P190", "q": "商品价值量与劳动生产率", "qh": "商品的价值量与生产商品所耗费的社会必要劳动时间成正比，与劳动生产率<span class=\"rd\">【成反比】</span><span class=\"pg\">P190</span>", "o": "", "a": "决定商品价值量的不是生产商品的个别劳动时间，而是社会必要劳动时间。劳动生产率水平越高，单位时间内生产的商品数量越多，生产每件商品所需要的社会必要劳动时间就越少，单位商品的价值量就越小，反之就越大。商品的价值量与生产商品所耗费的社会必要劳动时间成正比，与劳动生产率成反比。", "freq": 2, "years": ["21.10", "21.4单"], "paper": "押题卷（五）"}, {"id": "单126", "kind": "单选", "ch": "第五章 资本主义的发展及其趋势", "page": "P251-252", "q": "垄断资本向世界范围扩展", "qh": "垄断资本向世界范围扩展<span class=\"pg\">P251-252</span>(1)是通过<span class=\"rd\">【跨国公司】</span>实现的(2)经济动因：<span class=\"rd\">【将国内过剩的资本输出，以便在国外谋求高额利润；将部分非要害的技术转移到国外，以</span><span class=\"rd\">取得在别国的垄断优势，攫取高额垄断利润；争夺商品销售市场；确保原材料和能源的可靠来源】</span>(3)基本形式有<span class=\"rd\">【借贷资本输出、生产资本输出、商品资本输出】</span>", "o": "", "a": "垄断资本向世界范围扩展的主要经济动因是：首先，将国内过剩的资本输出，以便在国外谋求高额利润；其次，将部分非要害的技术转移到国外，以取得在别国的垄断优势，攫取高额垄断利润；再次，争夺商品销售市场；最后，确保原材料和能源的可靠来源。扩展的基本形式有三种：借贷资本输出、生产资本输出（在国外直接投资，独立创办企业，与国外资本合营，或收购国外已有的企业）、商品资本输出。垄断资本向世界范围的扩展是通过跨国公司这一国际垄断组织形式实现的。", "freq": 2, "years": ["24.4单", "2604单"], "paper": "押题卷（五）"}, {"id": "单140", "kind": "单选", "ch": "第七章 共产主义崇高理想及其最终实现", "page": "P351-352", "q": "共产主义远大理想与中国特色社会主义共同理想的关系", "qh": "共产主义远大理想和中国特色社会主义共同理想的关系<span class=\"pg\">P351-352</span>(1)从时间上看，远大理想与共同理想的关系是<span class=\"rd\">【最终理想与阶段性理想】</span>的关系(2)从层次上看，远大理想与共同理想的关系是<span class=\"rd\">【最高纲领与最低纲领】</span>的关系(3)从范围上看，远大理想与共同理想的关系也是<span class=\"rd\">【全人类理想与全体中国人民理想】</span>的关系", "o": "", "a": "首先，从时间上看，远大理想与共同理想的关系是最终理想与阶段性理想的关系（共产主义远大理想也就是我们的最终理想，它的实现需要许多代人的接续奋斗）。其次，从层次上看，远大理想与共同理想的关系是最高纲领与最低纲领的关系（坚定中国特色社会主义共同理想，进一步推进中国特色社会主义事业，就是我们党的最低纲领在当前的要求）。再次，从范围上看，远大理想与共同理想的关系也是全人类理想与全体中国人民理想的关系。习近平明确指出：\"中国特色社会主义是党的最高纲领和基本纲领的统一。\"", "freq": 2, "years": ["16.04"], "paper": "押题卷（五）"}, {"id": "单35", "kind": "单选", "ch": "第二章 实践与认识及其发展规律", "page": "P84", "q": "认识的两次飞跃", "qh": "人们认识一定事物的过程，是一个<span class=\"rd\">【从实践到认识(是第一次飞跃，表现为从感性认识到理性认识)，</span><span class=\"rd\">再从认识到实践(第二次飞跃)】</span>的过程<span class=\"pg\">P84</span>", "o": "", "a": "人们认识一定事物的过程，是一个从实践到认识（第一次飞跃，表现为在实践基础上由感性认识能动地飞跃到理性认识），再从认识到实践（第二次飞跃）的过程。", "freq": 2, "years": ["17.04"], "paper": "押题卷（五）"}, {"id": "单137", "kind": "单选", "ch": "第七章 共产主义崇高理想及其最终实现", "page": "P344-345", "q": "实现共产主义是人类最伟大的事业", "qh": "实现共产主义是人类最伟大的事业<span class=\"pg\">P344-345</span>(1)<span class=\"rd\">【实现共产主义理想】</span>是广大人民群众的共同愿望(2)实现共产主义，必须找到现实的阶级力量，这就是现代工人阶级或无产阶级(3)<span class=\"rd\">【无产阶级的解放与全人类的解放是完全一致的】</span>", "o": "", "a": "（二）实现共产主义是人类最伟大的事业。实现共产主义理想是广大人民群众的共同愿望；实现共产主义，必须找到现实的阶级力量，这就是现代工人阶级或无产阶级；无产阶级的解放与全人类的解放是完全一致的。", "freq": 2, "years": ["18.4简"], "paper": "押题卷（五）"}, {"id": "单75", "kind": "单选", "ch": "第三章 人类社会及其发展规律", "page": "P157-159", "q": "社会主要矛盾的转化原理", "qh": "社会主要矛盾的转化原理<span class=\"pg\">P157-159</span>(1)转化原理：社会主要矛盾不是一成不变的，在一定条件下会朝着两个方面转化：<span class=\"rd\">【一是社会主要矛盾双</span><span class=\"rd\">方的内容发生一定变化；二是矛盾地位发生变化，原来的主要矛盾转化为从属地位的矛盾，而原来的某个</span><span class=\"rd\">非主要矛盾则上升为占支配地位的主要矛盾】</span>。由于社会主要矛盾发生变化，它所影响的社会发展过程也发生变化，主要表现为社会发展过程中出现新的阶段性特点(2)其实践意义：当正确把握社会主要矛盾时，社会主义建设事业会朝着正确方向发展。我国社会主要矛盾已经转化为<span class=\"rd\">【人民日益增长的美好生活需要和不平衡不充分的发展】</span>之间的矛盾。抓住这一主要矛盾，就找到正确理解和把握新时代的钥匙。我们要紧紧扭住这一主要矛盾不放，不断推进我国经济社会发展", "o": "", "a": "社会主要矛盾不是一成不变的，在一定条件下会朝着两个方面转化：一是社会主要矛盾双方的内容发生一定变化；二是矛盾地位发生变化，原来的主要矛盾转化为从属地位的矛盾，而原来的某个非主要矛盾则上升为主要矛盾。我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾，抓住这一主要矛盾就找到了正确理解和把握新时代的钥匙。", "freq": 2, "years": ["23.10"], "paper": "押题卷（五）"}, {"id": "单136", "kind": "单选", "ch": "第六章 社会主义的发展及其规律", "page": "P300-302", "q": "无产阶级革命的根本问题、公有制的地位、按劳分配的原因", "qh": "无产阶级革命是以政治革命为核心的社会革命，其根本问题是<span class=\"rd\">【国家政权问题】</span>。<span class=\"rd\">【生产资料公有制】</span>是社会主义经济制度的根基。社会主义社会实行按劳分配制度的原因：<span class=\"rd\">【社会主义社会生产力的发展还不</span><span class=\"rd\">够充分，还存在旧的社会分工，存在脑力劳动和体力劳动的差别，劳动还是谋生的手段】</span><span class=\"pg\">P300-302</span>", "o": "", "a": "无产阶级革命是以政治革命为核心的社会革命，其根本问题是国家政权问题。社会主义社会必须坚持生产资料公有制，生产资料公有制是社会主义经济制度的根基，社会主义国家任何时候都不能放弃。社会主义社会要实行按劳分配的制度，但由于社会主义社会生产力的发展还不够充分，还存在旧的社会分工，存在脑力劳动和体力劳动的差别，劳动还是谋生的手段，因而个人消费品的分配还不能实行按需分配，而只能实行按劳分配，即等量劳动领取等量产品。", "freq": 2, "years": ["24.10"], "paper": "押题卷（五）"}, {"id": "单19", "kind": "单选", "ch": "第一章 世界的物质性及发展规律", "page": "P50", "q": "否定之否定规律的基本内容", "qh": "否定之否定规律的基本内容：事物的辩证否定不是一次完成的，而是经历<span class=\"rd\">【事物自我发展的两次否定，</span><span class=\"rd\">三个阶段，即“肯定—否定—否定之否定”】</span>的有规律的过程。事物的发展呈现出周期性，不同周期的交替使事物的发展呈现出波浪式前进或螺旋式上升的总趋势<span class=\"pg\">P50</span>", "o": "", "a": "事物的辩证否定经历事物自我发展的两次否定、三个阶段，即\"肯定—否定—否定之否定\"。事物的发展呈现出周期性，不同周期的交替使事物的发展呈现出波浪式前进或螺旋式上升的总趋势。", "freq": 2, "years": ["24.10"], "paper": "押题卷（五）"}, {"id": "简6", "kind": "简答", "ch": "第一章 世界的物质性及发展规律", "page": "P44", "q": "对立统一规律是唯物辩证法的实质和核心", "qh": "简述对立统一规律是唯物辩证法的实质和核心<span class=\"pg\">P44</span>", "o": "(1)对立统一规律揭示了事物普遍联系的根本内容和变化发展的内在动力，从根本上回答了事物为什么会发展的问题\n(2)是贯穿量变质变规律、否定之否定规律以及唯物辩证法基本范畴的中心线索，也是理解这些规律的“钥匙”\n(3)提供了人们认识世界和改造世界的根本方法——矛盾分析方法", "a": "（1）揭示了事物普遍联系的根本内容和变化发展的内在动力，从根本上回答了事物为什么会发展的问题；（2）是贯穿量变质变规律、否定之否定规律以及唯物辩证法基本范畴的中心线索，是理解这些规律的\"钥匙\"；（3）提供了人们认识世界和改造世界的根本方法——矛盾分析方法。", "freq": 2, "years": ["21.10"], "paper": "押题卷（五）"}, {"id": "简41", "kind": "简答", "ch": "第五章 资本主义的发展及其趋势", "page": "P252-253", "q": "垄断资本向世界范围扩展的社会经济后果", "qh": "垄断资本向世界范围扩展(资本输出)对输出国及输入国产生的社会经济后果<span class=\"pg\">P252-253</span>", "o": "(1)对于资本输出国：资本输出为其<span class=\"rd\">带来巨额利润</span>，加速资本积累，增强垄断资本的实力；<span class=\"rd\">带动和扩大</span><span class=\"rd\">商品输出</span>，巩固和扩大垄断资本的销售市场和投资场所；<span class=\"rd\">对发展中国家的经济命脉形成控制</span>，进一步巩固和扩大垄断优势地位。在资本输出中，<span class=\"rd\">资本输出国可能出现产业空心化，资本输出国与发展中国家和其他</span><span class=\"rd\">发达国家之间的矛盾会加深</span>，但是这些都不能改变垄断资本通过资本输出攫取巨大利益和扩大垄断实力的实质\n(2)对于资本输入国(主要是发展中国家)：①积极作用：主要是<span class=\"rd\">吸收</span>经济发展所需要的<span class=\"rd\">资金</span>，<span class=\"rd\">为经济发展提</span><span class=\"rd\">供条件</span>；<span class=\"rd\">引进</span>比较先进的机器<span class=\"rd\">设备和</span>工艺<span class=\"rd\">技术</span>，培训一批适应现代化生产需要的技术人员、熟练工人和经营管理人员；<span class=\"rd\">利用外资和技术</span>，建立一批现代工业，改造老企业和旧设备，<span class=\"rd\">优化产业结构</span>；<span class=\"rd\">利用外资扩大</span><span class=\"rd\">生产</span>，增加产品产量，提高产品质量，扩大出口，<span class=\"rd\">促进对外贸易的发展</span>；<span class=\"rd\">推动经济的发展</span>，增加就业机会，<span class=\"rd\">提高收入水平</span>。②不利影响：主要是<span class=\"rd\">付出较大的经济代价以及环境污染、能源资源消耗的代价</span>；<span class=\"rd\">产业调整</span><span class=\"rd\">和布局</span>有可能<span class=\"rd\">受制于外资的投资战略</span>；外来资本和跨国公司投资增加，<span class=\"rd\">冲击本国的民族工业</span>，并<span class=\"rd\">影响到国</span><span class=\"rd\">民经济的控制权</span>；<span class=\"rd\">债务负担加重</span>，影响经济的持续稳定发展；<span class=\"rd\">对国际资本的依赖性增强</span>，容易受到国际经济波动的影响", "a": "对于资本输出国来讲，资本输出为其带来了巨额利润，加速了资本积累，增强了垄断资本的实力；带动和扩大了商品输出，巩固和扩大了垄断资本的销售市场和投资场所；对发展中国家的经济命脉形成控制，进一步巩固和扩大了垄断优势地位。在资本输出过程中，资本输出国可能出现产业空心化，资本输出国与发展中国家和其他发达国家之间的矛盾会加深，但是这些都不能改变垄断资本通过资本输出攫取巨大利益和扩大垄断实力的实质。对于资本输入国（主要是发展中国家）而言，积极作用主要是：吸收经济发展所需要的资金，为经济发展提供条件；引进比较先进的机器设备和工艺技术，培训一批适应现代化生产需要的技术人员、熟练工人和经营管理人员；利用外资和技术，建立一批现代工业，改造老企业和旧设备，优化产业结构；利用外资扩大生产，增加产品产量，提高产品质量，扩大出口。不利影响主要是：付出了较大的经济代价以及环境污染、能源资源消耗的代价；产业调整和布局有可能受制于外资的投资战略；外来资本和跨国公司投资增加，冲击本国的民族工业，并影响到国民经济的控制权；债务负担加重，影响经济的持续稳定发展；对国际资本的依赖性增强，容易受到国际经济波动的影响。", "freq": 2, "years": ["21.4简"], "paper": "押题卷（五）"}, {"id": "简33", "kind": "简答", "ch": "第四章 资本主义的本质及规律", "page": "P211-212", "q": "不变资本与可变资本的划分及其意义", "qh": "不变资本和可变资本的划分及其意义<span class=\"pg\">P211-212</span>", "o": "(1)根据资本在剩余价值生产中所起的不同作用，资本分为\n①<span class=\"rd\">不变资本</span>：是以生产资料形态存在的资本\n②<span class=\"rd\">可变资本</span>：是用来购买劳动力的那部分资本\n(2)划分的意义：<span class=\"rd\">进一步揭示了剩余价值的源泉；雇佣劳动者的剩余劳动是剩余价值的唯一源泉；为确定资</span><span class=\"rd\">本家对雇佣劳动者的剥削程度提供了科学依据</span>", "a": "根据资本在剩余价值生产中所起的不同作用，可以将资本划分为不变资本与可变资本。不变资本（c）是以生产资料形态存在的资本，在生产过程中只转移自己的价值量，不发生增殖；可变资本（v）是用来购买劳动力的那部分资本，其价值在生产过程中不是被转移到新产品中去，而是由工人的劳动再生产出来，是一个可变的量。划分的意义：把资本划分为不变资本和可变资本，进一步揭示了剩余价值的源泉——剩余价值既不是由全部资本创造的，也不是由不变资本创造的，而是由可变资本雇佣的劳动者创造的，雇佣劳动者的剩余劳动是剩余价值的唯一源泉；同时，为确定资本家对雇佣劳动者的剥削程度提供了科学依据（应拿剩余价值同可变资本相比，而不是同全部资本相比）。", "freq": 2, "years": ["23.10"], "paper": "押题卷（五）"}, {"id": "简10", "kind": "简答", "ch": "第一章 世界的物质性及发展规律", "page": "P49-50", "q": "唯物辩证法的否定观及其指导意义", "qh": "唯物辩证法的否定观的内容及其指导意义<span class=\"pg\">P49-50</span>", "o": "(1)内容：①<span class=\"rd\">否定是事物的自我否定、自我发展，是事物内部矛盾运动的结果</span>\n②<span class=\"rd\">否定是事物发展的环节</span>，是旧事物向新事物的转变，是从旧质到新质的飞跃\n③<span class=\"rd\">否定是新旧事物联系的环节</span>，新事物孕育产生于旧事物，新旧事物是通过否定环节联系起来的\n④<span class=\"rd\">辩证否定的实质是扬弃</span>，即新事物对旧事物既批判又继承，既克服其消极因素又保留其积极因素\n(2)意义：要求对待一切事物都要<span class=\"rd\">采取科学分析的态度，既要把握住现存状态又要把握住发展趋向，反对简</span><span class=\"rd\">单地肯定一切或否定一切</span>。例如，对于中华优秀传统文化，既要注重传承又要根据时代要求实现创造性转化和创新性发展。对于其他民族的文化成果，既不照搬也不一概排斥，而要批判地吸收其合理的因素，为我所用", "a": "（1）否定是事物的自我否定、自我发展，是事物内部矛盾运动的结果；（2）否定是事物发展的环节，是旧事物向新事物的转变，是从旧质到新质的飞跃；（3）否定是新旧事物联系的环节；（4）辩证否定的实质是\"扬弃\"，即既批判又继承，既克服消极因素又保留积极因素。意义：要求对一切事物采取科学分析的态度，反对简单地肯定一切或否定一切。", "freq": 2, "years": ["23.4简"], "paper": "押题卷（五）"}]}];
